import nodeForge from 'node-forge';
const { pki, md: mdHash, util } = nodeForge;
import type { pki as PkiTypes } from 'node-forge';
import { ProjectIdError, ERROR_MESSAGES } from '../errors';
import { getWindow } from '../index';
import type { EndUserData } from '../types/user';

import { logger } from '../utils/logger';
interface Storage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

class AuthService {
  private static instance: AuthService;
  private storage: Storage | null = null;
  private privateKey: PkiTypes.rsa.PrivateKey | null = null;
  private publicKeyRaw: string | null = null;
  private sessionId: string | null = null;
  private projectId: string | null = null;
  private apiUrl: string = 'https://api.pointer.so';
  private isInitialized = false;
  private initializationPromise: Promise<void> | null = null;
  private worker: Worker | null = null;
  private userData: EndUserData | null = null;

  private constructor() {}

  public static getInstance(): AuthService {
    if (!AuthService.instance) {
      AuthService.instance = new AuthService();
    }
    return AuthService.instance;
  }

  public async initialize(projectId: string, storage: Storage, apiUrl?: string): Promise<void> {
    if (this.initializationPromise) {
      return this.initializationPromise;
    }

    this.initializationPromise = this.deferredInitialize(projectId, storage, apiUrl);
    return this.initializationPromise;
  }

  private async deferredInitialize(
    projectId: string,
    storage: Storage,
    apiUrl?: string,
  ): Promise<void> {
    try {
      this.projectId = projectId;
      this.storage = storage;
      if (apiUrl) {
        this.apiUrl = apiUrl;
      }

      // Load or generate keys with lower priority
      await new Promise(resolve => setTimeout(resolve, 0));
      await this.loadOrGenerateKeyPair();

      this.isInitialized = true;
    } catch (error) {
      logger.error('Auth service initialization failed:', error);
      this.initializationPromise = null;
      throw error;
    }
  }

  private async generateKeysInWorker(): Promise<{ privateKey: string; publicKey: string }> {
    return new Promise((resolve, reject) => {
      const win = getWindow();
      if (!win) {
        reject(new Error('Window not available'));
        return;
      }

      try {
        // Check if Worker API is available
        if (typeof Worker === 'undefined') {
          reject(new Error('Web Worker API not available'));
          return;
        }

        // Use a preloaded script rather than inline code
        // This approach works better with strict CSP policies
        const workerScript = `
          // Ensure forge library loads properly
          try {
            importScripts('https://cdn.jsdelivr.net/npm/node-forge@1.3.1/dist/forge.min.js');
          } catch (e) {
            self.postMessage({
              success: false,
              error: 'Failed to import forge library: ' + (e.message || e),
            });
            return;
          }
          
          self.onmessage = async () => {
            try {
              // Generate keys with less intensive settings if needed
              const keypair = forge.pki.rsa.generateKeyPair({ bits: 2048, workers: -1 });
              const privateKeyPem = forge.pki.privateKeyToPem(keypair.privateKey);
              const publicKeyPem = forge.pki.publicKeyToPem(keypair.publicKey);

              self.postMessage({
                success: true,
                privateKey: privateKeyPem,
                publicKey: publicKeyPem
                  .replace(/-----(BEGIN|END) PUBLIC KEY-----/g, '')
                  .replace(/[\n\r]/g, '')
                  .trim(),
              });
            } catch (error) {
              self.postMessage({
                success: false,
                error: error instanceof Error ? error.message : String(error),
              });
            }
          };
        `;

        // Use a try-catch for blob creation which can fail in some environments
        let blob, workerUrl;
        try {
          // Create a blob containing the worker code
          blob = new Blob([workerScript], { type: 'application/javascript' });
          workerUrl = URL.createObjectURL(blob);
        } catch (e) {
          reject(new Error(`Failed to create worker blob: ${(e as Error).message}`));
          return;
        }

        // Create the worker with error handling
        try {
          this.worker = new Worker(workerUrl);
        } catch (e) {
          URL.revokeObjectURL(workerUrl);
          reject(new Error(`Failed to create worker: ${(e as Error).message}`));
          return;
        }

        // Set a timeout to prevent hanging if the worker never responds
        const timeoutId = setTimeout(() => {
          logger.debug('Auth Service: Worker key generation timed out after 15 seconds');
          if (this.worker) {
            this.worker.terminate();
            this.worker = null;
          }
          if (workerUrl) {
            URL.revokeObjectURL(workerUrl);
          }
          reject(new Error('Key generation in worker timed out'));
        }, 15000);

        this.worker.onmessage = e => {
          clearTimeout(timeoutId);
          if (e.data.success) {
            // Clean up the blob URL after worker is initialized
            URL.revokeObjectURL(workerUrl);
            resolve({
              privateKey: e.data.privateKey,
              publicKey: e.data.publicKey,
            });
          } else {
            reject(new Error(e.data.error || 'Unknown worker error'));
          }
          this.worker?.terminate();
          this.worker = null;
        };

        this.worker.onerror = (error: ErrorEvent) => {
          clearTimeout(timeoutId);
          // Clean up the blob URL on error
          URL.revokeObjectURL(workerUrl);
          reject(new Error(`Worker error: ${error.message || 'Unknown worker error'}`));
          this.worker?.terminate();
          this.worker = null;
        };

        // Send message to start key generation
        this.worker.postMessage('generate');
      } catch (error) {
        logger.debug(
          'Auth Service: Failed to set up worker: ' + ((error as Error).message || error),
        );
        reject(error);
      }
    });
  }

  private async loadOrGenerateKeyPair(): Promise<void> {
    if (!this.storage) {
      throw new Error('Storage not initialized');
    }

    // Try to load from storage first
    const storedKeys = this.storage.getItem('pointer_keypair');
    if (storedKeys) {
      try {
        const { privateKey, publicKey } = JSON.parse(storedKeys);
        this.privateKey = pki.privateKeyFromPem(privateKey);
        this.publicKeyRaw = publicKey;
        logger.debug('Auth Service: Loaded existing keypair');
        return;
      } catch (error) {
        logger.debug('Auth Service: Failed to load stored keys, generating new ones');
      }
    }

    // Generate new keys if not found in storage
    logger.debug('Auth Service: Generating new keypair');
    try {
      logger.debug('Auth Service: Attempting to generate keys in worker thread');
      const { privateKey, publicKey } = await this.generateKeysInWorker();
      this.privateKey = pki.privateKeyFromPem(privateKey);
      this.publicKeyRaw = publicKey;

      // Store in storage for future use
      try {
        this.storage.setItem(
          'pointer_keypair',
          JSON.stringify({
            privateKey,
            publicKey,
          }),
        );
        logger.debug('Auth Service: Successfully stored new keypair');
      } catch (error) {
        logger.debug('Auth Service: Failed to store keypair');
      }
    } catch (error) {
      // Provide a helpful diagnostic message with the specific error
      logger.warn(
        `🎯 Auth Service: Failed to generate keypair in worker, falling back to main thread. Error: ${(error as Error).message || 'Unknown error'}`,
      );

      // Log a more user-friendly explanation
      logger.debug(
        'This is not critical - just means key generation will happen on the main thread, which might cause a slight UI delay.',
      );

      // Fallback to synchronous generation if worker fails
      const keypair = pki.rsa.generateKeyPair({ bits: 2048 });
      this.privateKey = keypair.privateKey;
      const pem = pki.publicKeyToPem(keypair.publicKey);
      this.publicKeyRaw = pem
        .replace(/-----(BEGIN|END) PUBLIC KEY-----/g, '')
        .replace(/[\n\r]/g, '')
        .trim();

      // Also store the fallback keypair
      try {
        this.storage.setItem(
          'pointer_keypair',
          JSON.stringify({
            privateKey: pki.privateKeyToPem(this.privateKey),
            publicKey: this.publicKeyRaw,
          }),
        );
        logger.debug('Auth Service: Stored fallback keypair generated on main thread');
      } catch (storageError) {
        logger.debug('Auth Service: Failed to store fallback keypair');
      }
    }
  }

  public setSessionId(sessionId: string): void {
    this.sessionId = sessionId;
  }

  public getSessionId(): string | null {
    return this.sessionId;
  }

  public getProjectId(): string | null {
    return this.projectId;
  }

  public getApiUrl(): string {
    return this.apiUrl;
  }

  public isReady(): boolean {
    return this.isInitialized && !!this.privateKey && !!this.publicKeyRaw;
  }

  private async ensureKeys(): Promise<void> {
    if (!this.isInitialized) {
      throw new Error('Auth service not initialized');
    }
    if (!this.privateKey || !this.publicKeyRaw) {
      await this.loadOrGenerateKeyPair();
    }
  }

  public async getPublicKeyPem(): Promise<string> {
    await this.ensureKeys();
    if (!this.publicKeyRaw) {
      throw new Error('Public key not generated');
    }
    return `-----BEGIN PUBLIC KEY-----\n${this.publicKeyRaw}\n-----END PUBLIC KEY-----`;
  }

  public async getEncodedPublicKey(): Promise<string> {
    return btoa(await this.getPublicKeyPem());
  }

  public async createSignature(
    timestamp: number,
    body: Record<string, unknown> = {},
  ): Promise<string> {
    await this.ensureKeys();
    if (!this.privateKey) {
      throw new Error('Cannot create signature without private key');
    }

    // Only include session ID in signature if we have one
    const message = this.sessionId
      ? `${timestamp}:${this.sessionId}:${JSON.stringify(body)}`
      : `${timestamp}::${JSON.stringify(body)}`;

    const md = mdHash.sha256.create();
    md.update(message, 'utf8');
    const signature = this.privateKey.sign(md, 'RSASSA-PKCS1-V1_5');
    return util.encode64(signature);
  }

  public async getAuthHeaders(body: Record<string, unknown> = {}): Promise<Record<string, string>> {
    if (!this.projectId) {
      throw new ProjectIdError(ERROR_MESSAGES.INVALID_PROJECT_ID);
    }

    if (!this.isReady()) {
      throw new Error('Auth service not ready');
    }

    const timestamp = Date.now();
    const [encodedPublicKey, signature] = await Promise.all([
      this.getEncodedPublicKey(),
      this.createSignature(timestamp, body),
    ]);

    // Only include session ID in headers if we have one
    const headers: Record<string, string> = {
      'X-PROJECT-ID': this.projectId,
      'X-CLIENT-PUBLIC-KEY': encodedPublicKey,
      'X-REQUEST-TIMESTAMP': timestamp.toString(),
      'X-REQUEST-SIGNATURE': signature,
    };

    if (this.sessionId) {
      headers['X-SESSION-ID'] = this.sessionId;
    }

    // Add user data to headers if available
    const userData = this.getUserData();
    if (userData && userData.userId) {
      headers['X-END-USER-ID'] = userData.userId;

      if (userData.email) {
        headers['X-END-USER-EMAIL'] = userData.email;
      }

      if (userData.name) {
        headers['X-END-USER-NAME'] = userData.name;
      }

      if (userData.avatarUrl) {
        headers['X-END-USER-AVATAR'] = userData.avatarUrl;
      }

      if (userData.hmacSignature) {
        headers['X-END-USER-HMAC'] = userData.hmacSignature;
      }

      if (userData.customData) {
        headers['X-END-USER-CUSTOM-DATA'] = JSON.stringify(userData.customData);
      }
    }

    return headers;
  }

  public async reset(): Promise<void> {
    this.privateKey = null;
    this.publicKeyRaw = null;
    this.sessionId = null;
    this.isInitialized = false;
    if (this.storage) {
      this.storage.removeItem('pointer_keypair');
      await this.loadOrGenerateKeyPair();
      this.isInitialized = true;
    }
  }

  // User data management methods
  public setUserData(userData: EndUserData): void {
    if (!userData.userId) {
      throw new Error('userId is required');
    }

    this.userData = userData;

    // Store sanitized user data in storage if available
    if (this.storage) {
      try {
        const { hmacSignature, ...storableData } = userData;
        this.storage.setItem('pointer_user_data', JSON.stringify(storableData));
      } catch (error) {
        logger.debug('Failed to store user data:', error);
      }
    }

    logger.debug('User data set:', {
      userId: userData.userId,
      hasEmail: !!userData.email,
      hasName: !!userData.name,
      hasAvatar: !!userData.avatarUrl,
      hasHMAC: !!userData.hmacSignature,
      hasCustomData: !!userData.customData,
    });
  }

  public getUserData(): EndUserData | null {
    // If we have in-memory data, use that
    if (this.userData) {
      return this.userData;
    }

    // Try to load from storage
    if (this.storage) {
      try {
        const storedData = this.storage.getItem('pointer_user_data');
        if (storedData) {
          this.userData = JSON.parse(storedData);
          return this.userData;
        }
      } catch (error) {
        logger.debug('Failed to load user data from storage:', error);
      }
    }

    return null;
  }

  public clearUserData(): void {
    this.userData = null;
    if (this.storage) {
      try {
        this.storage.removeItem('pointer_user_data');
      } catch (error) {
        logger.debug('Failed to clear user data from storage:', error);
      }
    }
  }
}

export const authService = AuthService.getInstance();
