import { useState, useRef, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import styles from './Tooltip.module.css';
import { getDocument, getWindow } from '@/sdk';

export interface TooltipProps {
  content: React.ReactNode;
  children: React.ReactNode;
  side?: 'top' | 'right' | 'bottom' | 'left';
  align?: 'start' | 'center' | 'end';
  delayMs?: number;
}

export const Tooltip: React.FC<TooltipProps> = ({
  content,
  children,
  side = 'top',
  align = 'center',
  delayMs = 200,
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const triggerRef = useRef<HTMLDivElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);
  const timeoutRef = useRef<NodeJS.Timeout>();

  const showTooltip = () => {
    timeoutRef.current = setTimeout(() => {
      setIsVisible(true);
    }, delayMs);
  };

  const hideTooltip = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    setIsVisible(false);
  };

  const updatePosition = useCallback(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;

    if (!triggerRef.current || !tooltipRef.current) return;

    const triggerRect = triggerRef.current.getBoundingClientRect();
    const tooltipRect = tooltipRef.current.getBoundingClientRect();

    let top = 0;
    let left = 0;

    switch (side) {
      case 'top':
        top = triggerRect.top - tooltipRect.height - 4;
        break;
      case 'bottom':
        top = triggerRect.bottom + 4;
        break;
      case 'left':
        left = triggerRect.left - tooltipRect.width - 4;
        top = triggerRect.top;
        break;
      case 'right':
        left = triggerRect.right + 4;
        top = triggerRect.top;
        break;
    }

    switch (align) {
      case 'start':
        left = side === 'top' || side === 'bottom' ? triggerRect.left : left;
        break;
      case 'center':
        left =
          side === 'top' || side === 'bottom'
            ? triggerRect.left + triggerRect.width / 2 - tooltipRect.width / 2
            : left;
        top =
          side === 'left' || side === 'right'
            ? triggerRect.top + triggerRect.height / 2 - tooltipRect.height / 2
            : top;
        break;
      case 'end':
        left = side === 'top' || side === 'bottom' ? triggerRect.right - tooltipRect.width : left;
        break;
    }

    tooltipRef.current.style.top = `${top + win.scrollY}px`;
    tooltipRef.current.style.left = `${left + win.scrollX}px`;
  }, [side, align]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;
    const doc = getDocument();
    if (!doc) return;

    if (isVisible) {
      updatePosition();
      win.addEventListener('scroll', updatePosition);
      win.addEventListener('resize', updatePosition);
    }

    return () => {
      win.removeEventListener('scroll', updatePosition);
      win.removeEventListener('resize', updatePosition);
    };
  }, [isVisible, updatePosition]);

  return (
    <>
      <div
        ref={triggerRef}
        onMouseEnter={showTooltip}
        onMouseLeave={hideTooltip}
        className={styles.trigger}>
        {children}
      </div>
      {isVisible &&
        createPortal(
          <div ref={tooltipRef} role="tooltip" className={`${styles.tooltip} ${styles[side]}`}>
            {content}
          </div>,
          getDocument()!.body,
        )}
    </>
  );
};
