import * as socketIo from 'socket.io-client';
const { io } = socketIo;
import type { Socket } from 'socket.io-client';
import type {
  GuideSocketConfig,
  GuideSocketCallbacks,
  StartGuidePayload,
  StepCompletePayload,
  GuideStepResponse,
  GuideCompleteResponse,
  ErrorResponse,
} from './types';
import { SocketEvents } from './types';
import { ERROR_MESSAGES, ServerConnectionError, ProjectIdError } from '../../errors';
import { websocketAuthService } from '../websocketAuth';
import { getStorage } from '../../index';
import { logger } from '../../utils/logger';
import { apiService } from '../../services/api';

interface EnrichmentProgress {
  totalElements: number;
  enrichedElements: number;
  newlyProcessed: number;
}

interface EnrichmentComplete {
  elementCount: number;
}

interface UIElement {
  elementId: string;
  trackerId: string;
  routeId: string;
  identifiers: {
    selector: string;
    structuralPath: string;
  };
  metadata: {
    elementType: string;
    pageContext: string;
    nearbyText: string;
  };
}

class GuideSocketClient {
  private static instance: GuideSocketClient;
  private socket: Socket | null = null;
  private config: GuideSocketConfig | null = null;
  private callbacks: GuideSocketCallbacks = {};
  private heartbeatTimeout: NodeJS.Timeout | null = null;
  private missedHeartbeats = 0;
  private readonly MAX_MISSED_HEARTBEATS = 5;
  private readonly HEARTBEAT_INTERVAL = 15000;
  private readonly GUIDE_TIMEOUT = 300000;
  private guideTimeoutId: NodeJS.Timeout | null = null;
  private isReconnecting = false;
  private reconnectAttempts = 0;
  private readonly MAX_RECONNECT_ATTEMPTS = 5;
  private reconnectTimer: NodeJS.Timeout | null = null;
  private enrichmentCache: Map<string, number> = new Map();
  private readonly CACHE_DURATION = 30 * 60 * 1000;
  private lastPingTime: number = 0;

  private constructor() {}

  public static getInstance(): GuideSocketClient {
    if (!GuideSocketClient.instance) {
      GuideSocketClient.instance = new GuideSocketClient();
    }
    return GuideSocketClient.instance;
  }

  private async getAuthData(): Promise<Record<string, string>> {
    if (!this.config?.projectId) {
      throw new ProjectIdError(ERROR_MESSAGES.INVALID_PROJECT_ID);
    }

    try {
      const storage = getStorage();
      // Initialize websocket auth service
      await websocketAuthService.initialize(this.config.projectId, storage, this.config.apiUrl);

      // Get session ID from storage if available
      const sessionId = storage.getItem('pointer_session_id');
      websocketAuthService.setSessionId(sessionId);

      // Get auth data with empty payload for initial connection
      const authData = await websocketAuthService.getAuthData({});

      // Log auth data for debugging
      logger.debug('Guide WebSocket: Auth Data:', {
        projectId: authData['X-PROJECT-ID'],
        timestamp: authData['X-REQUEST-TIMESTAMP'],
        hasPublicKey: !!authData['X-CLIENT-PUBLIC-KEY'],
        hasSignature: !!authData['X-REQUEST-SIGNATURE'],
        hasSessionId: !!authData['X-SESSION-ID'],
      });

      return authData;
    } catch (error) {
      logger.error('Guide WebSocket: Failed to get auth data:', error);
      throw error;
    }
  }

  private setupEventListeners() {
    if (!this.socket) return;

    // Connection events
    this.socket.on(SocketEvents.CONNECT, () => {
      logger.debug('Guide WebSocket: Connected');
      this.isReconnecting = false;
      this.reconnectAttempts = 0;
      this.missedHeartbeats = 0;
      this.lastPingTime = Date.now();
      this.callbacks.onConnectionStateChange?.(true);

      this.setupHeartbeatTimeout();
    });

    this.socket.on(SocketEvents.DISCONNECT, () => {
      logger.debug('Guide WebSocket: Disconnected');
      this.callbacks.onConnectionStateChange?.(false);
      this.cleanupTimers();

      this.handleReconnection();
    });

    this.socket.on(SocketEvents.CONNECT_ERROR, error => {
      logger.error('Guide WebSocket: Connection error:', error);
      this.handleReconnection();
    });

    // Guide-specific events
    this.socket.on(SocketEvents.GUIDE_STEP, (response: GuideStepResponse) => {
      this.resetGuideTimeout();
      this.callbacks.onGuideStep?.(response);
    });

    this.socket.on(SocketEvents.GUIDE_COMPLETE, (response: GuideCompleteResponse) => {
      const responseWithMetadata: GuideCompleteResponse = {
        ...response,
        metadata: {
          initiatedPage: window.location.pathname,
          ...response.metadata,
        },
      };
      this.cleanupGuide();
      this.callbacks.onGuideComplete?.(responseWithMetadata);
    });

    this.socket.on(SocketEvents.ERROR, (error: ErrorResponse) => {
      logger.error('Guide WebSocket: Error:', error);
      this.callbacks.onError?.(error);
    });

    // Heartbeat
    this.socket.on(SocketEvents.PING, () => {
      this.handleHeartbeat();
    });
  }

  private setupHeartbeatTimeout() {
    if (this.heartbeatTimeout) {
      clearTimeout(this.heartbeatTimeout);
    }

    this.heartbeatTimeout = setTimeout(() => {
      const timeSinceLastPing = Date.now() - this.lastPingTime;
      if (timeSinceLastPing > this.HEARTBEAT_INTERVAL * 1.5) {
        this.missedHeartbeats++;
        logger.debug('Guide WebSocket: Missed heartbeat', {
          missedHeartbeats: this.missedHeartbeats,
          timeSinceLastPing,
        });

        if (this.missedHeartbeats >= this.MAX_MISSED_HEARTBEATS) {
          logger.warn('Guide WebSocket: Too many missed heartbeats, reconnecting...');
          this.handleReconnection();
        }
      }
      this.setupHeartbeatTimeout();
    }, this.HEARTBEAT_INTERVAL);
  }

  private handleHeartbeat() {
    if (!this.socket) return;

    this.missedHeartbeats = 0;
    this.lastPingTime = Date.now();
    this.socket.emit(SocketEvents.PONG);
    logger.debug('Guide WebSocket: Heartbeat received and acknowledged');
  }

  private handleReconnection() {
    if (this.isReconnecting) {
      logger.debug('Guide WebSocket: Already attempting to reconnect');
      return;
    }

    this.isReconnecting = true;
    this.reconnectAttempts++;

    if (this.reconnectAttempts > this.MAX_RECONNECT_ATTEMPTS) {
      logger.error('Guide WebSocket: Max reconnection attempts reached');
      this.callbacks.onError?.({
        message: ERROR_MESSAGES.SERVER_CONNECTION_FAILED,
        code: 'MAX_RECONNECT_ATTEMPTS',
      });
      return;
    }

    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
    }

    const delay = Math.min(1000 * Math.pow(2, this.reconnectAttempts), 10000);
    logger.debug(
      `Guide WebSocket: Attempting reconnection in ${delay}ms (attempt ${this.reconnectAttempts})`,
    );

    this.reconnectTimer = setTimeout(async () => {
      try {
        logger.debug('Guide WebSocket: Attempting to reconnect...');
        await this.connect(this.config!);
      } catch (error) {
        logger.error('Guide WebSocket: Reconnection attempt failed:', error);
        if (this.reconnectAttempts < this.MAX_RECONNECT_ATTEMPTS) {
          this.handleReconnection();
        }
      }
    }, delay);
  }

  private resetGuideTimeout() {
    if (this.guideTimeoutId) {
      clearTimeout(this.guideTimeoutId);
    }

    this.guideTimeoutId = setTimeout(() => {
      logger.warn('Guide WebSocket: Guide session timed out');
      this.callbacks.onError?.({
        message: 'Guide session timed out due to inactivity',
        code: 'GUIDE_TIMEOUT',
      });
      this.cleanupGuide();
    }, this.GUIDE_TIMEOUT);
  }

  private cleanupTimers() {
    if (this.heartbeatTimeout) {
      clearTimeout(this.heartbeatTimeout);
      this.heartbeatTimeout = null;
    }
    if (this.guideTimeoutId) {
      clearTimeout(this.guideTimeoutId);
      this.guideTimeoutId = null;
    }
    this.missedHeartbeats = 0;
    this.lastPingTime = 0;
  }

  private cleanupGuide() {
    this.cleanupTimers();
  }

  public async connect(config: GuideSocketConfig): Promise<void> {
    try {
      this.config = config;
      this.callbacks = {
        onGuideStep: config.onGuideStep,
        onGuideComplete: config.onGuideComplete,
        onError: config.onError,
        onConnectionStateChange: config.onConnectionStateChange,
      };

      const authData = await this.getAuthData();

      this.socket = io(config.apiUrl || 'https://api.pointer.so', {
        auth: {
          projectId: authData['X-PROJECT-ID'],
          signature: authData['X-REQUEST-SIGNATURE'],
          timestamp: authData['X-REQUEST-TIMESTAMP'],
          clientPublicKey: authData['X-CLIENT-PUBLIC-KEY'],
        },
        transports: ['websocket'],
        timeout: 60000,
        reconnection: true,
        reconnectionAttempts: this.MAX_RECONNECT_ATTEMPTS,
        reconnectionDelay: 1000,
        reconnectionDelayMax: 10000,
      });

      this.setupEventListeners();
    } catch (error) {
      logger.error('Guide WebSocket: Failed to connect:', error);
      throw new ServerConnectionError(ERROR_MESSAGES.SERVER_CONNECTION_FAILED);
    }
  }

  public async startGuide(payload: StartGuidePayload): Promise<void> {
    if (!this.socket?.connected) {
      logger.debug('Guide WebSocket: Socket not connected, attempting to reconnect');
      await this.handleReconnection();
      return;
    }

    // Add user data to the request if available
    const userData = apiService.getUserData();
    const enhancedPayload = userData
      ? {
          ...payload,
          userData: {
            userId: userData.userId,
            name: userData.name,
            email: userData.email,
          },
        }
      : payload;

    // // Track guide start event
    // if (userData) {
    //   apiService.trackEvent({
    //     eventType: 'GUIDE',
    //     eventName: 'GUIDE_STARTED',
    //     eventData: {
    //       conversationId: payload.conversationId,
    //       messageLength: payload.message.length,
    //     },
    //     context: {
    //       userId: userData.userId,
    //     },
    //     timestamp: new Date().toISOString(),
    //   });
    // }

    try {
      this.socket.emit(SocketEvents.START_GUIDE, enhancedPayload);
      this.resetGuideTimeout();
    } catch (error) {
      logger.error('Guide WebSocket: Error starting guide:', error);
      throw error;
    }
  }

  public async sendStepComplete(payload: StepCompletePayload): Promise<void> {
    if (!this.socket?.connected) {
      logger.debug('Guide WebSocket: Socket not connected, attempting to reconnect');
      await this.handleReconnection();
      return;
    }

    try {
      this.socket.emit(SocketEvents.STEP_COMPLETE, payload);
      this.resetGuideTimeout();
    } catch (error) {
      logger.error('Guide WebSocket: Error completing step:', error);
      throw error;
    }
  }

  public disconnect(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    this.cleanupGuide();
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
    }
  }

  public isConnected(): boolean {
    return !!this.socket?.connected;
  }

  public async enrichUIElements(elements: UIElement[]): Promise<void> {
    if (!this.socket?.connected) {
      logger.warn('Socket not connected, attempting to connect before enrichment');
      await this.connect(this.config!);
    }

    const elementsToEnrich = elements.filter(element => {
      const cachedTimestamp = this.enrichmentCache.get(element.elementId);
      if (!cachedTimestamp) return true;
      return Date.now() - cachedTimestamp > this.CACHE_DURATION;
    });

    if (elementsToEnrich.length === 0) {
      logger.debug('No new elements to enrich, using cached data');
      return;
    }

    return new Promise((resolve, reject) => {
      if (!this.socket) {
        reject(new Error('Socket not initialized'));
        return;
      }

      const progressHandler = (data: EnrichmentProgress) => {
        logger.debug(`Enrichment progress: ${data.newlyProcessed} new elements processed`);
      };

      const completeHandler = (data: EnrichmentComplete) => {
        logger.debug(`Enrichment complete: ${data.elementCount} elements processed`);
        elementsToEnrich.forEach(element => {
          this.enrichmentCache.set(element.elementId, Date.now());
        });
        cleanup();
        resolve();
      };

      const errorHandler = (error: Error) => {
        logger.error('Enrichment error:', error);
        cleanup();
        reject(error);
      };

      const cleanup = () => {
        this.socket?.off('enrichment_progress', progressHandler);
        this.socket?.off('enrichment_complete', completeHandler);
        this.socket?.off('error', errorHandler);
      };

      this.socket.on('enrichment_progress', progressHandler);
      this.socket.on('enrichment_complete', completeHandler);
      this.socket.on('error', errorHandler);

      this.socket.emit('enrich_ui_elements', {
        elements: elementsToEnrich,
        projectId: this.config!.projectId,
      });
    });
  }
}

export const guideSocketClient = GuideSocketClient.getInstance();
