import * as React from 'react';
import { getDocument, getWindow } from '../index';
import type { CustomizationConfig } from '../types/customization';

import { logger } from '../utils/logger';
// Theme mode type and context
export type ThemeMode = 'light' | 'dark';
export const ThemeModeContext = React.createContext<{
  mode: ThemeMode;
  setMode: (mode: ThemeMode) => void;
}>({
  mode: 'dark',
  setMode: () => {},
});

// Function to determine if a color is dark
const isColorDark = (color: string): boolean => {
  try {
    // Convert hex to RGB
    const hex = color.replace('#', '');
    const r = parseInt(hex.substr(0, 2), 16);
    const g = parseInt(hex.substr(2, 2), 16);
    const b = parseInt(hex.substr(4, 2), 16);

    // Calculate relative luminance
    // Using relative luminance formula: https://www.w3.org/TR/WCAG20/#relativeluminancedef
    const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
    return luminance < 0.6; // Using same threshold as PoweredByPointer
  } catch (e) {
    // Default to false for invalid colors
    logger.warn('Invalid color format:', color);
    return false;
  }
};

// Helper function to get the correct color value based on theme mode
const getThemeValue = (
  value: string | { light: string; dark: string } | undefined,
  mode: ThemeMode,
  defaultValue: string | { light: string; dark: string },
): string => {
  if (!value) {
    // If defaultValue is an object with light/dark properties, return the appropriate one
    if (typeof defaultValue === 'object') {
      return defaultValue[mode];
    }
    return defaultValue;
  }

  if (typeof value === 'string') return value;

  // If value is an object with light/dark properties, return the appropriate one
  return value[mode] || (typeof defaultValue === 'object' ? defaultValue[mode] : defaultValue);
};

// Helper function to detect next-themes theme
const detectNextThemesMode = (): ThemeMode | null => {
  if (typeof window === 'undefined') return null;
  const doc = getDocument();
  if (!doc) return null;

  // Check for next-themes data attribute first
  const dataTheme = doc.documentElement.dataset.theme;

  // Also check for light/dark classes that next-themes might be using
  const hasLightClass = doc.documentElement.classList.contains('light');
  const hasDarkClass = doc.documentElement.classList.contains('dark');

  if (dataTheme === 'light') return 'light';
  if (dataTheme === 'dark') return 'dark';
  if (hasLightClass) return 'light';
  if (hasDarkClass) return 'dark';

  return null;
};

// Default theme that maintains our existing color scheme
const defaultTheme = {
  theme: {
    primaryColor: {
      light: '#374151', //gray-800
      dark: '#ffffff', //white
    },
    secondaryColor: {
      light: '#6b7280', //gray-500
      dark: '#9ca3af', //gray-400
    },
    tertiaryColor: {
      light: '#f3f4f6', //gray-100
      dark: '#18181b', //zinc-900
    },
    accentColor: {
      light: '#6366f1', // Indigo for interactive elements in light mode
      dark: '#818cf8', // Lighter indigo for interactive elements in dark mode
    },
    interactiveColor: {
      light: '#374151', //gray-700
      dark: '#6b7280', //gray-500
    },
    backgroundColor: {
      light: '#ffffff', // White background in light mode
      dark: '#09090b', // zinc-950 for dark mode
    },
    borderColor: {
      light: '#e4e4e7', // Light gray for border in light mode
      dark: '#18181b', // zinc-900 for dark mode
    },
    borderRadius: '12px',
    errorColor: '#ef4444', // Red for error messages
    buttonTextColor: {
      light: '',
      dark: '',
    },
    buttonSecondaryTextColor: {
      light: '',
      dark: '',
    },
    cursorColor: {
      light: '#6366f1', // Default to accentColor
      dark: '#818cf8',
    },
  },
  branding: {
    logomark: '',
    triggerIcon: 'pointer' as const,
    triggerBackground: 'linear-gradient(to bottom, #1f2937, #374151)', //gray-800 to gray-700
    triggerIconColor: '#ffffff', // White
    triggerBorder: 'none',
  },
  content: {
    welcomeMessage: 'Hi there 👋',
    welcomeSubheading: 'How can we help?',
    inputPlaceholder: 'Ask AI anything...',
  },
};

export const ThemeContext = React.createContext<Required<CustomizationConfig>>(
  defaultTheme as Required<CustomizationConfig>,
);

interface ThemeProviderProps {
  children: React.ReactNode;
  customization?: CustomizationConfig;
}

export const ThemeProvider: React.FC<ThemeProviderProps> = ({ children, customization }) => {
  // Add state for theme mode with next-themes detection first, then system preference
  const [mode, setMode] = React.useState<ThemeMode>(() => {
    if (typeof window === 'undefined') return 'dark';
    const win = getWindow();
    if (!win) return 'dark';

    // First check for next-themes
    const nextThemesMode = detectNextThemesMode();
    if (nextThemesMode) {
      logger.info(`🎨 ThemeContext: Initial theme from next-themes - ${nextThemesMode}`);
      return nextThemesMode;
    }

    // Then check system preference
    if (win.matchMedia && win.matchMedia('(prefers-color-scheme: dark)').matches) {
      logger.info('🎨 ThemeContext: Initial theme from system preference - dark');
      return 'dark';
    }
    logger.info('🎨 ThemeContext: Initial theme from system preference - light');
    return 'light';
  });

  // Listen for system theme changes (lower priority than next-themes)
  React.useEffect(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;
    const mediaQuery = win.matchMedia('(prefers-color-scheme: dark)');
    const handleChange = (e: MediaQueryListEvent) => {
      // Only update if we don't have next-themes active
      if (!detectNextThemesMode()) {
        const newMode = e.matches ? 'dark' : 'light';
        logger.info(`🎨 ThemeContext: System theme change detected - ${newMode}`);
        setMode(newMode);
      } else {
        logger.info('🎨 ThemeContext: Ignoring system theme change because next-themes is active');
      }
    };

    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, []);

  // Listen for custom theme toggle event
  React.useEffect(() => {
    const handleThemeToggle = () => {
      logger.info('🎨 ThemeContext: Custom theme toggle event received');
      setMode(prevMode => {
        const newMode = prevMode === 'light' ? 'dark' : 'light';
        logger.info(`🎨 ThemeContext: Toggling theme from ${prevMode} to ${newMode}`);
        return newMode;
      });
    };

    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;
    win.addEventListener('pointer-theme-toggle', handleThemeToggle);
    return () => win.removeEventListener('pointer-theme-toggle', handleThemeToggle);
  }, []);

  // Listen for next-themes changes
  React.useEffect(() => {
    const handleNextThemesChange = (event: Event) => {
      if (event instanceof CustomEvent && event.detail?.theme) {
        const nextTheme = event.detail.theme as string;
        logger.info(`🎨 ThemeContext: next-themes change detected - ${nextTheme}`);

        // Force update the theme mode based on next-themes
        if (nextTheme === 'dark' || nextTheme === 'light') {
          // Check if we need to update the mode
          if (mode !== nextTheme) {
            logger.info(
              `🎨 ThemeContext: Updating theme from ${mode} to ${nextTheme} based on next-themes`,
            );
            // Use requestAnimationFrame for smoother transitions
            requestAnimationFrame(() => {
              setMode(nextTheme as ThemeMode);
            });
          } else {
            logger.info(`🎨 ThemeContext: Theme already set to ${nextTheme}, no update needed`);
          }
        }
      }
    };

    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;
    win.addEventListener('next-themes-change', handleNextThemesChange);
    return () => win.removeEventListener('next-themes-change', handleNextThemesChange);
  }, [mode]);

  // Check for next-themes changes on mount and periodically
  React.useEffect(() => {
    // Function to check for next-themes changes
    const checkNextThemes = () => {
      const nextThemesMode = detectNextThemesMode();
      if (nextThemesMode && nextThemesMode !== mode) {
        logger.info(`🎨 ThemeContext: Detected next-themes change to ${nextThemesMode}`);
        setMode(nextThemesMode);
      }
    };

    // Check immediately on mount
    checkNextThemes();

    // Set up a periodic check (every 500ms instead of 2000ms)
    const intervalId = setInterval(checkNextThemes, 50);

    return () => clearInterval(intervalId);
  }, [mode]);

  const theme = React.useMemo<Required<CustomizationConfig>>(() => {
    // Log the customization object to debug
    logger.info('🎨 ThemeContext: Customization received:', customization?.theme);

    // Get background color for current mode
    const backgroundColorValue = getThemeValue(
      customization?.theme?.backgroundColor,
      mode,
      defaultTheme.theme.backgroundColor,
    );

    // Force isDark to match the mode rather than computing from color
    const isDark = mode === 'dark';
    logger.debug(`🎨 ThemeContext: Computed theme for mode ${mode}, isDark: ${isDark}`);
    logger.debug(`🎨 ThemeContext: Background color value: ${backgroundColorValue}`);

    // Handle logomark variants
    let logomark = '';
    if (customization?.branding?.logomark) {
      if (typeof customization.branding.logomark === 'string') {
        logomark = customization.branding.logomark;
      } else {
        logomark = isDark
          ? customization.branding.logomark.dark
          : customization.branding.logomark.light;
      }
    }

    // Create merged theme with mode-specific values
    // IMPORTANT: Preserve the original customization structure to ensure we don't lose the light/dark variants
    const merged = {
      theme: {
        ...defaultTheme.theme,
        primaryColor: customization?.theme?.primaryColor || defaultTheme.theme.primaryColor,
        secondaryColor: customization?.theme?.secondaryColor || defaultTheme.theme.secondaryColor,
        tertiaryColor: customization?.theme?.tertiaryColor || defaultTheme.theme.tertiaryColor,
        accentColor: customization?.theme?.accentColor || defaultTheme.theme.accentColor,
        interactiveColor:
          customization?.theme?.interactiveColor || defaultTheme.theme.interactiveColor,
        backgroundColor:
          customization?.theme?.backgroundColor || defaultTheme.theme.backgroundColor,
        borderRadius: customization?.theme?.borderRadius || defaultTheme.theme.borderRadius,
        borderColor: customization?.theme?.borderColor || defaultTheme.theme.borderColor,
        buttonTextColor: customization?.theme?.buttonTextColor || null,
        buttonSecondaryTextColor: customization?.theme?.buttonSecondaryTextColor || null,
        cursorColor: customization?.theme?.cursorColor || defaultTheme.theme.cursorColor,
        errorColor: defaultTheme.theme.errorColor,
      },
      branding: {
        ...defaultTheme.branding,
        ...customization?.branding,
        logomark, // Override with selected variant
      },
      content: { ...defaultTheme.content, ...customization?.content },
    };

    // Now get the correct values for the current mode
    const computedTheme = {
      theme: {
        ...merged.theme,
        primaryColor: getThemeValue(
          merged.theme.primaryColor,
          mode,
          defaultTheme.theme.primaryColor,
        ),
        secondaryColor: getThemeValue(
          merged.theme.secondaryColor,
          mode,
          defaultTheme.theme.secondaryColor,
        ),
        tertiaryColor: getThemeValue(
          merged.theme.tertiaryColor,
          mode,
          defaultTheme.theme.tertiaryColor,
        ),
        accentColor: getThemeValue(merged.theme.accentColor, mode, defaultTheme.theme.accentColor),
        interactiveColor: getThemeValue(
          merged.theme.interactiveColor,
          mode,
          defaultTheme.theme.interactiveColor,
        ),
        backgroundColor: backgroundColorValue,
        borderRadius: getThemeValue(
          merged.theme.borderRadius,
          mode,
          defaultTheme.theme.borderRadius,
        ),
        borderColor: getThemeValue(merged.theme.borderColor, mode, defaultTheme.theme.borderColor),
        buttonTextColor: merged.theme.buttonTextColor
          ? getThemeValue(merged.theme.buttonTextColor, mode, '')
          : '',
        buttonSecondaryTextColor: merged.theme.buttonSecondaryTextColor
          ? getThemeValue(merged.theme.buttonSecondaryTextColor, mode, '')
          : '',
        cursorColor: merged.theme.cursorColor
          ? getThemeValue(merged.theme.cursorColor, mode, defaultTheme.theme.cursorColor)
          : '',
        errorColor: defaultTheme.theme.errorColor,
      },
      branding: merged.branding,
      content: merged.content,
    };

    // Log the computed theme values for debugging
    logger.debug('🎨 ThemeContext: Computed theme values:', {
      primaryColor: computedTheme.theme.primaryColor,
      secondaryColor: computedTheme.theme.secondaryColor,
      backgroundColor: computedTheme.theme.backgroundColor,
      accentColor: computedTheme.theme.accentColor,
      borderColor: computedTheme.theme.borderColor,
      cursorColor: computedTheme.theme.cursorColor,
    });

    // Ensure all required properties exist
    return computedTheme as Required<CustomizationConfig>;
  }, [customization, mode]);

  // Inject CSS variables
  React.useEffect(() => {
    if (typeof window === 'undefined') return;
    const doc = getDocument();
    if (!doc) return;

    // Use requestAnimationFrame for smoother theme transitions
    requestAnimationFrame(() => {
      const root = doc.documentElement;

      logger.info(`🎨 ThemeContext: Setting CSS variables for mode ${mode}`);
      logger.info(`🎨 ThemeContext: primaryColor = ${theme.theme.primaryColor}`);
      logger.info(`🎨 ThemeContext: backgroundColor = ${theme.theme.backgroundColor}`);
      logger.info(`🎨 ThemeContext: cursorColor = ${theme.theme.cursorColor}`);

      // Add transition for smooth theme changes (if not already set)
      const currentTransition = root.style.getPropertyValue('--pointer-theme-transition');
      if (!currentTransition) {
        root.style.setProperty(
          '--pointer-theme-transition',
          'background-color 0.1s ease, color 0.1s ease, border-color 0.1s ease, fill 0.1s ease',
        );

        // Apply transitions to all elements within the Pointer widget
        const styleElement = doc.createElement('style');
        styleElement.id = 'pointer-theme-transitions';
        styleElement.textContent = `
          [data-pointer-widget] * {
            transition: var(--pointer-theme-transition);
          }
        `;

        // Only append if it doesn't exist already
        if (!doc.getElementById('pointer-theme-transitions')) {
          doc.head.appendChild(styleElement);
        }
      }

      // Theme colors
      root.style.setProperty('--pointer-primary-color', String(theme.theme.primaryColor || ''));
      root.style.setProperty('--pointer-secondary-color', String(theme.theme.secondaryColor || ''));
      root.style.setProperty('--pointer-tertiary-color', String(theme.theme.tertiaryColor || ''));
      root.style.setProperty('--pointer-accent-color', String(theme.theme.accentColor || ''));
      root.style.setProperty(
        '--pointer-interactive-color',
        String(theme.theme.interactiveColor || ''),
      );
      root.style.setProperty(
        '--pointer-background-color',
        String(theme.theme.backgroundColor || ''),
      );
      root.style.setProperty('--pointer-border-radius', String(theme.theme.borderRadius || ''));
      root.style.setProperty('--pointer-border-color', String(theme.theme.borderColor || ''));

      // Always set cursor color - if not provided, it will fall back to accent color
      root.style.setProperty(
        '--pointer-cursor-color',
        String(theme.theme.cursorColor || theme.theme.accentColor || '#6366F1'),
      );

      // Set button text colors if provided
      if (theme.theme.buttonTextColor) {
        root.style.setProperty('--pointer-button-text-color', String(theme.theme.buttonTextColor));
      }
      if (theme.theme.buttonSecondaryTextColor) {
        root.style.setProperty(
          '--pointer-button-secondary-text-color',
          String(theme.theme.buttonSecondaryTextColor),
        );
      }

      // Set logo color based on background darkness
      const backgroundColor = String(theme.theme.backgroundColor || '');
      const logoColor = isColorDark(backgroundColor) ? '#ffffff' : '#111827';
      root.style.setProperty('--pointer-logo-color', logoColor);

      // Additional semantic variables
      root.style.setProperty('--pointer-text-color', String(theme.theme.primaryColor || ''));
      root.style.setProperty('--pointer-text-muted', String(theme.theme.secondaryColor || ''));
      root.style.setProperty(
        '--pointer-interactive-color',
        String(theme.theme.interactiveColor || ''),
      );
      root.style.setProperty('--pointer-highlight-color', String(theme.theme.accentColor || ''));

      // Add theme mode as a data attribute for potential CSS selectors
      root.dataset.pointerThemeMode = mode;
      logger.info(`🎨 ThemeContext: Set data-pointer-theme-mode="${mode}"`);

      // Dispatch an event to notify that theme has changed
      if (typeof window === 'undefined') return;
      const win = getWindow();
      if (!win) return;
      win.dispatchEvent(new CustomEvent('pointer-theme-changed'));
      logger.info('🎨 ThemeContext: Dispatched pointer-theme-changed event');
    });
  }, [theme, mode]);

  return (
    <ThemeModeContext.Provider value={{ mode, setMode }}>
      <ThemeContext.Provider value={theme}>{children}</ThemeContext.Provider>
    </ThemeModeContext.Provider>
  );
};

export const useTheme = () => {
  const context = React.useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

export const useThemeMode = () => {
  const context = React.useContext(ThemeModeContext);
  if (!context) {
    throw new Error('useThemeMode must be used within a ThemeProvider');
  }
  return context;
};
