import { apiService } from '../services/api';

import { logger } from './logger';
interface VerificationState {
  isVerified: boolean;
  timestamp: number;
  error?: string;
}

class ProjectIdVerificationCache {
  private static instance: ProjectIdVerificationCache;
  private cache: Map<string, VerificationState> = new Map();
  private verificationPromises: Map<string, Promise<boolean>> = new Map();
  private CACHE_DURATION = 1000 * 60 * 60; // 1 hour

  private constructor() {}

  static getInstance(): ProjectIdVerificationCache {
    if (!ProjectIdVerificationCache.instance) {
      ProjectIdVerificationCache.instance = new ProjectIdVerificationCache();
    }
    return ProjectIdVerificationCache.instance;
  }

  async verifyProjectId(projectId: string, apiUrl?: string): Promise<boolean> {
    const cacheKey = `${projectId}-${apiUrl || 'default'}`;
    const now = Date.now();

    // Check if we have a cached result that's still valid
    const cachedState = this.cache.get(cacheKey);
    if (cachedState && now - cachedState.timestamp < this.CACHE_DURATION) {
      return cachedState.isVerified;
    }

    // Check if we already have a verification in progress
    let verificationPromise = this.verificationPromises.get(cacheKey);
    if (verificationPromise) {
      return verificationPromise;
    }

    // Start new verification
    verificationPromise = this.performVerification(projectId, apiUrl);
    this.verificationPromises.set(cacheKey, verificationPromise);

    try {
      const isVerified = await verificationPromise;
      this.cache.set(cacheKey, {
        isVerified,
        timestamp: now,
      });
      return isVerified;
    } finally {
      this.verificationPromises.delete(cacheKey);
    }
  }

  private async performVerification(projectId: string, apiUrl?: string): Promise<boolean> {
    try {
      // Initialize API service if needed
      const browserStorage = typeof window !== 'undefined' ? window.localStorage : null;
      if (browserStorage) {
        apiService.initialize(projectId, browserStorage, apiUrl);
      }

      // Perform the actual verification
      await apiService.verifyProjectId();
      return true;
    } catch (error) {
      logger.debug('Project ID Verification failed:', error);
      return false;
    }
  }

  // Method to check if a key is already verified without making a new request
  isProjectIdVerified(projectId: string, apiUrl?: string): boolean {
    const cacheKey = `${projectId}-${apiUrl || 'default'}`;
    const cachedState = this.cache.get(cacheKey);
    return !!(
      cachedState &&
      Date.now() - cachedState.timestamp < this.CACHE_DURATION &&
      cachedState.isVerified
    );
  }

  // Method to invalidate cache for a specific key
  invalidateCache(projectId: string, apiUrl?: string): void {
    const cacheKey = `${projectId}-${apiUrl || 'default'}`;
    this.cache.delete(cacheKey);
  }
}

export const projectIdVerificationCache = ProjectIdVerificationCache.getInstance();
