import type { RuntimeGuide, Step } from '../types';
import { getWindow, getDocument } from '../index';
import { logger } from './logger';
/**
 * Validates whether a guide is still supported by checking if all referenced elements exist in the DOM.
 * @param guide The guide to validate
 * @returns An object containing validation status and any validation errors
 */
export function validateGuide(guide: RuntimeGuide): { isValid: boolean; errors: string[] } {
  if (typeof window === 'undefined') return { isValid: false, errors: ['Window is undefined'] };
  const win = getWindow();
  if (!win) return { isValid: false, errors: ['Window is undefined'] };

  const errors: string[] = [];

  logger.debug('Validating guide:', {
    guideId: guide.id,
    guideName: guide.name,
    hasSteps: !!(guide.steps && guide.steps.length > 0),
    stepCount: guide.steps?.length || 0,
    currentUrl: win.location.pathname,
  });

  // No steps means invalid guide
  if (!guide.steps || guide.steps.length === 0) {
    logger.debug('Guide validation failed: No steps found');
    return { isValid: false, errors: ['Guide has no steps'] };
  }

  // Check each step
  for (const step of guide.steps) {
    const stepErrors = validateStep(step);
    if (stepErrors.length > 0) {
      logger.debug('Step validation failed:', {
        stepId: step.id,
        position: step.position,
        errors: stepErrors,
      });
      errors.push(`Step ${step.id}: ${stepErrors.join(', ')}`);
    }
  }

  if (errors.length > 0) {
    logger.debug('Guide validation failed:', {
      guideId: guide.id,
      errors,
    });
  } else {
    logger.debug('Guide validation passed:', {
      guideId: guide.id,
    });
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
}

/**
 * Validates a single step by checking if its target element exists and is interactive
 */
function validateStep(step: Step): string[] {
  if (typeof window === 'undefined') return ['Window is undefined'];
  const win = getWindow();
  if (!win) return ['Window is undefined'];
  const doc = getDocument();
  if (!doc) return ['Document is undefined'];

  const errors: string[] = [];

  try {
    const element = doc.querySelector(step.position);
    if (!element) {
      errors.push('Target element not found in DOM');
      return errors;
    }

    // Check if element is visible
    const rect = element.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) {
      errors.push('Target element has no dimensions (might be hidden)');
    }

    // Check if element is interactive for click/input actions
    if (step.action) {
      const { type } = step.action;
      if (type === 'click' || type === 'input') {
        const computedStyle = win.getComputedStyle(element);
        if (computedStyle.display === 'none' || computedStyle.visibility === 'hidden') {
          errors.push('Target element is not visible');
        }
        if (computedStyle.pointerEvents === 'none') {
          errors.push('Target element is not interactive');
        }
      }
    }
  } catch (error) {
    logger.error('Error validating step:', error);
    errors.push(
      'Error validating step: ' + (error instanceof Error ? error.message : String(error)),
    );
  }

  return errors;
}
