import * as React from 'react';
import styles from './Suggestions.module.css';
import { useTheme } from '../../../contexts/ThemeContext';

interface SuggestionsProps {
  onItemClick: (text: string) => void;
  isHiding?: boolean;
}

export const Suggestions: React.FC<SuggestionsProps> = ({ onItemClick, isHiding }) => {
  const { content } = useTheme();
  const suggestions = content.suggestedItems;

  return (
    <div className={`${styles.container} ${isHiding ? styles.hiding : ''}`}>
      <h3 className={styles.title}>Try asking</h3>
      <div className={styles.grid}>
        {suggestions?.map((suggestion, index) => (
          <button
            key={index}
            className={styles.suggestionButton}
            onClick={() => onItemClick(suggestion)}>
            {suggestion}
          </button>
        ))}
      </div>
    </div>
  );
};
