import { useMemo } from 'react';
import { MousePointerClick, Loader2, CircleCheck } from '../../../components/icons';
import { Button } from '../../../components/base/Button';
import { Tooltip } from '../../../components/base/Tooltip/Tooltip';
import type { RuntimeGuide } from '../../../types';
import { validateGuide } from '../../../utils/pointerUtils';
import { storage } from '../../../utils/storage';
import styles from './MessageActions.module.css';
import * as React from 'react';
import { getWindow } from '../../../index';
import { logger } from '../../../utils/logger';
interface MessageActionsProps {
  guide?: RuntimeGuide;
  showGuideButton?: boolean;
  showFeedback?: boolean;
  feedbackGiven?: 'yes' | 'no' | null;
  onGuideStart?: (guide: RuntimeGuide) => void;
  onFeedback?: (feedback: 'yes' | 'no') => void;
  isGuideLoading?: boolean;
}

export const MessageActions: React.FC<MessageActionsProps> = ({
  guide,
  showGuideButton,
  showFeedback,
  feedbackGiven,
  onGuideStart,
  onFeedback,
  isGuideLoading,
}) => {
  const guideValidation = useMemo(() => {
    if (typeof window === 'undefined') return { isValid: false, errors: ['Window is undefined'] };
    const win = getWindow();
    if (!win) return { isValid: false, errors: ['Window is undefined'] };

    if (!guide) {
      logger.debug('Guide button disabled: No guide available');
      return { isValid: false, errors: ['No guide available'] };
    }

    const validation = validateGuide(guide);

    // Check if guide can be started from this page
    const initiatedPage = storage.getGuideInitiatedPage(guide.id);
    if (initiatedPage && initiatedPage !== win.location.pathname) {
      logger.debug('Guide page restriction:', {
        guideId: guide.id,
        initiatedPage,
        currentPage: win.location.pathname,
        isCompleted: storage.isGuideCompleted(guide.id),
      });
      return {
        isValid: false,
        errors: [...(validation.errors || []), 'Guide must be started from its original page'],
      };
    }

    return validation;
  }, [guide]);

  // Check if the guide is completed
  const isGuideCompleted = guide ? storage.isGuideCompleted(guide.id) : false;

  const isDisabled = !guide || isGuideLoading || !guideValidation.isValid || isGuideCompleted;

  // Determine if this is an old/unavailable guide
  const isOldGuide = guide && !guideValidation.isValid && !isGuideLoading;

  // Set appropriate button text and tooltip
  const buttonText = isGuideLoading
    ? 'Creating guide'
    : !guide
      ? 'Preparing guide'
      : isOldGuide
        ? 'Guide unavailable'
        : isGuideCompleted
          ? 'Guide completed'
          : 'Show me';

  const tooltipText = isOldGuide
    ? 'This guide is from a previous conversation and is no longer available.'
    : isGuideCompleted
      ? 'You have already completed this guide.'
      : guideValidation.errors?.join(', ');

  // Log guide state for debugging
  React.useEffect(() => {
    if (guide) {
      logger.debug('Guide button state:', {
        guideId: guide.id,
        isDisabled,
        isOldGuide,
        isCompleted: isGuideCompleted,
        buttonText,
        validationErrors: guideValidation.errors,
        isLoading: isGuideLoading,
      });
    }
  }, [
    guide,
    isDisabled,
    isOldGuide,
    buttonText,
    guideValidation.errors,
    isGuideLoading,
    isGuideCompleted,
  ]);

  // Only show tooltip if there's text to display
  const shouldShowTooltip = !!tooltipText;

  return (
    <div className={styles.container}>
      {showGuideButton &&
        (shouldShowTooltip ? (
          <Tooltip
            content={
              <div style={{ maxWidth: '275px', whiteSpace: 'normal', textAlign: 'center' }}>
                {tooltipText}
              </div>
            }
            side="top">
            <Button
              size="sm"
              onClick={() => guide && onGuideStart?.(guide)}
              disabled={isDisabled}
              variant={isGuideLoading || isOldGuide || isGuideCompleted ? 'secondary' : 'primary'}
              className={styles.guideButton}
              style={{
                position: 'relative',
                overflow: 'hidden',
                isolation: 'isolate',
              }}>
              {isGuideLoading ? (
                <>
                  {/* Border container with trail effect */}
                  <div
                    style={{
                      position: 'absolute',
                      inset: 0,
                      borderRadius: 'inherit',
                      padding: '1px',
                      background: 'var(--pointer-border-color)',
                      WebkitMask:
                        'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                      WebkitMaskComposite: 'xor',
                      maskComposite: 'exclude',
                      pointerEvents: 'none',
                      overflow: 'hidden',
                    }}>
                    <div className={styles.trail}></div>
                  </div>
                  <span className={styles.thinkingText}>{buttonText}</span>
                  <Loader2 className={`${styles.icon} ${styles.spinning}`} />
                </>
              ) : (
                <>
                  <span>{buttonText}</span>
                  {!guide ? (
                    <Loader2 className={`${styles.icon} ${styles.spinning}`} />
                  ) : isOldGuide ? (
                    <MousePointerClick className={`${styles.icon} ${styles.disabled}`} />
                  ) : isGuideCompleted ? (
                    <CircleCheck className={`${styles.icon} ${styles.completed}`} />
                  ) : (
                    <MousePointerClick className={styles.icon} />
                  )}
                </>
              )}
            </Button>
          </Tooltip>
        ) : (
          <Button
            size="sm"
            onClick={() => guide && onGuideStart?.(guide)}
            disabled={isDisabled}
            variant={isGuideLoading || isOldGuide || isGuideCompleted ? 'secondary' : 'primary'}
            className={styles.guideButton}
            style={{
              position: 'relative',
              overflow: 'hidden',
              isolation: 'isolate',
            }}>
            {isGuideLoading ? (
              <>
                {/* Border container with trail effect */}
                <div
                  style={{
                    position: 'absolute',
                    inset: 0,
                    borderRadius: 'inherit',
                    padding: '1px',
                    background: 'var(--pointer-border-color)',
                    WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                    WebkitMaskComposite: 'xor',
                    maskComposite: 'exclude',
                    pointerEvents: 'none',
                    overflow: 'hidden',
                  }}>
                  <div className={styles.trail}></div>
                </div>
                <span className={styles.thinkingText}>{buttonText}</span>
                <Loader2 className={`${styles.icon} ${styles.spinning}`} />
              </>
            ) : (
              <>
                <span>{buttonText}</span>
                {!guide ? (
                  <Loader2 className={`${styles.icon} ${styles.spinning}`} />
                ) : isOldGuide ? (
                  <MousePointerClick className={`${styles.icon} ${styles.disabled}`} />
                ) : isGuideCompleted ? (
                  <CircleCheck className={`${styles.icon} ${styles.completed}`} />
                ) : (
                  <MousePointerClick className={styles.icon} />
                )}
              </>
            )}
          </Button>
        ))}
      {showFeedback && onFeedback && (
        <div className={styles.feedbackContainer}>
          <Button
            size="sm"
            variant="outline"
            onClick={() => onFeedback('yes')}
            disabled={!!feedbackGiven}
            className={`${styles.feedbackButton} ${styles.positiveButton} ${
              feedbackGiven === 'yes' ? styles.positiveActive : ''
            }`}>
            Yes 👍
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => onFeedback('no')}
            disabled={!!feedbackGiven}
            className={`${styles.feedbackButton} ${styles.negativeButton} ${
              feedbackGiven === 'no' ? styles.negativeActive : ''
            }`}>
            No 👎
          </Button>
        </div>
      )}
    </div>
  );
};
