'use client';

import { useEffect, useState, useCallback } from 'react';
import { X, ChevronsRight } from './icons';
import { Card } from './base/Card';
import { Tooltip } from './base/Tooltip';
import { Button } from './base/Button';
import { usePointer } from '../hooks/usePointer';
import { getDocument, getStorage, getWindow } from '../index';
import { updatePointerPosition } from '../utils/positions';
import type { PointerDirection } from '../utils/positions';
import { Cursor } from './cursor';
import styles from './Step.module.css';

import { logger } from '../utils/logger';
interface StepProps {
  instructions: string;
  isLastStep: boolean;
  onNextStep: () => void;
  onStopGuide: () => void;
  position: { top: number; left: number };
  onWalkthroughEnd: () => void;
  stepId: string;
}

export const Step: React.FC<StepProps> = ({
  instructions,
  onStopGuide,
  onWalkthroughEnd,
  onNextStep,
  position,
}) => {
  const {
    currentStep,
    steps,
    activeGuide,
    handleActionCompletion,
    setPointerPosition,
    setTargetPosition,
    setIsChatOpen,
    isStepGenerating,
  } = usePointer();
  const [isVisible, setIsVisible] = useState(false);
  const [elementDisappeared, setElementDisappeared] = useState(false);
  const [_cursorPosition, setCursorPosition] = useState({ top: 0, left: 0 });
  const [showClickEffect, setShowClickEffect] = useState(false);
  const [cardVisible, setCardVisible] = useState(false); // Start with card hidden
  const [cursorReady, setCursorReady] = useState(false);
  const [isThinking, setIsThinking] = useState(false);
  const [initialAnimation, setInitialAnimation] = useState(true);
  const [widgetPosition, setWidgetPosition] = useState({ top: 0, left: 0 });
  const [cursorInPosition, setCursorInPosition] = useState(false);
  const [finalCursorPos, setFinalCursorPos] = useState({ top: 0, left: 0 });
  const [pointerDirection, setPointerDirection] = useState<PointerDirection>('left');

  const handleStopGuide = useCallback(() => {
    if (activeGuide && steps.length > 0) {
      const storage = getStorage();
      storage.setItem(
        'pointer_walkthrough_state',
        JSON.stringify({
          guideId: activeGuide.id,
          currentStep,
          steps,
          lastActive: new Date().toISOString(),
          wasManuallyStopped: !elementDisappeared,
          elementDisappeared,
        }),
      );

      const pointerState = storage.getItem('pointerState');
      if (pointerState) {
        const currentState = JSON.parse(pointerState);
        storage.setItem(
          'pointerState',
          JSON.stringify({
            ...currentState,
            currentStep: -1,
            activeGuide: null,
            steps: [],
            isGuideActive: false,
            showPointer: false,
          }),
        );
      }
    }
    setIsVisible(false);
    onWalkthroughEnd();
    onStopGuide();
  }, [activeGuide, currentStep, steps, elementDisappeared, onWalkthroughEnd, onStopGuide]);

  // Set up position tracking for the current step
  useEffect(() => {
    if (steps[currentStep]) {
      const cleanup = updatePointerPosition(
        steps[currentStep],
        setPointerPosition,
        setTargetPosition,
        () => {
          // When element disappears, stop the guide
          logger.debug('Element disappeared, stopping guide');
          setElementDisappeared(true);
          handleStopGuide();
        },
      );
      return () => {
        if (cleanup) cleanup();
      };
    }
  }, [currentStep, steps, setPointerPosition, setTargetPosition, handleStopGuide]);

  // Get widget position for initial animation
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;
    const doc = getDocument();
    if (!doc) return;

    // Find the widget trigger button
    const widgetTrigger = doc.querySelector('.Widget-module__triggerButton___i7xat');
    if (widgetTrigger) {
      const rect = widgetTrigger.getBoundingClientRect();
      setWidgetPosition({
        top: rect.top + rect.height / 2,
        left: rect.left + rect.width / 2,
      });
    } else {
      // Fallback if widget button not found
      setWidgetPosition({
        top: win.innerHeight - 50,
        left: win.innerWidth - 50,
      });
    }
  }, []);

  // Calculate positions once before animations start
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;
    const doc = getDocument();
    if (!doc) return;

    if (!steps[currentStep]) return;

    // Get window dimensions
    const windowWidth = typeof window !== 'undefined' ? window.innerWidth : 1000;
    const windowHeight = typeof window !== 'undefined' ? window.innerHeight : 800;

    // Card dimensions
    const cardWidth = 320;
    const cardHeight = 150;

    // Get target element position if available
    let targetRect = null;
    const targetElement = doc.querySelector(steps[currentStep].position);
    if (targetElement) {
      targetRect = targetElement.getBoundingClientRect();
    }

    // Calculate positions
    const cursorSize = 24;
    let cursorPos = { top: 0, left: 0 };
    const cardPosition = { top: 0, left: 0 };
    let direction: PointerDirection = 'left';

    if (targetRect) {
      // Check if the target position has a direction
      if (position && 'direction' in position && position.direction) {
        direction = position.direction as PointerDirection;
      }

      setPointerDirection(direction);

      // Position cursor more centered on the target element
      // Use a very small offset based on direction to avoid completely covering the element
      const horizontalOffset = targetRect.width * 0.05; // Reduced to 5% of element width for more centered positioning

      if (direction === 'left') {
        cursorPos = {
          left: targetRect.left + targetRect.width / 2 + horizontalOffset - cursorSize / 2,
          top: targetRect.top + targetRect.height / 2, // Center vertically
        };
      } else {
        cursorPos = {
          left: targetRect.left + targetRect.width / 2 - horizontalOffset - cursorSize / 2,
          top: targetRect.top + targetRect.height / 2, // Center vertically
        };
      }

      // Position card based on direction
      if (direction === 'left') {
        // Default - card to the right of the cursor
        cardPosition.left = cursorPos.left + 20;
        cardPosition.top = cursorPos.top + 20;
      } else {
        // Flipped - card to the left of the cursor
        cardPosition.left = cursorPos.left - cardWidth - 20;
        cardPosition.top = cursorPos.top + 20;
      }

      // Ensure card stays within viewport bounds
      if (cardPosition.left + cardWidth > windowWidth - 20) {
        cardPosition.left = Math.max(20, windowWidth - cardWidth - 20);
      }
      if (cardPosition.left < 20) {
        cardPosition.left = 20;
      }

      if (cardPosition.top + cardHeight > windowHeight - 20) {
        cardPosition.top = Math.max(20, windowHeight - cardHeight - 20);
      }
      if (cardPosition.top < 20) {
        cardPosition.top = 20;
      }
    } else {
      // Fallback positioning
      cursorPos = {
        left: position.left,
        top: position.top,
      };

      cardPosition.left = cursorPos.left + 20;
      cardPosition.top = cursorPos.top + 20;
    }

    // Final check for viewport bounds
    cardPosition.left = Math.max(20, Math.min(windowWidth - cardWidth - 20, cardPosition.left));
    cardPosition.top = Math.max(20, Math.min(windowHeight - cardHeight - 20, cardPosition.top));

    // Store the card position
    setCursorPosition(cardPosition);

    // Now position the cursor based on the card position and direction
    let finalCursorPosition = { left: 0, top: 0 };

    if (direction === 'left') {
      // Default - cursor on the left side of the card
      finalCursorPosition = {
        left: cardPosition.left - 20,
        top: cardPosition.top - 10,
      };
    } else {
      // Flipped - cursor on the right side of the card
      finalCursorPosition = {
        left: cardPosition.left + cardWidth + 5,
        top: cardPosition.top - 10,
      };
    }

    // Store the final cursor position
    setFinalCursorPos(finalCursorPosition);
  }, [currentStep, steps, position]);

  // Enhanced fade-in sequence with initial animation
  useEffect(() => {
    // First make the component itself visible
    const visibilityTimer = setTimeout(() => {
      setIsVisible(true);

      // Reset cursor position state
      setCursorInPosition(false);

      // If it's the first step, do the shooting animation from widget
      if (initialAnimation) {
        // Start with cursor completely hidden
        setCursorReady(false);

        // After a short delay, make cursor visible and start moving to target
        setTimeout(() => {
          // Show cursor at widget position first
          setCursorReady(true);

          // After cursor has moved to position, mark it as in position
          const movementTimer = setTimeout(() => {
            setCursorInPosition(true);

            // Only after cursor is in position, show the card
            const cardTimer = setTimeout(() => {
              setInitialAnimation(false);
              setCardVisible(true);
            }, 300);

            return () => clearTimeout(cardTimer);
          }, 800);

          return () => clearTimeout(movementTimer);
        }, 100);
      } else {
        // For subsequent steps, just position the cursor
        setCursorReady(true);

        // After cursor has moved to position, mark it as in position
        const movementTimer = setTimeout(() => {
          setCursorInPosition(true);

          // Only after cursor is in position, show the card
          const cardTimer = setTimeout(() => {
            setCardVisible(true);
          }, 300);

          return () => clearTimeout(cardTimer);
        }, 600);

        return () => clearTimeout(movementTimer);
      }
    }, 50);

    return () => clearTimeout(visibilityTimer);
  }, [initialAnimation, widgetPosition]);

  // Close widget when guide starts
  useEffect(() => {
    setIsChatOpen(false);
  }, [setIsChatOpen]);

  // Handle click effect for cursor
  const handleCursorClick = useCallback(() => {
    setShowClickEffect(true);
    setTimeout(() => {
      setShowClickEffect(false);
    }, 600);
  }, []);

  // Handle automatic step completion (when user completes the step)
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;

    // Listen for step completion events
    const handleStepComplete = (event: CustomEvent) => {
      if (event.detail?.stepId === steps[currentStep]?.id) {
        // Hide card first
        setCardVisible(false);

        // Show thinking state
        setIsThinking(true);

        // Show click effect
        handleCursorClick();

        // Don't call handleActionCompletion here - it's already called in PointerContext
        // This was causing the step to be completed twice
        // handleActionCompletion(steps[currentStep].id);

        // Move to next step
        onNextStep();
      }
    };

    // Add event listener
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    win.addEventListener('stepComplete' as any, handleStepComplete);

    return () => {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      win.removeEventListener('stepComplete' as any, handleStepComplete);
    };
  }, [currentStep, steps, handleActionCompletion, onNextStep, handleCursorClick]);

  // Reset card visibility when step changes
  useEffect(() => {
    // When step changes, reset the card visibility
    setCardVisible(false);
    setCursorInPosition(false);

    // Clear thinking state when new step is ready
    const timer = setTimeout(() => {
      setIsThinking(false);

      // Add a small delay before allowing cursor to move to new position
      // This ensures thinking state is completely gone before movement starts
      setTimeout(() => {
        // Allow time for cursor to move to new position
        const positionTimer = setTimeout(() => {
          setCursorInPosition(true);

          // Show card after cursor is in position
          const cardTimer = setTimeout(() => {
            setCardVisible(true);
          }, 300);

          return () => clearTimeout(cardTimer);
        }, 600);

        return () => clearTimeout(positionTimer);
      }, 200); // Small delay to ensure thinking state is gone

      return () => {};
    }, 0); // Reduced from 300ms to 200ms to fade out thinking state earlier

    return () => clearTimeout(timer);
  }, [currentStep]); // This effect runs when the step changes

  // Simulate click when skipping to next step
  const handleSkip = () => {
    if (isStepGenerating || isThinking) return; // Prevent skipping while generating or thinking
    const currentStepData = steps[currentStep];
    if (currentStepData) {
      // Hide card first
      setCardVisible(false);

      // Show thinking state
      setIsThinking(true);

      // Show click effect
      handleCursorClick();

      // Complete the current step's action if it exists
      handleActionCompletion(currentStepData.id);

      // The thinking state will remain until the next step is ready
      // We don't set a timeout here - it will be handled by the step change effect
      onNextStep();
    }
  };

  if (!isVisible) return null;

  // Calculate card position based on final cursor position and direction
  const cardPosition = {
    top: finalCursorPos.top + 25,
    left:
      pointerDirection === 'left'
        ? finalCursorPos.left + 25 // Card to the right of cursor
        : finalCursorPos.left - 320 - 5, // Card to the left of cursor (320px is card width)
  };

  // For initial animation, use widget position as starting point
  // Only use widget position during the initial animation and when cursor is not in position
  const displayCursorPos = initialAnimation && !cursorInPosition ? widgetPosition : finalCursorPos;

  // Calculate thinking card position - needs to be closer to cursor when flipped
  const thinkingCardPosition = {
    top: finalCursorPos.top + 25,
    left:
      pointerDirection === 'left'
        ? finalCursorPos.left + 25 // Card to the right of cursor
        : finalCursorPos.left - 120 - 5, // Thinking card is narrower, position it closer
  };

  return (
    <>
      {/* Only show cursor when ready and ensure we don't show two cursors */}
      {cursorReady && (
        <Cursor
          position={displayCursorPos}
          onClick={showClickEffect}
          size={20}
          isThinking={isThinking}
          initialAnimation={initialAnimation}
          isFlipped={pointerDirection === 'right'}
        />
      )}

      {/* Thinking state card with animated gradient */}
      {isThinking && (
        <Card
          className={styles.card}
          style={{
            position: 'fixed',
            top: `${thinkingCardPosition.top}px`,
            left: `${thinkingCardPosition.left}px`,
            transform: 'none',
            opacity: 1,
            margin: 0,
            zIndex: 2147483647,
            width: 'auto', // Auto width to hug content
            minWidth: '120px', // Minimum width
            maxWidth: '320px',
            boxShadow: '0 0 10px rgba(0, 0, 0, 0.1)',
            borderRadius: '16px',
            border: 'none',
            overflow: 'hidden',
            transition: 'all 0.3s ease-out',
            pointerEvents: 'none',
          }}>
          {/* Border container */}
          <div
            style={{
              position: 'absolute',
              inset: 0,
              borderRadius: '16px',
              padding: '1px',
              background: 'var(--pointer-border-color)',
              WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
              WebkitMaskComposite: 'xor',
              maskComposite: 'exclude',
              pointerEvents: 'none',
              overflow: 'hidden',
            }}>
            {/* Animated trail effect */}
            <div className={styles.trail}></div>
          </div>

          <div
            className={styles.header}
            style={{ justifyContent: 'center', padding: '0.75rem 1.25rem' }}>
            {/* Text with animated gradient effect */}
            <div
              className={styles.thinkingText}
              style={{
                background:
                  'linear-gradient(90deg, rgb(134, 142, 160) 0%, rgb(134, 142, 160) 35%, var(--pointer-accent-color) 50%, rgb(134, 142, 160) 65%, rgb(134, 142, 160) 100%)',
                backgroundSize: '200% auto',
                color: 'transparent',
                WebkitBackgroundClip: 'text',
                backgroundClip: 'text',
                animation: 'textGradient 2s linear infinite reverse',
                fontWeight: '500',
              }}>
              Thinking
            </div>
          </div>
        </Card>
      )}

      {/* Main step card - only show when not thinking */}
      {!isThinking && (
        <Card
          className={styles.card}
          style={{
            position: 'fixed',
            top: `${cardPosition.top}px`,
            left: `${cardPosition.left}px`,
            transform: 'none', // Remove scale transform
            opacity: cardVisible ? 1 : 0,
            margin: 0,
            zIndex: 2147483647, // Below cursor
            maxWidth: '320px',
            width: '100%',
            boxShadow: '0 0 10px rgba(0, 0, 0, 0.1)', // Add subtle shadow to help distinguish card
            borderRadius: '16px', // Increased border radius for more rounding
            border: 'none', // Remove default border as we'll add a gradient border
            overflow: 'hidden', // To contain the gradient border
            transition: 'opacity 0.3s ease-out', // Simplified transition
            pointerEvents: cardVisible ? 'auto' : 'none', // Only enable interactions when visible
            // Ensure the card doesn't overlap with the target element
            // This helps prevent the card from blocking clicks on the target element
            isolation: 'isolate',
          }}>
          {/* Gradient border using pseudo-element - with stronger accent color */}
          <div
            style={{
              position: 'absolute',
              inset: 0,
              borderRadius: '16px',
              padding: '1px', // Border thickness
              background:
                'linear-gradient(137deg, var(--pointer-accent-color) 0%, var(--pointer-accent-color) 1%, var(--pointer-border-color) 15%, var(--pointer-border-color) 100%)',
              WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
              WebkitMaskComposite: 'xor',
              maskComposite: 'exclude',
              pointerEvents: 'none',
            }}
          />

          <div className={styles.header}>
            {/* Instructions text aligned with action icons */}
            <p className={styles.instructions}>{instructions}</p>
            <div className={styles.actions}>
              <Tooltip content="Skip to next step">
                <Button
                  variant="ghost"
                  size="icon"
                  className={styles.actionButton}
                  onClick={handleSkip}
                  disabled={isStepGenerating || isThinking}>
                  <ChevronsRight className={styles.actionIcon} />
                </Button>
              </Tooltip>
              <Tooltip content="Close guide">
                <Button
                  variant="ghost"
                  size="icon"
                  className={styles.actionButton}
                  onClick={handleStopGuide}>
                  <X className={styles.actionIcon} />
                </Button>
              </Tooltip>
            </div>
          </div>
        </Card>
      )}

      {/* Add styles for animations */}
      <style>
        {`
          @keyframes textGradient {
            0% {
              background-position: 0% 50%;
            }
            100% {
              background-position: 200% 50%;
            }
          }
          
          @supports not (offset-path: border-box) {
            .${styles.trail} {
              animation: fallbackTrail 3s infinite linear;
              width: 100%;
              height: 100%;
              background: linear-gradient(90deg, transparent 0%, var(--pointer-accent-color) 50%, transparent 100%);
              background-size: 200% 100%;
            }
            
            @keyframes fallbackTrail {
              0% {
                background-position: 100% 0;
              }
              100% {
                background-position: -100% 0;
              }
            }
          }
        `}
      </style>
    </>
  );
};
