import type { Step } from '../types';
import { getDocument, getWindow } from '../index';

import { logger } from './logger';

// Keep track of active elements and their steps with timestamps
const activeElements = new Map<
  string,
  {
    element: Element;
    timestamp: number;
    selector: string;
    observers?: {
      intersection?: IntersectionObserver;
      mutation?: MutationObserver;
      resize?: ResizeObserver;
    };
  }
>();

// Manage global observers to reduce duplication
const globalObservers = {
  mutation: null as MutationObserver | null,
  setupCount: 0,
};

// Debounce helper
const debounce = <T extends (...args: unknown[]) => void>(fn: T, ms = 100) => {
  let timeoutId: ReturnType<typeof setTimeout>;
  return function (this: unknown, ...args: Parameters<T>) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn.apply(this, args), ms);
  };
};

// Throttle helper to ensure minimum time between executions
const throttle = <T extends (...args: unknown[]) => void>(fn: T, ms = 100) => {
  let lastRun = 0;
  let timeout: ReturnType<typeof setTimeout> | null = null;

  return function (this: unknown, ...args: Parameters<T>) {
    const now = Date.now();
    if (lastRun && now < lastRun + ms) {
      // If the function is being called too soon, schedule it for later
      if (timeout) clearTimeout(timeout);
      timeout = setTimeout(() => {
        lastRun = now;
        fn.apply(this, args);
      }, ms);
      return;
    }
    lastRun = now;
    fn.apply(this, args);
  };
};

// Helper to check if an element is inside a modal/dialog
const isElementInModal = (element: Element | null): boolean => {
  if (!element) return false;

  // Check if the element itself is a dialog or inside a dialog
  if (
    element.getAttribute('role') === 'dialog' ||
    element.closest('[role="dialog"]') ||
    element.closest('.backdrop') || // Dialog backdrop class
    element.closest('dialog')
  ) {
    return true;
  }

  return false;
};

// Helper to find elements with retry logic for modals
const findElementWithRetry = (
  selector: string,
  maxRetries = 10,
  retryDelay = 100,
  retryCount = 0,
): Promise<Element | null> => {
  return new Promise(resolve => {
    if (typeof window === 'undefined') {
      resolve(null);
      return;
    }
    const doc = getDocument();
    if (!doc) {
      resolve(null);
      return;
    }

    try {
      // Try to find the element
      const element = doc.querySelector(selector);

      // If found, resolve immediately
      if (element) {
        resolve(element);
        return;
      }
    } catch (error) {
      logger.error('Invalid selector in findElementWithRetry:', {
        selector,
        error: error instanceof Error ? error.message : String(error),
      });
      resolve(null);
      return;
    }

    // If we've reached max retries, resolve with null
    if (retryCount >= maxRetries) {
      resolve(null);
      return;
    }

    // Otherwise, retry after delay
    setTimeout(() => {
      findElementWithRetry(selector, maxRetries, retryDelay, retryCount + 1).then(resolve);
    }, retryDelay);
  });
};

// Direction type for pointer positioning
export type PointerDirection = 'left' | 'right';

// Setup and manage the global mutation observer
const setupGlobalMutationObserver = (callback: () => void): (() => void) => {
  if (typeof window === 'undefined') return () => {};
  const doc = getDocument();
  if (!doc) return () => {};

  // Increment setup count
  globalObservers.setupCount++;

  // If we already have an observer, just return the cleanup function
  if (globalObservers.mutation) {
    return () => {
      globalObservers.setupCount--;
      if (globalObservers.setupCount === 0 && globalObservers.mutation) {
        globalObservers.mutation.disconnect();
        globalObservers.mutation = null;
      }
    };
  }

  // Create a single mutation observer for the entire document
  const observer = new MutationObserver(
    debounce(() => {
      callback();
    }, 50),
  );

  // Observe the entire document with a configuration that captures most changes
  observer.observe(doc.body, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ['style', 'class', 'hidden', 'display'],
  });

  globalObservers.mutation = observer;

  // Return a cleanup function
  return () => {
    globalObservers.setupCount--;
    if (globalObservers.setupCount === 0 && globalObservers.mutation) {
      globalObservers.mutation.disconnect();
      globalObservers.mutation = null;
    }
  };
};

export const updatePointerPosition = (
  step: Step,
  setPointerPosition: Function,
  setTargetPosition: Function,
  onElementDisappear?: () => void,
) => {
  let currentElement: Element | null = null;
  let lastUpdate = 0;
  const UPDATE_THRESHOLD = 200;
  const OBSERVER_THRESHOLD = 500;
  const MODAL_RETRY_DELAY = 150; // Specific delay for modal elements
  let rafId: number | null = null;
  let modalReadyListener: ((e: Event) => void) | null = null;
  const stepId = step.id;
  let isInModal = false; // Track if the element is in a modal
  let observersAttached = false;

  // Collection of cleanup functions
  const cleanupFunctions: Array<() => void> = [];

  // Clear any elements older than 10 seconds or from different selectors
  for (const [id, data] of activeElements.entries()) {
    if (Date.now() - data.timestamp > 10000 || data.selector !== step.position) {
      // Clean up any observers
      if (data.observers) {
        if (data.observers.intersection) data.observers.intersection.disconnect();
        if (data.observers.resize) data.observers.resize.disconnect();
      }
      activeElements.delete(id);
    }
  }

  // Listen for modal ready events
  const setupModalReadyListener = () => {
    if (modalReadyListener) return;
    if (typeof window === 'undefined') return;
    const doc = getDocument();
    if (!doc) return;

    modalReadyListener = (e: Event) => {
      logger.debug('Modal content ready event received:', e);
      // Force an update when modal is ready
      setTimeout(() => {
        updatePositions();
      }, 50);
    };

    doc.addEventListener('modal-content-ready', modalReadyListener);
    doc.addEventListener('dialog-ready', modalReadyListener);

    cleanupFunctions.push(() => {
      if (modalReadyListener && doc) {
        doc.removeEventListener('modal-content-ready', modalReadyListener);
        doc.removeEventListener('dialog-ready', modalReadyListener);
      }
    });
  };

  // Set up the modal ready listener
  setupModalReadyListener();

  const findElement = async (shouldLog = false): Promise<Element | null> => {
    if (typeof window === 'undefined') return null;
    const win = getWindow();
    if (!win) return null;
    const doc = getDocument();
    if (!doc) return null;

    // Check if we have a recently found element for this step
    const activeElement = activeElements.get(stepId);
    if (activeElement) {
      const timeSinceFound = Date.now() - activeElement.timestamp;
      if (timeSinceFound < OBSERVER_THRESHOLD) {
        if (shouldLog) {
          logger.debug('Using existing element for step:', stepId);
        }
        return activeElement.element;
      }
    }

    if (shouldLog) {
      logger.debug('Finding element for step:', {
        stepId,
        position: step.position,
      });
    }

    // Validate the selector to avoid invalid queries
    if (!step.position || typeof step.position !== 'string') {
      logger.error('Invalid selector:', {
        stepId,
        position: step.position,
      });
      return null;
    }

    // First try the direct selector
    let element: Element | null = null;
    try {
      element = doc.querySelector(step.position);
    } catch (error) {
      logger.error('Invalid selector in findElement:', {
        selector: step.position,
        error: error instanceof Error ? error.message : String(error),
      });
    }
    let findMethod = 'direct';

    // If not found, check if we need to look inside a modal
    if (!element) {
      // Look for any open modals/dialogs
      const modalElements = doc.querySelectorAll(
        '[role="dialog"], dialog, .backdrop, [data-modal-id], [data-testid="dialog-content"], .project-details-modal',
      );

      if (modalElements.length > 0 && shouldLog) {
        logger.debug('Modal detected, searching inside modal:', {
          modalCount: modalElements.length,
          stepId,
          position: step.position,
        });

        // Try to find the element inside each modal
        for (const modal of Array.from(modalElements)) {
          // Try to find the element within this specific modal with various selector strategies
          const elementInModal = modal.querySelector(
            `#${step.position}, 
             [id="${step.position}"], 
             .${step.position}, 
             [data-testid="${step.position}"]`,
          );

          if (elementInModal) {
            element = elementInModal;
            isInModal = true;
            logger.debug('Found element inside specific modal:', {
              stepId,
              position: step.position,
              modalId: modal.getAttribute('data-modal-id') || modal.id,
            });
            break;
          }
        }
      }

      // If still not found, try with retry logic
      if (!element) {
        // Try with ID selector first if the position doesn't already start with #
        if (!step.position.startsWith('#')) {
          element = await findElementWithRetry(`#${step.position}`);
        }

        // If not found, try with the original selector
        if (!element) {
          element = await findElementWithRetry(step.position, 10, MODAL_RETRY_DELAY);
        }

        findMethod = 'modal-retry';

        if (element && isElementInModal(element)) {
          isInModal = true;
          if (shouldLog) {
            logger.debug('Found element inside modal with retry:', {
              stepId,
              position: step.position,
              method: findMethod,
            });
          }
        }
      }
    }

    // If not found and position starts with #, try partial ID match
    if (!element && step.position.startsWith('#')) {
      findMethod = 'partial';
      const idToMatch = step.position.slice(1); // Remove the # prefix
      const doc = getDocument();
      if (!doc) return null;

      const elements = Array.from(doc.querySelectorAll('[id]')).filter(el =>
        el.id.includes(idToMatch),
      );

      // Only use if we found exactly one match to ensure uniqueness
      if (elements.length === 1) {
        element = elements[0];
        logger.debug('Found element by partial ID match:', {
          idToMatch,
          foundId: element.id,
          method: findMethod,
        });
      } else if (elements.length > 1) {
        logger.debug('Multiple elements found with partial ID match:', {
          idToMatch,
          matches: elements.map(el => el.id),
          method: findMethod,
        });
      }
    }

    // If still not found, try structural path
    if (!element && step.position.includes('>')) {
      findMethod = 'structural';
      logger.debug('Trying structural path: ', {
        stepId,
        position: step.position,
        method: findMethod,
      });
      const structuralPath = step.position
        .toLowerCase()
        .split('>')
        .map(part => {
          const [tag, index] = part.trim().split(':');
          const parsedIndex = parseInt(index);
          const validIndex = !isNaN(parsedIndex) ? parsedIndex + 1 : 1;
          return `${tag}:nth-child(${validIndex})`;
        })
        .join(' > ');

      try {
        const doc = getDocument();
        if (doc) {
          element = doc.querySelector(structuralPath);
        }
      } catch (e) {
        logger.error('Invalid structural path:', {
          path: structuralPath,
          error: e,
          method: findMethod,
        });
      }
    }

    if (!element) {
      logger.error('Element not found:', {
        stepId,
        position: step.position,
        attemptedMethods: findMethod,
        currentUrl: win.location.href,
        timestamp: new Date().toISOString(),
      });
    }

    if (element) {
      // Check if element is in a modal
      if (!isInModal) {
        isInModal = isElementInModal(element);
      }

      // Store the found element with timestamp and selector
      activeElements.set(stepId, {
        element,
        timestamp: Date.now(),
        selector: step.position,
      });

      // Set up observers for this element if we haven't already
      if (!observersAttached) {
        setupElementObservers(element);
      }
    }

    return element;
  };

  // Set up observers for the target element
  const setupElementObservers = (element: Element) => {
    if (typeof window === 'undefined' || observersAttached) return;
    const win = getWindow();
    if (!win) return;

    observersAttached = true;
    const observers: {
      intersection?: IntersectionObserver;
      resize?: ResizeObserver;
    } = {};

    // Set up intersection observer to track visibility
    if ('IntersectionObserver' in window) {
      const intersectionObserver = new IntersectionObserver(
        entries => {
          // Process the entries
          entries.forEach(entry => {
            if (entry.target === element) {
              if (entry.isIntersecting) {
                // Element is visible, update its position
                updatePositions();
              } else if (onElementDisappear) {
                // Element is not visible, potentially trigger disappear callback
                // But don't trigger immediately - check if it's really gone
                setTimeout(() => {
                  // Re-check if the element exists
                  findElement(true).then(foundElement => {
                    if (!foundElement) {
                      onElementDisappear();
                    }
                  });
                }, 300);
              }
            }
          });
        },
        {
          root: null, // Use viewport as root
          rootMargin: '0px',
          threshold: [0, 0.1, 0.5, 1.0], // Track multiple thresholds for better accuracy
        },
      );

      intersectionObserver.observe(element);
      observers.intersection = intersectionObserver;

      cleanupFunctions.push(() => {
        if (observers.intersection) {
          observers.intersection.disconnect();
        }
      });
    }

    // Set up resize observer to track element size changes
    if ('ResizeObserver' in window) {
      const resizeObserver = new ResizeObserver(
        debounce(entries => {
          // Process the entries
          (entries as ResizeObserverEntry[]).forEach(entry => {
            if (entry.target === element) {
              // Element size changed, update positions
              updatePositions();
            }
          });
        }, 50),
      );

      resizeObserver.observe(element);
      observers.resize = resizeObserver;

      cleanupFunctions.push(() => {
        if (observers.resize) {
          observers.resize.disconnect();
        }
      });
    }

    // Store observers in the activeElements map
    const activeElement = activeElements.get(stepId);
    if (activeElement) {
      activeElements.set(stepId, {
        ...activeElement,
        observers,
      });
    }

    // Set up global mutation observer to track DOM changes
    const cleanupMutationObserver = setupGlobalMutationObserver(() => {
      // Check if our element is still in the DOM
      updatePositions();
    });

    cleanupFunctions.push(cleanupMutationObserver);
  };

  // Function to determine the best direction for the pointer based on element position
  const determinePointerDirection = (rect: DOMRect): PointerDirection => {
    if (typeof window === 'undefined') return 'left';
    const win = getWindow();
    if (!win) return 'left';

    const windowWidth = win.innerWidth;

    // Calculate distances to each edge of the screen
    const distanceToRight = windowWidth - (rect.left + rect.width);
    const distanceToLeft = rect.left;

    // Card dimensions (approximate)
    const cardWidth = 320;

    // Check if there's enough space on the right
    const hasSpaceOnRight = distanceToRight >= cardWidth + 20;
    // Check if there's enough space on the left
    const hasSpaceOnLeft = distanceToLeft >= cardWidth + 20;

    // Default direction is left (original behavior)
    let direction: PointerDirection = 'left';

    // If there's not enough space on the right but enough on the left, flip to right
    if (!hasSpaceOnRight && hasSpaceOnLeft) {
      direction = 'right';
    }

    logger.debug('Determined pointer direction:', {
      direction,
      elementRect: {
        left: rect.left,
        right: rect.right,
        top: rect.top,
        bottom: rect.bottom,
        width: rect.width,
        height: rect.height,
      },
      distances: {
        toRight: distanceToRight,
        toLeft: distanceToLeft,
      },
      hasSpace: {
        onRight: hasSpaceOnRight,
        onLeft: hasSpaceOnLeft,
      },
    });

    return direction;
  };

  // Function to update positions based on current element bounds
  const updatePositions = async () => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;

    // Cancel any pending animation frame
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }

    const now = Date.now();
    if (now - lastUpdate < UPDATE_THRESHOLD) {
      // Schedule next update if we're updating too frequently
      rafId = requestAnimationFrame(() => updatePositions());
      return;
    }
    lastUpdate = now;

    const element = await findElement(true);

    // If element not found, don't immediately trigger disappear callback
    // Instead, set up a retry mechanism
    if (!element) {
      logger.warn('Element not found for step, will retry:', {
        stepId,
        position: step.position,
        currentUrl: win.location.href,
        timestamp: new Date().toISOString(),
      });

      // Reset positions but don't trigger disappear callback yet
      setTargetPosition({
        top: 0,
        left: 0,
        width: 0,
        height: 0,
      });
      setPointerPosition({
        top: 0,
        left: 0,
      });

      // Only trigger disappear callback if this is a previously found element that has disappeared
      // Not if we're still trying to find it initially
      if (currentElement && onElementDisappear) {
        onElementDisappear();
      }

      // Clean up any existing element references
      currentElement = null;
      activeElements.delete(stepId);
      return;
    }

    // Check if element exists and has changed
    if (currentElement && currentElement !== element) {
      logger.debug('Element changed for step:', {
        stepId,
        oldElement: currentElement.outerHTML.slice(0, 100),
        newElement: element.outerHTML.slice(0, 100),
      });
    }

    // Update current element reference
    currentElement = element;

    const rect = element.getBoundingClientRect();

    // Determine the best direction for the pointer
    const direction = determinePointerDirection(rect);

    // Just set the target position - this information is used by the Step component
    // to determine where to place the cursor and card
    setTargetPosition({
      top: rect.top,
      left: rect.left,
      width: rect.width,
      height: rect.height,
      // Add higher z-index for modal elements to ensure highlight appears above modal
      zIndex: isInModal ? 2147483646 : undefined, // Use one less than max to ensure it's below the dialog but above everything else
      direction, // Add direction to the target position
    });

    // Set a simple pointer position - the Step component will calculate the real position
    // but we need to provide a default
    setPointerPosition({
      left: rect.left,
      top: rect.top,
      direction, // Add direction to the pointer position
    });
  };

  // Create debounced update function for essential events
  const debouncedUpdatePositions = debounce(updatePositions, 100);

  // Add a click-through handler to ensure clicks reach the target element
  // This is especially important for elements that need to be clicked as part of the guide
  const clickThroughHandler = (event: MouseEvent) => {
    if (typeof window === 'undefined') return;
    const doc = getDocument();
    if (!doc) return;

    // Find the target element again (it might have changed)
    const targetElement = doc.querySelector(step.position);
    if (targetElement && step.action?.type === 'click' && !step.action.completed) {
      // If the click was directly on the target element, don't simulate another click
      if (event.target === targetElement) {
        return;
      }

      // Check if the click was near the target element
      const rect = targetElement.getBoundingClientRect();
      const buffer = 20; // Add a small buffer around the element

      if (
        event.clientX >= rect.left - buffer &&
        event.clientX <= rect.right + buffer &&
        event.clientY >= rect.top - buffer &&
        event.clientY <= rect.bottom + buffer
      ) {
        // If the click was near the target element but didn't hit it directly,
        // simulate a click on the target element
        logger.debug('Forwarding click to target element');
        targetElement.dispatchEvent(
          new MouseEvent('click', {
            bubbles: true,
            cancelable: true,
            view: window,
          }),
        );
      }
    }
  };

  // Set up minimal event listeners for critical interactions
  if (typeof window !== 'undefined') {
    const doc = getDocument();
    if (doc) {
      // Add click handler for tracking click-through
      doc.addEventListener('click', clickThroughHandler);
      cleanupFunctions.push(() => {
        if (doc) {
          doc.removeEventListener('click', clickThroughHandler);
        }
      });

      // Add keydown handler for accessibility interactions
      doc.addEventListener('keydown', debouncedUpdatePositions);
      cleanupFunctions.push(() => {
        if (doc) {
          doc.removeEventListener('keydown', debouncedUpdatePositions);
        }
      });
    }

    // Always add scroll handler for position updates during scrolling
    const win = getWindow();
    if (win) {
      // Throttled scroll handler for smooth performance
      const scrollHandler = throttle(() => {
        requestAnimationFrame(updatePositions);
      }, 100);

      win.addEventListener('scroll', scrollHandler, { capture: true, passive: true });
      cleanupFunctions.push(() => {
        if (win) {
          win.removeEventListener('scroll', scrollHandler, { capture: true });
        }
      });
    }

    // For resize, only add an event listener if ResizeObserver is not supported
    if (!('ResizeObserver' in window)) {
      const win = getWindow();
      if (win) {
        const resizeHandler = debounce(() => {
          updatePositions();
        }, 100);

        win.addEventListener('resize', resizeHandler, { passive: true });
        cleanupFunctions.push(() => {
          if (win) {
            win.removeEventListener('resize', resizeHandler);
          }
        });
      }
    }
  }

  // Initial position update
  updatePositions();

  return () => {
    // Execute all cleanup functions
    for (const cleanup of cleanupFunctions) {
      cleanup();
    }

    // Cancel any pending animation frame
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }

    // Clean up element reference
    activeElements.delete(stepId);
  };
};
