import * as React from 'react';
import { MessageSquare, PenSquare, Trash2, Check } from '../../icons';
import { formatDate } from '../../../utils/dateUtils';
import { Button } from '../../../components/base/Button';
import { Input } from '../../../components/base/Input';
import type { StorageConversation } from '../../../types';
import styles from './SessionItem.module.css';

interface SessionItemProps {
  session: StorageConversation;
  isEditing: boolean;
  editTitle: string;
  isHovered: boolean;
  onMouseEnter: () => void;
  onMouseLeave: () => void;
  onClick: () => void;
  onEditClick: () => void;
  onDeleteClick: () => void;
  onTitleChange: (value: string) => void;
  onTitleBlur: () => void;
  onTitleKeyPress: (e: React.KeyboardEvent) => void;
}

export const SessionItem: React.FC<SessionItemProps> = ({
  session,
  isEditing,
  editTitle,
  isHovered,
  onMouseEnter,
  onMouseLeave,
  onClick,
  onEditClick,
  onDeleteClick,
  onTitleChange,
  onTitleBlur,
  onTitleKeyPress,
}) => {
  const [showDeleteConfirm, setShowDeleteConfirm] = React.useState(false);

  const handleDeleteClick = () => {
    if (showDeleteConfirm) {
      onDeleteClick();
    } else {
      setShowDeleteConfirm(true);
    }
  };

  // Reset delete confirmation when mouse leaves
  React.useEffect(() => {
    if (!isHovered) {
      setShowDeleteConfirm(false);
    }
  }, [isHovered]);

  return (
    <div
      className={`${styles.container} ${isHovered ? styles.hovered : ''}`}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}>
      <button className={styles.mainButton} onClick={onClick}>
        <MessageSquare className={styles.messageIcon} />
        {isEditing ? (
          <div className={styles.wrapper}>
            <Input
              value={editTitle}
              onChange={e => onTitleChange(e.target.value)}
              onBlur={onTitleBlur}
              onKeyPress={onTitleKeyPress}
              className={styles.titleInput}
              autoFocus
            />
          </div>
        ) : (
          <span className={styles.title}>{session.title}</span>
        )}
        <span className={styles.date}>{formatDate(session.createdAt)}</span>
      </button>
      {isHovered && (
        <div className={styles.actions}>
          <Button variant="ghost" size="icon" onClick={onEditClick} className={styles.actionButton}>
            <PenSquare className={styles.editIcon} />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            onClick={handleDeleteClick}
            className={`${styles.actionButton} ${showDeleteConfirm ? styles.confirmDelete : ''}`}>
            {showDeleteConfirm ? (
              <Check className={styles.confirmIcon} />
            ) : (
              <Trash2 className={styles.deleteIcon} />
            )}
          </Button>
        </div>
      )}
    </div>
  );
};
