import { useContext } from 'react';
import { PointerContext } from '../contexts/PointerContext';
import type { PointerContextType } from '../types';

export const usePointer = (): PointerContextType => {
  const context = useContext(PointerContext);
  if (!context) {
    throw new Error('usePointer must be used within a PointerProvider');
  }
  return context;
};
