import type { StorageMessage, StorageConversation, GuideProgress } from '../types';
import { getStorage } from '../index';

import { logger } from './logger';
interface StorageState {
  guides: {
    completedGuides: string[];
    progress: GuideProgress | null;
  };
  conversations: {
    activeConversationId: string | null;
    conversations: StorageConversation[];
  };
}

// Storage keys
const STORAGE_KEY = 'pointer_sdk_storage';

// Constants
const MAX_CONVERSATIONS = 50;
const MAX_MESSAGES_PER_CONVERSATION = 100;

const getInitialState = (): StorageState => ({
  guides: {
    completedGuides: [],
    progress: null,
  },
  conversations: {
    activeConversationId: null,
    conversations: [],
  },
});

export class StorageManager {
  private state: StorageState;
  private isInitialized: boolean = false;

  constructor() {
    this.state = getInitialState();
    // Don't initialize in constructor anymore
  }

  public initialize() {
    if (this.isInitialized) return;
    // Load existing state first
    this.state = this.loadState();
    this.isInitialized = true;
    // Only save if we got an empty state and there's existing data
    const storage = getStorage();
    const existing = storage.getItem(STORAGE_KEY);
    if (!existing && Object.keys(this.state.conversations.conversations).length > 0) {
      this.saveState();
    }
  }

  private loadState(): StorageState {
    try {
      const storage = getStorage();
      const stored = storage.getItem(STORAGE_KEY);

      if (!stored) {
        return getInitialState();
      }

      const parsed = JSON.parse(stored);

      // Ensure conversations have messages arrays
      if (parsed.conversations && parsed.conversations.conversations) {
        parsed.conversations.conversations = parsed.conversations.conversations.map(
          (conv: Partial<StorageConversation>) => ({
            ...conv,
            messages: Array.isArray(conv.messages) ? conv.messages : [],
          }),
        );
      }

      return {
        ...getInitialState(),
        ...parsed,
      };
    } catch (error) {
      logger.debug('Failed to load storage state:', error);
      return getInitialState();
    }
  }

  private ensureInitialized() {
    if (!this.isInitialized) {
      this.initialize();
    }
  }

  private saveState(): void {
    this.ensureInitialized();
    try {
      const storage = getStorage();
      storage.setItem(STORAGE_KEY, JSON.stringify(this.state));
    } catch (error) {
      logger.error('Failed to save state:', error);
      this.handleStorageError();
    }
  }

  private handleStorageError(): void {
    this.ensureInitialized();
    // If storage is full, remove oldest conversations
    if (this.state.conversations.conversations.length > 0) {
      this.state.conversations.conversations = this.state.conversations.conversations
        .sort((a, b) => b.lastUpdated - a.lastUpdated)
        .slice(0, Math.floor(MAX_CONVERSATIONS / 2));

      this.saveState();
    }
  }

  // Guide Methods
  public markGuideCompleted(guideId: string): void {
    this.ensureInitialized();
    if (!this.state.guides.completedGuides.includes(guideId)) {
      this.state.guides.completedGuides.push(guideId);
      this.saveState();
    }
  }

  public saveGuideProgress(progress: GuideProgress): void {
    this.ensureInitialized();
    this.state.guides.progress = {
      ...progress,
      metadata: {
        ...progress.metadata,
        initiatedPage: progress.metadata?.initiatedPage || window.location.pathname,
      },
    };
    this.saveState();
  }

  public clearGuideProgress(): void {
    this.ensureInitialized();
    this.state.guides.progress = null;
    this.saveState();
  }

  public isGuideCompleted(guideId: string): boolean {
    this.ensureInitialized();
    return this.state.guides.completedGuides.includes(guideId);
  }

  // Conversation Methods
  public createConversation(title: string, id?: string): string {
    this.ensureInitialized();
    const conversation: StorageConversation = {
      id: id || crypto.randomUUID(),
      title,
      createdAt: Date.now(),
      lastUpdated: Date.now(),
      messages: [],
    };

    this.state.conversations.conversations.unshift(conversation);
    this.state.conversations.activeConversationId = conversation.id;

    // Maintain max conversations limit
    if (this.state.conversations.conversations.length > MAX_CONVERSATIONS) {
      this.state.conversations.conversations.pop();
    }

    this.saveState();
    return conversation.id;
  }

  public addMessage(conversationId: string, message: Omit<StorageMessage, 'timestamp'>): void {
    this.ensureInitialized();
    const conversation = this.state.conversations.conversations.find(c => c.id === conversationId);

    if (!conversation) {
      logger.error('Conversation not found:', conversationId);
      return;
    }

    // Initialize messages array if it doesn't exist
    if (!conversation.messages) {
      conversation.messages = [];
    }

    const newMessage: StorageMessage = {
      ...message,
      timestamp: Date.now(),
    };

    conversation.messages.push(newMessage);
    conversation.lastUpdated = Date.now();

    // Maintain max messages limit
    if (conversation.messages.length > MAX_MESSAGES_PER_CONVERSATION) {
      conversation.messages = conversation.messages.slice(-MAX_MESSAGES_PER_CONVERSATION);
    }

    this.saveState();
  }

  public getConversation(conversationId: string): StorageConversation | undefined {
    this.ensureInitialized();
    return this.state.conversations.conversations.find(c => c.id === conversationId);
  }

  public getAllConversations(): StorageConversation[] {
    this.ensureInitialized();
    return this.state.conversations.conversations;
  }

  public deleteConversation(conversationId: string): void {
    this.ensureInitialized();
    this.state.conversations.conversations = this.state.conversations.conversations.filter(
      c => c.id !== conversationId,
    );

    if (this.state.conversations.activeConversationId === conversationId) {
      this.state.conversations.activeConversationId =
        this.state.conversations.conversations[0]?.id || null;
    }

    this.saveState();
  }

  public setActiveConversation(conversationId: string): void {
    this.ensureInitialized();
    if (this.state.conversations.conversations.some(c => c.id === conversationId)) {
      this.state.conversations.activeConversationId = conversationId;
      this.saveState();
    }
  }

  public getActiveConversation(): StorageConversation | undefined {
    this.ensureInitialized();
    return this.state.conversations.activeConversationId
      ? this.getConversation(this.state.conversations.activeConversationId)
      : undefined;
  }

  public clearActiveConversation(): void {
    this.ensureInitialized();
    this.state.conversations.activeConversationId = null;
    this.saveState();
  }

  // Utility Methods
  public clearAll(): void {
    this.ensureInitialized();
    const storage = getStorage();
    storage.removeItem(STORAGE_KEY);
    this.state = getInitialState();
  }

  public updateConversationTitle(conversationId: string, newTitle: string): void {
    this.ensureInitialized();
    const conversation = this.state.conversations.conversations.find(c => c.id === conversationId);
    if (conversation) {
      conversation.title = newTitle;
      this.saveState();
    }
  }

  public updateMessageFeedback(
    conversationId: string,
    messageIndex: number,
    feedback: 'yes' | 'no',
  ): void {
    this.ensureInitialized();
    const conversation = this.state.conversations.conversations.find(c => c.id === conversationId);
    if (conversation && conversation.messages[messageIndex]) {
      conversation.messages[messageIndex].feedbackGiven = feedback;
      this.saveState();
    }
  }

  public getGuideProgress(): GuideProgress | null {
    this.ensureInitialized();
    return this.state.guides.progress;
  }

  public getGuideInitiatedPage(guideId: string): string | null {
    this.ensureInitialized();
    const completedGuide = this.state.guides.completedGuides.find(g => g === guideId);
    if (completedGuide) {
      // If guide was completed, it can be started from any page
      return null;
    }
    const progress = this.getGuideProgress();
    if (progress && progress.guideId === guideId) {
      return progress.metadata?.initiatedPage || null;
    }
    return null;
  }

  public getLastMessage(conversationId: string): StorageMessage | null {
    const conversation = this.getConversation(conversationId);
    if (!conversation || conversation.messages.length === 0) {
      return null;
    }
    return conversation.messages[conversation.messages.length - 1];
  }
}

// Export singleton instance
export const storage = new StorageManager();
