declare global {
  const __BROWSER__: boolean;
  const __DEV__: boolean;
}

// Lazy initialization for browser-specific code
let _isBrowser: boolean | undefined;
let _storage: Storage | null = null;
let _document: Document | null = null;
let _window: Window | null = null;

// SSR-safe environment detection
const getEnvironment = () => {
  if (_isBrowser === undefined) {
    try {
      _isBrowser = typeof window !== 'undefined' && Boolean(window.document);
    } catch {
      _isBrowser = false;
    }
  }
  return _isBrowser ? 'browser' : 'server';
};

export const isBrowser = () => getEnvironment() === 'browser';
export const isServer = () => !isBrowser();

// SSR-safe storage with error handling
export const getStorage = () => {
  if (!isBrowser()) {
    return createNullStorage();
  }

  if (_storage) return _storage;

  try {
    // Test if localStorage is actually available (not just window.localStorage existing)
    if (typeof window !== 'undefined' && window.localStorage) {
      const testKey = '__storage_test__';
      window.localStorage.setItem(testKey, testKey);
      window.localStorage.removeItem(testKey);
      _storage = window.localStorage;
      return _storage;
    }
  } catch (e) {
    // Fallback if localStorage is not available or throws
    logger.debug('localStorage not available, falling back to memory storage');
  }

  // Fallback to memory storage
  _storage = createMemoryStorage();
  return _storage;
};

// SSR-safe document access with error handling
export const getDocument = () => {
  if (!isBrowser()) return null;
  if (_document) return _document;

  try {
    _document = window.document;
    return _document;
  } catch {
    return null;
  }
};

// SSR-safe window access with error handling
export const getWindow = () => {
  if (!isBrowser()) return null;
  if (_window) return _window;

  try {
    _window = window;
    return _window;
  } catch {
    return null;
  }
};

// Helper functions
const createNullStorage = (): Storage => ({
  getItem: () => null,
  setItem: () => null,
  removeItem: () => null,
  clear: () => null,
  key: () => null,
  length: 0,
});

const createMemoryStorage = (): Storage => {
  const memoryStorage: Record<string, string> = {};
  return {
    getItem: (key: string) => memoryStorage[key] || null,
    setItem: (key: string, value: string) => {
      memoryStorage[key] = value;
    },
    removeItem: (key: string) => {
      delete memoryStorage[key];
    },
    clear: () => {
      Object.keys(memoryStorage).forEach(key => delete memoryStorage[key]);
    },
    key: (index: number) => Object.keys(memoryStorage)[index] || null,
    get length() {
      return Object.keys(memoryStorage).length;
    },
  };
};
