'use client';

import * as React from 'react';
import { useContext, useState, useRef, useEffect, useCallback } from 'react';
import { FlowManager } from '../utils/FlowManager';
import { FlowStep } from '../components/flows/FlowStep';
import { FlowModal } from '../components/flows/FlowModal';
import { FlowChecklist } from '../components/flows/FlowChecklist';
import { updatePointerPosition } from '../utils/positions';
import { apiService } from '../services/api';
import { projectIdVerificationCache } from '../utils/apiVerification';
import type { FlowContextType, FlowState } from '../types';
import type { UnifiedFlowProviderProps } from '../types/pointer';
import Confetti from '../components/confetti';
import { getDocument, getWindow, getStorage } from '../index';
import { ThemeProvider } from './ThemeContext';
import { logger } from '../utils/logger';

export const UnifiedFlowContext = React.createContext<FlowContextType | null>(null);

export const PointerFlowProvider = ({
  children,
  flows = [],
  projectId,
  apiUrl,
  disabled = false,
  logomark,
  userData,
  userFirstName,
  onNavigate,
  primaryColor,
  secondaryColor,
  tertiaryColor,
  accentColor,
  backgroundColor,
  borderColor,
  borderRadius,
  interactiveColor,
  buttonTextColor,
  buttonSecondaryTextColor,
  cursorColor,
}: UnifiedFlowProviderProps) => {
  // Position state
  const [pointerPosition, setPointerPosition] = useState({ top: 0, left: 0 });
  const [targetPosition, setTargetPosition] = useState({ top: 0, left: 0, width: 0, height: 0 });
  const [scrollDirection, setScrollDirection] = useState<'up' | 'down' | null>(null);
  const positionCleanupRef = useRef<(() => void) | null>(null);

  // Core state
  const isInitializedRef = useRef<boolean>(false);
  const [isBackendAvailable, setIsBackendAvailable] = useState<boolean>(true);
  const flowsRegisteredRef = useRef<boolean>(false); // Flag to track flow registration status
  const pendingFlowStartsRef = useRef<Array<{ flowId: string; userInitiated: boolean }>>([]);
  const isFirstPageLoadRef = useRef<boolean>(true);

  // UI state
  const [isThinking, setIsThinking] = useState(false);
  const [showClickEffect, setShowClickEffect] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showCompletionPopup, _setShowCompletionPopup] = useState(false);
  const [isVisible, _setIsVisible] = useState(false);

  // Initialize FlowManager with navigation callback
  const flowManager = React.useRef<FlowManager>(
    new FlowManager((path: string) => {
      if (typeof window === 'undefined') return;
      const win = getWindow();
      if (!win) return;
      const doc = getDocument();
      if (!doc) return;

      if (onNavigate) {
        onNavigate(path);
      } else {
        win.location.pathname = path;
      }
    }),
  );
  const initialState = flowManager.current.getCurrentState();
  const [flowState, setFlowState] = useState<FlowState>(initialState);
  const previousCompletedFlowsRef = useRef<Set<string>>(initialState.completedFlows);

  // State for tracking the last completed flow to prevent duplicate popups
  const lastCompletedFlowRef = React.useRef<string | null>(null);

  // Store completed flow IDs for consistent checking
  const completedFlowIdsRef = useRef<Set<string>>(new Set());

  // Constants from FlowManager
  const FLOW_STATE_KEY = 'pointer-flow-state';

  // Create theme customization object
  const customization = React.useMemo(
    () => ({
      theme: {
        ...(primaryColor && { primaryColor }),
        ...(secondaryColor && { secondaryColor }),
        ...(tertiaryColor && { tertiaryColor }),
        ...(accentColor && { accentColor }),
        ...(backgroundColor && { backgroundColor }),
        ...(borderColor && { borderColor }),
        ...(borderRadius && { borderRadius }),
        ...(interactiveColor && { interactiveColor }),
        ...(buttonTextColor && { buttonTextColor }),
        ...(buttonSecondaryTextColor && { buttonSecondaryTextColor }),
        ...(cursorColor && { cursorColor }),
      },
      branding: {
        ...(logomark && { logomark }),
      },
    }),
    [
      primaryColor,
      secondaryColor,
      tertiaryColor,
      accentColor,
      backgroundColor,
      borderColor,
      borderRadius,
      interactiveColor,
      buttonTextColor,
      buttonSecondaryTextColor,
      cursorColor,
      logomark,
    ],
  );

  // Initialize SDK and verify API connection - with debouncing
  React.useEffect(() => {
    // If disabled, don't even attempt initialization
    if (disabled) {
      logger.debug('[PointerFlowProvider] SDK disabled, skipping initialization');
      return;
    }

    // Only attempt initialization once every 30 seconds at most
    const cacheKey = `${projectId}-${apiUrl || 'default'}-last-init`;
    const storage = getStorage();
    const lastInitStr = storage.getItem(cacheKey);
    const now = Date.now();
    const lastInit = lastInitStr ? parseInt(lastInitStr, 10) : 0;
    const MIN_INIT_INTERVAL = 900000; // 15 minutes

    // If initialized recently, skip
    if (lastInit && now - lastInit < MIN_INIT_INTERVAL) {
      logger.debug(
        `Skipping SDK initialization (last init was ${Math.round((now - lastInit) / 1000)}s ago)`,
      );
      isInitializedRef.current = true;
      setIsBackendAvailable(true);

      // Even when skipping initialization, check for page path matches
      if (isFirstPageLoadRef.current) {
        setTimeout(() => {
          checkForPagePathTriggers();
        }, 100);
      }

      // Also check for local completion data to sync
      syncLocalCompletions();

      return;
    }

    logger.debug('THIS IS A TEST OF THE LOGGING SYSTEM');

    // Track initialization time
    storage.setItem(cacheKey, now.toString());

    // Actual initialization logic - only run once per session
    if (isInitializedRef.current) {
      logger.debug('[PointerFlowProvider] SDK already initialized - skipping');
      return;
    }

    let initPromise: Promise<void>;

    const initializeSDK = async () => {
      try {
        // Check if we're in SSR
        if (typeof window === 'undefined') {
          logger.debug('[PointerFlowProvider] Skipping initialization in SSR');
          return;
        }

        // Initialize only once - use a shared promise
        initPromise = apiService.initialize(projectId, getStorage(), apiUrl);
        await initPromise;

        if (userData) {
          apiService.setUserData(userData);
        }

        // Check if the project ID is valid
        let isVerified = projectIdVerificationCache.isProjectIdVerified(projectId, apiUrl);
        if (!isVerified) {
          isVerified = await projectIdVerificationCache.verifyProjectId(projectId, apiUrl);
        }

        setIsBackendAvailable(isVerified);
        isInitializedRef.current = true;
        logger.debug('[PointerFlowProvider] SDK initialized successfully');

        // After initialization, check if the current page path should trigger any flows
        if (isFirstPageLoadRef.current) {
          setTimeout(() => {
            checkForPagePathTriggers();
          }, 200);
        }

        // Also check for local completion data to sync
        syncLocalCompletions();
      } catch (error) {
        logger.error('[PointerFlowProvider] Error during SDK initialization', error);
        setIsBackendAvailable(false);
        isInitializedRef.current = true;
      }
    };

    initializeSDK();

    // Cleanup function
    return () => {
      // No cleanup needed
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectId, apiUrl, userData, disabled]);

  // Function to synchronize locally stored completions with the server
  const syncLocalCompletions = useCallback(async () => {
    // Only sync if we have a user identified and backend is available
    if (!userData || !isBackendAvailable) {
      logger.debug('[PointerFlowProvider] Skipping local completion sync - no user or backend');
      return;
    }

    try {
      logger.debug('[PointerFlowProvider] Starting bidirectional completion sync');

      // 1. Get server-side completions
      const serverData = await apiService.fetchUserDataFromServer();
      const serverCompletedFlows = new Set(
        Array.isArray(serverData.completedFlows?.flowIds) ? serverData.completedFlows.flowIds : [],
      );

      // 2. Collect locally completed flows from all storage locations
      const locallyCompletedFlows = new Set<string>();
      const flowMetadata: Record<
        string,
        {
          isSubflow: boolean;
          parentFlowId?: string;
          completedAt?: Date;
        }
      > = {};

      const storage = getStorage();

      // A. Check the main flow state
      const mainFlowState = storage.getItem(FLOW_STATE_KEY);
      if (mainFlowState) {
        try {
          const state = JSON.parse(mainFlowState);
          if (Array.isArray(state.completedFlows)) {
            state.completedFlows.forEach((flowId: string) => {
              locallyCompletedFlows.add(flowId);

              // Determine if it's a subflow
              const parentFlow = flows.find(
                flow => flow.type === 'composite' && flow.subflows.some(sf => sf.id === flowId),
              );

              flowMetadata[flowId] = {
                isSubflow: !!parentFlow,
                parentFlowId: parentFlow?.id,
                completedAt: new Date(), // Use current date as fallback
              };
            });
          }
        } catch (e) {
          logger.warn('[PointerFlowProvider] Error reading main flow state:', e);
        }
      }

      // B. Check all individual flow states
      // Get all keys that start with pointer-flow-state-
      const allKeys = Object.keys(localStorage);
      const flowStateKeys = allKeys.filter(key => key.startsWith('pointer-flow-state-'));

      for (const key of flowStateKeys) {
        try {
          const stateStr = storage.getItem(key);
          if (stateStr) {
            const state = JSON.parse(stateStr);
            // Add the flowId from the key
            const flowId = key.replace('pointer-flow-state-', '');
            if (state.isCompleted) {
              locallyCompletedFlows.add(flowId);

              // Check if this is a subflow
              const parentFlow = flows.find(
                flow => flow.type === 'composite' && flow.subflows.some(sf => sf.id === flowId),
              );

              flowMetadata[flowId] = {
                isSubflow: !!parentFlow,
                parentFlowId: parentFlow?.id,
                completedAt: state.completedAt ? new Date(state.completedAt) : new Date(),
              };
            }

            // Also check completedFlows array if it exists
            if (Array.isArray(state.completedFlows)) {
              state.completedFlows.forEach((id: string) => {
                locallyCompletedFlows.add(id);

                // Check if this is a subflow
                const parentFlow = flows.find(
                  flow => flow.type === 'composite' && flow.subflows.some(sf => sf.id === id),
                );

                if (!flowMetadata[id]) {
                  flowMetadata[id] = {
                    isSubflow: !!parentFlow,
                    parentFlowId: parentFlow?.id,
                    completedAt: state.completedAt ? new Date(state.completedAt) : new Date(),
                  };
                }
              });
            }
          }
        } catch (e) {
          logger.warn(`[PointerFlowProvider] Error reading flow state for ${key}:`, e);
        }
      }

      // C. Check onboarding state storage
      const onboardingKeys = allKeys.filter(key => key.startsWith('pointer-onboarding-state-'));
      for (const key of onboardingKeys) {
        try {
          const stateStr = storage.getItem(key);
          if (stateStr) {
            const state = JSON.parse(stateStr);
            // Add the flowId from the key
            const flowId = key.replace('pointer-onboarding-state-', '');

            // Composite flows might be completed if all subflows are completed
            const flow = flows.find(f => f.id === flowId);
            if (flow?.type === 'composite' && Array.isArray(state.completedFlows)) {
              const allSubflowsCompleted = flow.subflows.every(subflow =>
                state.completedFlows.includes(subflow.id),
              );

              if (allSubflowsCompleted) {
                locallyCompletedFlows.add(flowId);

                // This is a parent flow
                flowMetadata[flowId] = {
                  isSubflow: false,
                  completedAt: state.completedAt ? new Date(state.completedAt) : new Date(),
                };
              }

              // Also add individual subflow completions
              state.completedFlows.forEach((id: string) => {
                locallyCompletedFlows.add(id);

                // Mark as subflow
                if (!flowMetadata[id]) {
                  flowMetadata[id] = {
                    isSubflow: true,
                    parentFlowId: flowId,
                    completedAt: state.completedAt ? new Date(state.completedAt) : new Date(),
                  };
                }
              });
            }
          }
        } catch (e) {
          logger.warn(`[PointerFlowProvider] Error reading onboarding state for ${key}:`, e);
        }
      }

      // 3. Find flows that are completed locally but not on server
      const flowsToSync: string[] = [];
      locallyCompletedFlows.forEach(flowId => {
        if (!serverCompletedFlows.has(flowId)) {
          flowsToSync.push(flowId);
        }
      });

      // 4. Find flows that are completed on server but not locally
      const flowsToAddLocally: string[] = [];
      serverCompletedFlows.forEach(flowId => {
        if (!locallyCompletedFlows.has(flowId)) {
          flowsToAddLocally.push(flowId);
          // Add to our in-memory completed flows set
          completedFlowIdsRef.current.add(flowId);
        }
      });

      // Update local state with server completions
      if (flowsToAddLocally.length > 0) {
        logger.debug('[PointerFlowProvider] Adding server completions to local state:', {
          flowCount: flowsToAddLocally.length,
          flows: flowsToAddLocally,
        });

        // Update the state to include server-completed flows
        const newCompletedFlows = new Set([...locallyCompletedFlows, ...flowsToAddLocally]);

        // Update localStorage
        try {
          if (mainFlowState) {
            const state = JSON.parse(mainFlowState);
            state.completedFlows = Array.from(newCompletedFlows);
            storage.setItem(FLOW_STATE_KEY, JSON.stringify(state));
          }
        } catch (e) {
          logger.warn(
            '[PointerFlowProvider] Error updating local state with server completions:',
            e,
          );
        }

        // IMPORTANT: Trigger a FlowManager state update to refresh the UI
        // This ensures the checklist updates immediately without requiring a page reload
        flowManager.current.updateState({
          completedFlows: new Set(newCompletedFlows),
        });
      }

      // 5. Sync the missing completions to the server
      if (flowsToSync.length > 0) {
        logger.debug('[PointerFlowProvider] Found locally completed flows to sync:', {
          flowCount: flowsToSync.length,
          flows: flowsToSync,
        });

        // Batch process to avoid too many API calls
        const batchSize = 5; // Process 5 flows at a time
        for (let i = 0; i < flowsToSync.length; i += batchSize) {
          const batch = flowsToSync.slice(i, i + batchSize);

          // Process batch concurrently
          await Promise.all(
            batch.map(async flowId => {
              try {
                const metadata = flowMetadata[flowId] || { isSubflow: false };

                // Register with API
                await apiService.registerFlowCompletion({
                  flowId,
                  customData: userData?.customData,
                  isSubflow: metadata.isSubflow,
                  parentFlowId: metadata.parentFlowId,
                });

                logger.debug(`[PointerFlowProvider] Synced local completion for flow ${flowId}`, {
                  isSubflow: metadata.isSubflow,
                  parentFlowId: metadata.parentFlowId,
                });

                // Update our in-memory completed flows set
                completedFlowIdsRef.current.add(flowId);
              } catch (error) {
                logger.error(
                  `[PointerFlowProvider] Failed to sync completion for flow ${flowId}:`,
                  error,
                );
              }
            }),
          );

          // Small delay between batches to avoid overwhelming the API
          if (i + batchSize < flowsToSync.length) {
            await new Promise(resolve => setTimeout(resolve, 500));
          }
        }

        // IMPORTANT: Trigger a FlowManager state update after all syncing is complete
        // This ensures the checklist updates immediately without requiring a page reload
        flowManager.current.updateState({
          completedFlows: new Set(completedFlowIdsRef.current),
        });
      } else {
        logger.debug('[PointerFlowProvider] No locally completed flows to sync');
      }
    } catch (error) {
      logger.error('[PointerFlowProvider] Error synchronizing completions:', error);
    }
  }, [userData, isBackendAvailable, flows]);

  // Add a periodic sync effect to ensure completions stay in sync
  React.useEffect(() => {
    if (disabled || !isBackendAvailable || !userData) {
      return; // Don't run periodic sync if disabled, offline, or no user
    }

    // Only sync periodically if we have a user identified
    const SYNC_INTERVAL = 43200000; // 12 hours in milliseconds

    // Do an initial sync after a short delay
    const initialSyncTimeout = setTimeout(() => {
      syncLocalCompletions();
    }, 5000); // 5 second delay for initial sync

    // Set up periodic sync
    const intervalId = setInterval(() => {
      logger.debug('[PointerFlowProvider] Running periodic completion sync');
      syncLocalCompletions();
    }, SYNC_INTERVAL);

    return () => {
      clearTimeout(initialSyncTimeout);
      clearInterval(intervalId);
    };
  }, [userData, isBackendAvailable, disabled, syncLocalCompletions]);

  // Add an effect to sync when userData changes (user signs in)
  React.useEffect(() => {
    if (userData && isBackendAvailable && !disabled) {
      logger.debug('[PointerFlowProvider] User data changed, syncing completions');
      // Small delay to ensure userData is properly set
      setTimeout(() => {
        syncLocalCompletions();
      }, 1000);
    }
  }, [userData, isBackendAvailable, disabled, syncLocalCompletions]);

  // Helper function to check if current page path matches any flow page triggers
  const checkForPagePathTriggers = useCallback(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;

    const currentPath = win.location.pathname;
    logger.debug('[PointerFlowProvider] Checking for path-based flow triggers', {
      currentPath,
      isFirstPageLoad: isFirstPageLoadRef.current,
    });

    // Check if any registered flow should be triggered on this path
    const triggersChecked = flows.filter(flow => {
      // Skip completed flows - don't trigger them
      if (completedFlowIdsRef.current.has(flow.id)) {
        logger.debug('[PointerFlowProvider] Skipping completed flow for path trigger', {
          flowId: flow.id,
          isCompleted: true,
        });
        return false;
      }

      // For composite flows, check if the modalTriggerPath matches the current path
      if (flow.type === 'composite') {
        // Flow might have a modalTriggerPath property or rely on the first subflow
        const modalTriggerPath =
          flow.modalTriggerPath || flow.subflows[0]?.page || flow.subflows[0]?.steps?.[0]?.page;

        if (
          modalTriggerPath &&
          (modalTriggerPath === currentPath || currentPath.includes(modalTriggerPath))
        ) {
          logger.debug('[PointerFlowProvider] Found path-based flow trigger', {
            flowId: flow.id,
            path: modalTriggerPath,
            matchType: 'composite-modalTriggerPath',
          });

          // Queue this flow with high priority
          pendingFlowStartsRef.current.push({
            flowId: flow.id,
            userInitiated: true, // Treat path matches as user-initiated
          });

          return true;
        }
      }
      // For simple flows, check if the first step's page matches
      else if (flow.type === 'simple' && flow.steps && flow.steps.length > 0) {
        const firstStepPage = flow.steps[0].page || flow.page;

        if (
          firstStepPage &&
          (firstStepPage === currentPath || currentPath.includes(firstStepPage))
        ) {
          logger.debug('[PointerFlowProvider] Found path-based flow trigger', {
            flowId: flow.id,
            path: firstStepPage,
            matchType: 'simple-first-step',
          });

          // Queue this flow with high priority
          pendingFlowStartsRef.current.push({
            flowId: flow.id,
            userInitiated: true, // Treat path matches as user-initiated
          });

          return true;
        }
      }

      return false;
    });

    logger.debug('[PointerFlowProvider] Path-based trigger check completed', {
      triggersFound: triggersChecked.length,
      triggeredFlows: triggersChecked.map(f => f.id),
    });
  }, [flows]);

  // Register flows with FlowManager AFTER initialization is complete
  React.useEffect(() => {
    logger.debug('[PointerFlowProvider] Registering flows', {
      flowCount: flows.length,
      flows: flows.map(f => ({ id: f.id, type: f.type })),
    });

    if (!isInitializedRef.current) return;

    const currentFlowManager = flowManager.current;

    logger.debug('[PointerFlowPointer] Registering flows', {
      flowCount: flows.length,
      flows: flows.map(f => ({ id: f.id, type: f.type })),
    });

    // Clear completed flows when registering new flows
    previousCompletedFlowsRef.current = new Set();

    // Keep track of all cleanup functions
    const cleanupFunctions: (() => void)[] = [];

    const flowState = currentFlowManager.getCurrentState();
    const hasActiveFlow = flowState.activeFlowId !== null;

    // Check if active flow is completed (should rarely happen)
    const activeFlowIsCompleted =
      hasActiveFlow &&
      flowState.activeFlowId &&
      completedFlowIdsRef.current.has(flowState.activeFlowId);

    if (hasActiveFlow && !activeFlowIsCompleted) {
      logger.debug('[PointerFlowProvider] Detected ongoing flow from navigation', {
        activeFlowId: flowState.activeFlowId,
        activeSubflowId: flowState.activeSubflowId,
        currentStep: flowState.currentStep,
      });

      // Register all flows, but we'll handle the active flow specially
      flows.forEach(flow => {
        // For active flow, always register it even if completed
        if (flow.id === flowState.activeFlowId || !completedFlowIdsRef.current.has(flow.id)) {
          currentFlowManager.registerFlow(flow);
          logger.debug('[PointerFlowProvider] Registered flow during navigation continuation', {
            flowId: flow.id,
            type: flow.type,
            isActive: flow.id === flowState.activeFlowId,
          });

          // IMPORTANT: Also register all subflows for composite flows
          if (flow.type === 'composite') {
            flow.subflows.forEach(subflow => {
              // Only register subflows that are not completed or are the active subflow
              if (
                subflow.id === flowState.activeSubflowId ||
                !completedFlowIdsRef.current.has(subflow.id)
              ) {
                currentFlowManager.registerFlow(subflow);
                logger.debug(
                  '[PointerFlowProvider] Registered subflow during navigation continuation',
                  {
                    subflowId: subflow.id,
                    parentFlowId: flow.id,
                    isActive: subflow.id === flowState.activeSubflowId,
                  },
                );
              }
            });
          }
        } else {
          logger.debug('[PointerFlowProvider] Skipping completed flow', {
            flowId: flow.id,
            type: flow.type,
          });
        }
      });

      // Mark flows as registered
      flowsRegisteredRef.current = true;
    } else {
      apiService
        .fetchUserDataFromServer()
        .then(serverData => {
          const completedFlowsArray = Array.isArray(serverData.completedFlows?.flowIds)
            ? serverData.completedFlows.flowIds
            : [];

          // Update the completed flows reference
          completedFlowIdsRef.current = new Set(completedFlowsArray);
          const filteredFlows = flows.filter(flow => !completedFlowIdsRef.current.has(flow.id));

          logger.debug('Registering flows after filtering completed:', {
            totalFlows: flows.length,
            completedFlows: completedFlowsArray,
            remainingFlows: filteredFlows.length,
            allFlows: flows.map(flow => flow.id),
          });

          // Register only non-completed flows
          flows.forEach(flow => {
            if (!completedFlowIdsRef.current.has(flow.id)) {
              currentFlowManager.registerFlow(flow);
              logger.debug('[PointerFlowProvider] Registered non-completed flow', {
                flowId: flow.id,
                type: flow.type,
              });

              // IMPORTANT: Also register all subflows for composite flows
              if (flow.type === 'composite') {
                // Track the total subflows and how many were registered
                const totalSubflows = flow.subflows.length;
                let registeredSubflows = 0;

                flow.subflows.forEach(subflow => {
                  if (!completedFlowIdsRef.current.has(subflow.id)) {
                    currentFlowManager.registerFlow(subflow);
                    registeredSubflows++;
                    logger.debug('[PointerFlowProvider] Registered non-completed subflow', {
                      subflowId: subflow.id,
                      parentFlowId: flow.id,
                    });
                  }
                });

                logger.debug('[PointerFlowProvider] Subflow registration summary', {
                  parentFlowId: flow.id,
                  totalSubflows,
                  registeredSubflows,
                  skippedSubflows: totalSubflows - registeredSubflows,
                });
              }
            } else {
              logger.debug('[PointerFlowProvider] Skipping completed flow', {
                flowId: flow.id,
                type: flow.type,
              });
            }
          });

          // Mark flows as registered
          flowsRegisteredRef.current = true;
        })
        .catch(error => {
          logger.warn('Failed to fetch completed flows, registering all:', error);

          // In case of an error, register all flows and their subflows
          flows.forEach(flow => {
            currentFlowManager.registerFlow(flow);

            // Also register all subflows for composite flows
            if (flow.type === 'composite') {
              flow.subflows.forEach(subflow => {
                currentFlowManager.registerFlow(subflow);
                logger.debug('[PointerFlowProvider] Registered subflow during error recovery', {
                  subflowId: subflow.id,
                  parentFlowId: flow.id,
                });
              });
            }
          });

          // Mark flows as registered even if there was an error
          flowsRegisteredRef.current = true;
        });
    }

    // Subscribe to state changes
    const unsubscribe = currentFlowManager.subscribe(newState => {
      logger.debug('[PointerFlowProvider] Flow state update from subscription', {
        newState,
        activeFlowId: newState.activeFlowId,
        isWelcomeModalOpen: newState.isWelcomeModalOpen,
      });

      // Track newly completed flows
      if (
        newState.lastCompletedFlow &&
        newState.lastCompletedFlow !== lastCompletedFlowRef.current
      ) {
        // Update the ref to prevent duplicate popups in the future
        lastCompletedFlowRef.current = newState.lastCompletedFlow;

        // Add to our completed flows set (with type assertion since we've already checked it's non-null)
        completedFlowIdsRef.current.add(newState.lastCompletedFlow as string);
      }

      // Update completed flows set
      if (newState.completedFlows) {
        newState.completedFlows.forEach(flowId => {
          completedFlowIdsRef.current.add(flowId);
        });
      }

      previousCompletedFlowsRef.current = new Set(newState.completedFlows);
      setFlowState(newState);
    });
    cleanupFunctions.push(unsubscribe);

    return () => {
      logger.debug('[PointerFlowProvider] Cleaning up flows');
      cleanupFunctions.forEach(cleanup => cleanup());

      // Do NOT unregister flows when navigating between pages - this is crucial
      const win = getWindow();
      if (win && !win.location.href.includes('navigate')) {
        flows.forEach(flow => {
          // Unregister the parent flow
          currentFlowManager.unregisterFlow(flow.id);

          // Also unregister all subflows for composite flows
          if (flow.type === 'composite') {
            flow.subflows.forEach(subflow => {
              currentFlowManager.unregisterFlow(subflow.id);
              logger.debug('[PointerFlowProvider] Unregistered subflow during cleanup', {
                subflowId: subflow.id,
                parentFlowId: flow.id,
              });
            });
          }
        });
      }
    };
  }, [flows, userData]);

  // Add effect to process pending flow starts after initialization
  React.useEffect(() => {
    // Only process the queue when both initialization and flow registration are complete
    if (
      isInitializedRef.current &&
      flowsRegisteredRef.current &&
      pendingFlowStartsRef.current.length > 0
    ) {
      logger.debug('[PointerFlowProvider] Processing pending flow starts', {
        count: pendingFlowStartsRef.current.length,
        flows: pendingFlowStartsRef.current.map(f => f.flowId),
        isFirstPageLoad: isFirstPageLoadRef.current,
      });

      // Process each pending flow start
      const pendingFlows = [...pendingFlowStartsRef.current];
      pendingFlowStartsRef.current = []; // Clear the queue

      // Add a slightly longer delay for first page load to ensure DOM is ready
      const delay = isFirstPageLoadRef.current ? 200 : 50;
      isFirstPageLoadRef.current = false;

      setTimeout(() => {
        pendingFlows.forEach(({ flowId, userInitiated }) => {
          logger.debug('[PointerFlowProvider] Starting queued flow', {
            flowId,
            userInitiated,
          });

          const flow = flowManager.current.getFlowById(flowId);
          if (flow) {
            flowManager.current.startFlow(flowId, userInitiated);
          } else {
            logger.error('[PointerFlowProvider] Queued flow not found after initialization', {
              flowId,
              registeredFlows: flows.map(f => f.id),
            });
          }
        });
      }, delay);
    }
  }, [flows]);

  // Add effect to check for URL parameters that should trigger flows on page load
  React.useEffect(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;

    // Only check on first page load
    if (!isFirstPageLoadRef.current) return;

    try {
      // Check for flow trigger parameters in the URL
      const urlParams = new URLSearchParams(win.location.search);
      const flowParam = urlParams.get('flow');
      const showOnboardingParam = urlParams.get('showOnboarding');

      if (flowParam) {
        // URL contains a specific flow to start - queue it with high priority
        logger.debug('[PointerFlowProvider] Detected flow trigger in URL', {
          flowParam,
          url: win.location.href,
        });

        // Find flow by ID or by matching substring
        const matchingFlow = flows.find(
          f =>
            (f.id === flowParam ||
              (flowParam && f.id.includes(flowParam)) ||
              (flowParam && flowParam.includes(f.id))) &&
            !completedFlowIdsRef.current.has(f.id),
        );

        if (matchingFlow) {
          // Queue this flow with user-initiated flag to ensure it will start
          pendingFlowStartsRef.current.push({
            flowId: matchingFlow.id,
            userInitiated: true, // Treat URL parameters as user-initiated
          });
        }
      } else if (showOnboardingParam === 'true' || showOnboardingParam === '1') {
        // Generic onboarding request - find the first non-completed composite flow
        const onboardingFlow = flows.find(
          f => f.type === 'composite' && !completedFlowIdsRef.current.has(f.id),
        );

        if (onboardingFlow) {
          logger.debug('[PointerFlowProvider] Detected onboarding trigger in URL', {
            showOnboardingParam,
            flow: onboardingFlow.id,
            url: win.location.href,
          });

          pendingFlowStartsRef.current.push({
            flowId: onboardingFlow.id,
            userInitiated: true, // Treat URL parameters as user-initiated
          });
        }
      }
    } catch (error) {
      logger.error('[PointerFlowProvider] Error checking URL parameters', error);
    }
  }, [flows]);

  // Core flow actions
  const startFlow = React.useCallback(
    async (flowId: string, userInitiated: boolean = false) => {
      logger.debug('[PointerFlowProvider] Attempting to start flow', {
        flowId,
        isInitialized: isInitializedRef.current,
        isBackendAvailable,
        flowsRegistered: flowsRegisteredRef.current,
        userInitiated,
        isFirstPageLoad: isFirstPageLoadRef.current,
        flows: flows.map(f => ({ id: f.id, type: f.type })),
      });

      // Check if flow is completed - skip it unless it's a user-initiated action
      if (completedFlowIdsRef.current.has(flowId) && !userInitiated) {
        logger.debug('[PointerFlowProvider] Skipping completed flow start', {
          flowId,
          userInitiated,
        });
        return;
      }

      // Queue flow start requests that occur before initialization
      if (!isInitializedRef.current || !flowsRegisteredRef.current) {
        logger.debug('[PointerFlowProvider] Queueing flow start for after initialization', {
          flowId,
          userInitiated,
        });

        // Add to the queue if it's not already there
        if (!pendingFlowStartsRef.current.some(f => f.flowId === flowId)) {
          pendingFlowStartsRef.current.push({
            flowId,
            userInitiated: userInitiated || isFirstPageLoadRef.current, // Treat first page load requests as user-initiated
          });
        }

        // Only skip non-user-initiated flows - always try for user clicks
        if (!userInitiated && !isFirstPageLoadRef.current) {
          return;
        }
      }

      // Skip auto-triggered flows (non-user initiated) during initialization
      if (
        !userInitiated &&
        !isFirstPageLoadRef.current &&
        (!isInitializedRef.current || !flowsRegisteredRef.current)
      ) {
        logger.debug('[PointerFlowProvider] Skipping automatic flow start during initialization', {
          flowId,
          isInitialized: isInitializedRef.current,
          flowsRegistered: flowsRegisteredRef.current,
        });
        return;
      }

      if (!isInitializedRef.current) {
        logger.debug('[PointerFlowProvider] Cannot start flow - SDK not ready', {
          isInitialized: isInitializedRef.current,
          isBackendAvailable,
        });

        const MAX_RETRIES = 25; // Reduced from 50 to 25
        let retryCount = 0;

        // Queue the flow start for when we're initialized
        const checkInterval = setInterval(() => {
          retryCount++;
          if (isInitializedRef.current && flowsRegisteredRef.current) {
            logger.debug('[PointerFlowProvider] SDK ready after waiting, starting flow', {
              flowId,
            });

            // Try to get the flow again
            const flow = flowManager.current.getFlowById(flowId);
            if (flow) {
              flowManager.current.startFlow(flowId);
              clearInterval(checkInterval);
            } else {
              // Flow still not found even though we're initialized and flows are registered
              logger.error('[PointerFlowProvider] Flow not found after retry', {
                flowId,
                registeredFlows: flows.map(f => f.id),
              });

              // Attempt to register the specific flow if available
              const flowToRegister = flows.find(f => f.id === flowId);
              if (flowToRegister) {
                logger.debug('[PointerFlowProvider] Registering missing flow', { flowId });
                flowManager.current.registerFlow(flowToRegister);
                flowManager.current.startFlow(flowId);
              }

              clearInterval(checkInterval);
            }
          } else if (retryCount >= MAX_RETRIES) {
            logger.warn(
              '[PointerFlowProvider] Max retries reached waiting for SDK initialization',
              {
                flowId,
                retries: retryCount,
              },
            );
            clearInterval(checkInterval);
          }
        }, 100);

        // Clear interval after 2.5 seconds
        setTimeout(() => clearInterval(checkInterval), 2500);
        return;
      }

      // Check if backend is available before making API requests
      if (!isBackendAvailable) {
        // Check one more time in case the network just came back
        const canConnect = await apiService.canConnectToBackend();
        if (!canConnect) {
          logger.debug('[PointerFlowProvider] Cannot start flow - backend unavailable', {
            flowId,
          });
          // Start flow anyway, but mark as offline mode
          const flow = flowManager.current.getFlowById(flowId);
          if (flow) {
            flowManager.current.startFlow(flowId);
          }
          return;
        }
      }

      // Double check if flows are registered before attempting to start
      if (!flowsRegisteredRef.current) {
        logger.debug('[PointerFlowProvider] Flows not yet registered, registering now', {
          flowId,
          flows: flows.map(f => f.id),
        });

        // Force register all flows to ensure the flow can be started
        flows.forEach(flow => {
          flowManager.current.registerFlow(flow);
        });
        flowsRegisteredRef.current = true;
      }

      const flow = flowManager.current.getFlowById(flowId);

      if (!flow) {
        logger.error('[PointerFlowProvider] Flow not found', {
          flowId,
          registeredFlows: flows.map(f => f.id),
        });

        // Attempt to register the specific flow as a last resort
        const flowToRegister = flows.find(f => f.id === flowId);
        if (flowToRegister) {
          logger.debug('[PointerFlowProvider] Registering missing flow as last resort', { flowId });
          flowManager.current.registerFlow(flowToRegister);
          flowManager.current.startFlow(flowId);
        }
        return;
      }

      // Start the flow in FlowManager first
      flowManager.current.startFlow(flowId);

      if (flow.type === 'composite') {
        // Check localStorage for existing state
        const storage = getStorage();
        const localStorageKey = 'pointer-onboarding-state';
        const flowStateKey = 'pointer-flow-state';
        const savedState = storage.getItem(`${localStorageKey}-${flowId}`);
        const flowState = storage.getItem(`${flowStateKey}-${flowId}`);

        let hasSeenWelcomeModal = false;
        let isPermanentlyDismissed = false;

        // Check both storage locations for state
        if (savedState) {
          try {
            const state = JSON.parse(savedState);
            hasSeenWelcomeModal = state.isWelcomeModalOpen === false;
            isPermanentlyDismissed = state.isPermanentlyDismissed === true;
          } catch (e) {
            logger.error('[PointerFlowProvider] Error reading localStorage state', e);
          }
        }

        if (flowState) {
          try {
            const state = JSON.parse(flowState);
            // If either storage indicates it's dismissed, respect that
            isPermanentlyDismissed =
              isPermanentlyDismissed || state.isPermanentlyDismissed === true;
          } catch (e) {
            logger.error('[PointerFlowProvider] Error reading flow state', e);
          }
        }

        const newState = {
          activeFlowId: flowId,
          isWelcomeModalOpen: !hasSeenWelcomeModal && !isPermanentlyDismissed, // Only show modal if we've seen it and it's not permanently dismissed, makes close button dismiss modal forever
          // Only show checklist if we've seen welcome modal AND it's not permanently dismissed
          isChecklistVisible: hasSeenWelcomeModal && !isPermanentlyDismissed,
          isPaused: false,
          // currentStep: 0,
        };

        // Update both states synchronously
        flowManager.current.updateState(newState);
        setFlowState(prevState => ({
          ...prevState,
          ...newState,
        }));
        setIsModalOpen(!hasSeenWelcomeModal);

        // Initialize localStorage if it doesn't exist
        if (!savedState) {
          const storageState = {
            flowId,
            isWelcomeModalOpen: true,
            isChecklistVisible: false,
            isPermanentlyDismissed: false,
            completedFlows: [],
          };

          storage.setItem(`${localStorageKey}-${flowId}`, JSON.stringify(storageState));
        }
      }
    },
    [isBackendAvailable, flows],
  );

  const stopFlow = React.useCallback(() => {
    // Don't attempt when disabled or backend unavailable
    if (disabled || !isBackendAvailable) {
      logger.debug('[PointerFlowContext] Cannot stop flow - SDK disabled or backend unavailable');
      return;
    }

    const activeFlow = flowManager.current.getActiveFlow();
    if (activeFlow) {
      flowManager.current.stopFlow(activeFlow.id);
    }
  }, [disabled, isBackendAvailable]);

  const pauseFlow = React.useCallback(() => {
    // Don't attempt when disabled or backend unavailable
    if (disabled || !isBackendAvailable) {
      logger.debug('[PointerFlowContext] Cannot pause flow - SDK disabled or backend unavailable');
      return;
    }

    const activeFlow = flowManager.current.getActiveFlow();
    if (activeFlow) {
      flowManager.current.pauseFlow(activeFlow.id);
    }
  }, [disabled, isBackendAvailable]);

  const resumeFlow = React.useCallback(() => {
    // Don't attempt when disabled or backend unavailable
    if (disabled || !isBackendAvailable) {
      logger.debug('[PointerFlowContext] Cannot resume flow - SDK disabled or backend unavailable');
      return;
    }

    const activeFlow = flowManager.current.getActiveFlow();
    if (activeFlow) {
      flowManager.current.resumeFlow(activeFlow.id);
    }
  }, [disabled, isBackendAvailable]);

  const nextStep = React.useCallback(() => {
    // Don't attempt when disabled or backend unavailable
    if (disabled || !isBackendAvailable) {
      logger.debug(
        '[PointerFlowContext] Cannot advance to next step - SDK disabled or backend unavailable',
      );
      return;
    }

    setIsThinking(true);
    setShowClickEffect(true);

    const activeFlow = flowManager.current.getActiveFlow();
    const activeSubflow = flowManager.current.getActiveSubflow();
    const currentFlow = activeSubflow || activeFlow;

    if (currentFlow?.type === 'simple' && currentFlow.steps) {
      const currentState = flowManager.current.getCurrentState();
      const currentStepIndex = currentState.currentStep;
      const totalSteps = currentFlow.steps.length;

      logger.debug('[UnifiedFlowContext] Processing next step', {
        currentStepIndex,
        totalSteps,
        flowId: currentFlow.id,
      });

      // Only proceed if we're within valid step bounds
      if (currentStepIndex >= 0 && currentStepIndex < totalSteps) {
        // If we're on the last step, complete the flow
        if (currentStepIndex === totalSteps - 1) {
          logger.debug('[UnifiedFlowContext] Completing flow on last step', {
            flowId: currentFlow.id,
            stepIndex: currentStepIndex,
          });
          flowManager.current.completeFlow(currentFlow.id);
        } else {
          // Otherwise, move to next step
          logger.debug('[UnifiedFlowContext] Moving to next step', {
            flowId: currentFlow.id,
            fromStep: currentStepIndex,
            toStep: currentStepIndex + 1,
          });
          flowManager.current.nextStep();
        }
      } else {
        logger.warn('[UnifiedFlowContext] Invalid step index detected', {
          currentStepIndex,
          totalSteps,
          flowId: currentFlow.id,
        });
      }
    }

    setTimeout(() => {
      setIsThinking(false);
      setShowClickEffect(false);
    }, 600);
  }, [disabled, isBackendAvailable]);

  const previousStep = React.useCallback(() => {
    // Don't attempt when disabled or backend unavailable
    if (disabled || !isBackendAvailable) {
      logger.debug(
        '[PointerFlowContext] Cannot go to previous step - SDK disabled or backend unavailable',
      );
      return;
    }

    flowManager.current.previousStep();
  }, [disabled, isBackendAvailable]);

  const jumpToStep = React.useCallback(
    (stepIndex: number) => {
      // Don't attempt when disabled or backend unavailable
      if (disabled || !isBackendAvailable) {
        logger.debug(
          '[PointerFlowContext] Cannot jump to step - SDK disabled or backend unavailable',
        );
        return;
      }

      const activeFlow = flowManager.current.getActiveFlow();
      if (activeFlow) {
        flowManager.current.jumpToStep(stepIndex);
      }
    },
    [disabled, isBackendAvailable],
  );

  const completeFlow = React.useCallback(
    (flowId: string) => {
      // Don't attempt when disabled or backend unavailable
      if (disabled || !isBackendAvailable) {
        logger.debug(
          '[PointerFlowContext] Cannot complete flow - SDK disabled or backend unavailable',
        );
        return;
      }

      flowManager.current.completeFlow(flowId);
    },
    [disabled, isBackendAvailable],
  );

  const startSubflow = React.useCallback(
    (subflowId: string) => {
      // Don't attempt when disabled or backend unavailable
      if (disabled || !isBackendAvailable) {
        logger.debug(
          '[PointerFlowContext] Cannot start subflow - SDK disabled or backend unavailable',
        );
        return;
      }

      const activeFlow = flowManager.current.getActiveFlow();
      if (activeFlow?.type === 'composite') {
        flowManager.current.startSubflow(activeFlow.id, subflowId);
      }
    },
    [disabled, isBackendAvailable],
  );

  const completeSubflow = React.useCallback(
    (subflowId: string) => {
      // Don't attempt when disabled or backend unavailable
      if (disabled || !isBackendAvailable) {
        logger.debug(
          '[PointerFlowContext] Cannot complete subflow - SDK disabled or backend unavailable',
        );
        return;
      }

      const activeFlow = flowManager.current.getActiveFlow();
      if (activeFlow?.type === 'composite') {
        flowManager.current.completeFlow(subflowId);
      }
    },
    [disabled, isBackendAvailable],
  );

  // Function to check element visibility
  const checkElementVisibility = useCallback(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;
    const doc = getDocument();
    if (!doc) return;

    const activeFlow = flowManager.current.getActiveFlow();
    const activeSubflow = flowManager.current.getActiveSubflow();
    const currentFlow = activeSubflow || activeFlow;

    if (
      currentFlow?.type === 'simple' &&
      currentFlow.steps &&
      currentFlow.steps[flowState.currentStep]
    ) {
      try {
        const currentStep = currentFlow.steps[flowState.currentStep];
        const element = doc.querySelector(`#${currentStep.position || currentStep.id}`);

        if (element) {
          const rect = element.getBoundingClientRect();
          const viewportHeight = win.innerHeight;

          // Larger buffer for top elements to prevent aggressive up-scroll indicators
          const topBuffer = rect.top < 100 ? 0 : 100; // No buffer for nav elements
          const bottomBuffer = 100;

          // Calculate how much of the element is visible
          const elementHeight = rect.height;
          const visibleHeight = Math.min(rect.bottom, viewportHeight) - Math.max(rect.top, 0);
          const visibilityRatio = visibleHeight / elementHeight;

          // Only show indicators if element is significantly out of view (less than 50% visible)
          if (rect.bottom < topBuffer && visibilityRatio < 0.5) {
            setScrollDirection('up');
          } else if (rect.top > viewportHeight - bottomBuffer && visibilityRatio < 0.5) {
            setScrollDirection('down');
          } else {
            setScrollDirection(null);
          }
        } else {
          setScrollDirection(null);
        }
      } catch (error) {
        setScrollDirection(null);
      }
    }
  }, [flowState.currentStep]);

  // Check visibility on mount, step changes, and after any position updates
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;
    const activeFlow = flowManager.current.getActiveFlow();
    if (activeFlow && !flowState.isPaused) {
      checkElementVisibility();
      const scrollHandler = () => {
        requestAnimationFrame(checkElementVisibility);
      };
      win.addEventListener('scroll', scrollHandler, { passive: true });

      // Check position adjustments less frequently with timeout
      const startTime = Date.now();
      const MAX_VISIBILITY_CHECK_DURATION = 10000; // 10 seconds maximum search time

      const positionCheckTimer = setInterval(() => {
        // Stop checking after the maximum duration if element not found
        if (Date.now() - startTime > MAX_VISIBILITY_CHECK_DURATION) {
          clearInterval(positionCheckTimer);
          logger.debug('Element visibility check timeout', {
            duration: `${MAX_VISIBILITY_CHECK_DURATION / 1000} seconds`,
            flow: activeFlow?.id,
            step: flowState.currentStep,
          });
          return;
        }

        checkElementVisibility();
      }, 250);

      return () => {
        win.removeEventListener('scroll', scrollHandler);
        clearInterval(positionCheckTimer);
      };
    } else {
      setScrollDirection(null);
    }
  }, [checkElementVisibility, flowState.isPaused, flowState.currentStep]);

  // Position tracking effect
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;
    const doc = getDocument();
    if (!doc) return;

    const activeFlow = flowManager.current.getActiveFlow();
    const activeSubflow = flowManager.current.getActiveSubflow();
    const currentFlow = activeSubflow || activeFlow;

    // Reset positions immediately when step changes
    setTargetPosition({ top: 0, left: 0, width: 0, height: 0 });
    setPointerPosition({ top: 0, left: 0 });

    if (
      currentFlow &&
      !flowState.isPaused &&
      !flowState.isWelcomeModalOpen &&
      !flowState.isChecklistVisible
    ) {
      if (currentFlow.type === 'simple' && currentFlow.steps) {
        const currentStep = currentFlow.steps[flowState.currentStep];

        if (currentStep) {
          // Clean up existing tracking
          if (positionCleanupRef.current) {
            positionCleanupRef.current();
            positionCleanupRef.current = null;
          }

          // Add a small delay to allow for DOM updates
          const updateTimer = setTimeout(() => {
            const elementSelector = `#${currentStep.position || currentStep.id}`;
            const element = doc.querySelector(elementSelector);

            if (element) {
              // Start new position tracking
              const cleanup = updatePointerPosition(
                {
                  id: currentStep.position || currentStep.id,
                  position: elementSelector,
                  instructions: currentStep.content.description,
                  page: currentStep.page || '',
                  action: currentStep.action,
                },
                (newPosition: { top: number; left: number }) => {
                  setPointerPosition(newPosition);
                },
                (newTargetPosition: {
                  top: number;
                  left: number;
                  width: number;
                  height: number;
                }) => {
                  setTargetPosition(newTargetPosition);
                },
                // () => {
                //   setTargetPosition({ top: 0, left: 0, width: 0, height: 0 });
                //   setPointerPosition({ top: 0, left: 0 });
                //   flowManager.current.stopFlow(currentFlow.id);
                // },
              );

              positionCleanupRef.current = cleanup;
            }
          }, 100); // Small delay to allow for DOM updates

          return () => {
            clearTimeout(updateTimer);
            if (positionCleanupRef.current) {
              // positionCleanupRef.current();
              positionCleanupRef.current = null;
            }
          };
        }
      }
    }

    return () => {
      if (positionCleanupRef.current) {
        positionCleanupRef.current();
        positionCleanupRef.current = null;
      }
    };
  }, [
    flowState.currentStep,
    flowState.isPaused,
    flowState.isWelcomeModalOpen,
    flowState.isChecklistVisible,
  ]);

  // Set accent color
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const win = getWindow();
    if (!win) return;
    const doc = getDocument();
    if (!doc) return;

    if (accentColor) {
      // Set the CSS variable directly
      doc.documentElement.style.setProperty(
        '--pointer-accent-color',
        typeof accentColor === 'string'
          ? accentColor
          : accentColor[doc.documentElement.dataset.pointerThemeMode === 'dark' ? 'dark' : 'light'],
      );
    }
  }, [accentColor]);

  // Add an effect to monitor flow state changes
  React.useEffect(() => {
    logger.debug('[PointerFlowProvider] Flow state changed', {
      activeFlowId: flowState.activeFlowId,
      isWelcomeModalOpen: flowState.isWelcomeModalOpen,
      isChecklistVisible: flowState.isChecklistVisible,
      currentFlow: flowManager.current.getActiveFlow()?.id,
    });
  }, [flowState]);

  // Add state change subscription
  useEffect(() => {
    const handleStateChange = (newState: FlowState) => {
      setFlowState(newState);
    };

    // Subscribe to state changes
    const unsubscribe = flowManager.current.subscribe(handleStateChange);
    return () => unsubscribe();
  }, []);

  // Define openModal and closeModal as useCallbacks before the contextValue definition
  const openModal = useCallback(() => setIsModalOpen(true), []);
  const closeModal = useCallback(() => setIsModalOpen(false), []);

  // Optimize getFlowProgress with memoization
  const getFlowProgress = useCallback((flowId: string) => {
    const state = flowManager.current.getCurrentState();
    const flow = flowManager.current.getFlowState(flowId);
    const isCompleted = state.completedFlows.has(flowId);

    // Get the flow definition to check if it's a composite flow
    const flowDefinition = flowManager.current.getFlowById(flowId);

    if (flowDefinition?.type === 'composite') {
      const totalSubflows = flowDefinition.subflows.length;
      const completedSubflows = flowDefinition.subflows.filter((subflow: { id: string }) =>
        state.completedFlows.has(subflow.id),
      ).length;

      return {
        isCompleted,
        currentStep: 0,
        completedSteps: new Set<number>(),
        totalSteps: totalSubflows,
        percentage: isCompleted
          ? 100
          : totalSubflows > 0
            ? Math.round((completedSubflows / totalSubflows) * 100)
            : 0,
      };
    }

    if (!flow) {
      return {
        isCompleted,
        currentStep: 0,
        completedSteps: new Set<number>(),
        totalSteps: 0,
        percentage: isCompleted ? 100 : 0,
      };
    }

    const activeFlow = flowManager.current.getActiveFlow();
    const totalSteps =
      activeFlow?.type === 'simple' && 'steps' in activeFlow ? activeFlow.steps?.length || 0 : 0;

    return {
      isCompleted,
      currentStep: flow.currentStep,
      completedSteps: flow.completedSteps,
      totalSteps,
      percentage: isCompleted ? 100 : Math.round((flow.completedSteps.size / totalSteps) * 100),
    };
  }, []);

  const contextValue = React.useMemo(
    () => ({
      activeFlow: flowManager.current.getActiveFlow(),
      flowState,
      isEnabled: !disabled && isBackendAvailable,
      isInitialized: isInitializedRef.current,
      startFlow,
      stopFlow,
      pauseFlow,
      resumeFlow,
      nextStep,
      previousStep,
      jumpToStep,
      completeFlow,
      startSubflow,
      completeSubflow,
      pointerPosition,
      targetPosition,
      isThinking,
      showClickEffect,
      scrollDirection,
      isModalOpen,
      openModal,
      closeModal,
      currentStepType: null,
      showChecklist: (flowId: string) => {
        // Check if SDK is disabled or backend is unavailable
        if (disabled || !isBackendAvailable) {
          logger.debug(
            '[PointerFlowContext] Cannot show checklist - SDK disabled or backend unavailable',
            {
              disabled,
              isBackendAvailable,
              flowId,
            },
          );
          return;
        }

        // Start the specified flow if it's not already active
        if (
          !flowManager.current.getActiveFlow() ||
          flowManager.current.getActiveFlow()?.id !== flowId
        ) {
          flowManager.current.startFlow(flowId);
        }

        // Call the FlowManager's showChecklist method with the flowId and mark it as a manual trigger
        flowManager.current.showChecklist(flowId, true);

        // Force a local state update to ensure the UI refreshes
        // This is a backup in case the FlowManager state update doesn't trigger a re-render
        if (flowState.isChecklistVisible) {
          setFlowState(prevState => ({
            ...prevState,
            isChecklistVisible: false,
          }));

          // Then set it back to true after a short delay
          setTimeout(() => {
            setFlowState(prevState => ({
              ...prevState,
              isChecklistVisible: true,
            }));
          }, 10);
        }
      },
      getFlowProgress,
    }),
    [
      flowState,
      disabled,
      isBackendAvailable,
      startFlow,
      stopFlow,
      pauseFlow,
      resumeFlow,
      nextStep,
      previousStep,
      jumpToStep,
      completeFlow,
      startSubflow,
      completeSubflow,
      pointerPosition,
      targetPosition,
      isThinking,
      showClickEffect,
      scrollDirection,
      isModalOpen,
      openModal,
      closeModal,
      getFlowProgress,
    ],
  );

  const activeFlow = flowManager.current.getActiveFlow();
  const activeSubflow = flowManager.current.getActiveSubflow();
  const currentFlow = activeSubflow || activeFlow;

  // Derive an actual name from userData or fall back to userFirstName
  const userName = React.useMemo(() => {
    if (userData?.name) {
      // Extract first name from full name if possible
      const firstName = userData.name.split(' ')[0];
      return firstName;
    }
    return userFirstName || undefined;
  }, [userData, userFirstName]);

  return (
    <ThemeProvider customization={customization}>
      <UnifiedFlowContext.Provider value={contextValue}>
        {children}
        {/* Only render flow components if initialized, available, and not disabled */}
        {isInitializedRef.current && isBackendAvailable && !disabled && (
          <>
            {/* Welcome modal */}
            {currentFlow &&
              !flowState.isPaused &&
              flowState.isWelcomeModalOpen &&
              activeFlow?.type === 'composite' &&
              (() => {
                // Check localStorage before showing modal
                const storage = getStorage();
                const localStorageKey = 'pointer-onboarding-state';
                const savedState = storage.getItem(`${localStorageKey}-${activeFlow.id}`);

                if (savedState) {
                  try {
                    const state = JSON.parse(savedState);
                    // Only skip the modal if we've already seen it (isWelcomeModalOpen was false)
                    if (state.isWelcomeModalOpen === false) {
                      flowManager.current.updateState({
                        isWelcomeModalOpen: false,
                        isChecklistVisible: true,
                      });
                      return null;
                    }
                  } catch (e) {
                    logger.error('[FlowModal] Error reading localStorage state', e);
                  }
                }

                // If no saved state or modal hasn't been shown yet, show the modal
                return (
                  <FlowModal
                    workflow={{
                      id: activeFlow.id,
                      welcomeHeading: activeFlow.welcome.title,
                      welcomeSubheading: activeFlow.welcome.subtitle,
                      welcomeDescription: activeFlow.welcome.description,
                      welcomeImage: activeFlow.welcome.image,
                      buttonText: activeFlow.welcome.buttonText,
                      guides: [],
                      currentGuideIndex: 0,
                    }}
                    onComplete={() => {
                      setIsModalOpen(false);

                      // Update flow state to show checklist
                      flowManager.current.updateState({
                        isWelcomeModalOpen: false,
                        isChecklistVisible: true,
                      });

                      // Update localStorage state to remember we've shown the modal
                      const storage = getStorage();
                      const localStorageKey = 'pointer-onboarding-state';
                      const currentState = {
                        flowId: activeFlow.id,
                        isWelcomeModalOpen: false,
                        isChecklistVisible: true,
                        isPermanentlyDismissed: false,
                        completedFlows: [],
                      };

                      // Try to merge with existing state if it exists
                      const existingState = storage.getItem(`${localStorageKey}-${activeFlow.id}`);
                      if (existingState) {
                        try {
                          const parsedState = JSON.parse(existingState);
                          Object.assign(currentState, parsedState, {
                            isWelcomeModalOpen: false,
                            isChecklistVisible: true,
                          });
                        } catch (e) {
                          logger.error('[FlowModal] Error reading existing state', e);
                        }
                      }

                      storage.setItem(
                        `${localStorageKey}-${activeFlow.id}`,
                        JSON.stringify(currentState),
                      );
                    }}
                    onDismiss={() => {
                      setIsModalOpen(false);
                      flowManager.current.stopFlow(activeFlow.id);
                    }}
                    isEnabled={true}
                    mode="modal"
                    logomark={logomark}
                    autoScroll={currentFlow.autoScroll}
                  />
                );
              })()}

            {/* Checklist - always show when isChecklistVisible is true and we have an active flow */}
            {flowState.isChecklistVisible && activeFlow?.type === 'composite' && (
              <>
                <FlowChecklist
                  workflow={{
                    id: activeFlow.id,
                    welcomeHeading: activeFlow.welcome.title,
                    welcomeSubheading: activeFlow.welcome.subtitle,
                    welcomeDescription: activeFlow.welcome.description,
                    welcomeImage: activeFlow.welcome.image,
                    currentGuideIndex: 0,
                    guides: activeFlow.subflows.map(subflow => ({
                      id: subflow.id,
                      title: subflow.name,
                      description: subflow.description || '',
                      buttonText: subflow.buttonText || 'Start',
                      // Use completedFlowIdsRef.current for most up-to-date completion status
                      // This ensures sync updates are reflected immediately
                      completed:
                        completedFlowIdsRef.current.has(subflow.id) ||
                        flowState.completedFlows.has(subflow.id),
                      allowRetrigger: subflow.allowRetrigger,
                      currentStepIndex: flowState.flowProgress[subflow.id]?.currentStep || 0,
                      steps:
                        subflow.steps?.map(step => ({
                          id: step.id,
                          type: step.type || 'guided',
                          position: step.position || step.id,
                          page: step.page || subflow.page || '',
                          content: {
                            title: step.content.title,
                            description: step.content.description,
                            media: step.content.media,
                          },
                          action: step.action,
                          showCloseButton: step.showCloseButton,
                        })) || [],
                    })),
                    checklistConfig: activeFlow.checklistConfig,
                  }}
                  userFirstName={userName}
                  onGuideStart={startSubflow}
                  onGuideComplete={completeSubflow}
                  onClose={stopFlow}
                  pointerPosition={pointerPosition}
                  handleNextStep={nextStep}
                  widgetHeader={activeFlow.checklistConfig?.header || 'Getting started 👋'}
                  stopActiveGuide={() => {
                    const activeSubflowId = flowState.activeSubflowId;
                    if (activeSubflowId) {
                      flowManager.current.updateState({
                        activeSubflowId: null,
                        isChecklistVisible: true,
                      });
                    }
                  }}
                  scrollDirection={scrollDirection}
                  autoScroll={activeFlow.autoScroll}
                />
              </>
            )}

            {/* Flow steps */}
            {currentFlow &&
              !flowState.isPaused &&
              !flowState.isWelcomeModalOpen &&
              !flowState.isChecklistVisible &&
              currentFlow.type === 'simple' &&
              currentFlow.steps && (
                <>
                  <FlowStep
                    stepId={
                      currentFlow.steps[flowState.currentStep].position ||
                      currentFlow.steps[flowState.currentStep].id
                    }
                    instructions={currentFlow.steps[flowState.currentStep].content.description}
                    isLastStep={flowState.currentStep === currentFlow.steps.length - 1}
                    onNextStep={nextStep}
                    onPreviousStep={previousStep}
                    onStopGuide={stopFlow}
                    position={pointerPosition}
                    currentStep={flowState.currentStep + 1}
                    totalSteps={currentFlow.steps.length}
                    action={currentFlow.steps[flowState.currentStep].action}
                    scrollDirection={scrollDirection}
                    onWalkthroughEnd={() => {
                      nextStep();
                    }}
                    type={currentFlow.steps[flowState.currentStep].type || 'guided'}
                    content={currentFlow.steps[flowState.currentStep].content}
                    showCloseButton={currentFlow.steps[flowState.currentStep].showCloseButton}
                    pollDuration={currentFlow.steps[flowState.currentStep].pollDuration}
                    autoScroll={currentFlow.autoScroll}
                  />
                </>
              )}

            {/* Completion popup */}
            {showCompletionPopup && (
              <>
                <div
                  style={{
                    position: 'fixed',
                    bottom: 0,
                    left: 0,
                    right: 0,
                    height: '100vh',
                    pointerEvents: 'none',
                    opacity: isVisible ? 1 : 0,
                    transition: 'opacity 0.5s ease-out',
                  }}>
                  <Confetti
                    mode="boom"
                    particleCount={50}
                    colors={['#ff577f', '#ff884b', '#ffd384', '#fff9b0']}
                    effectCount={1}
                    effectInterval={1500}
                    y={0.85}
                  />
                </div>
                <div
                  style={{
                    position: 'fixed',
                    bottom: '32px',
                    left: '50%',
                    transform: 'translateX(-50%)',
                    backgroundColor: 'var(--pointer-background-color)',
                    padding: '8px 16px',
                    borderRadius: 'var(--pointer-border-radius)',
                    border: '1px solid var(--pointer-border-color)',
                    boxShadow: '0 4px 24px -4px rgba(0, 0, 0, 0.08)',
                    zIndex: 99999,
                    animation: 'slideUpAndFade 0.3s ease-out',
                    fontSize: '14px',
                    fontWeight: 500,
                    color: 'var(--pointer-secondary-color)',
                    opacity: isVisible ? 1 : 0,
                    transition: 'opacity 0.5s ease-out',
                  }}>
                  <style>
                    {`
                      @keyframes slideUpAndFade {
                        from { 
                          opacity: 0; 
                          transform: translate(-50%, 16px); 
                        }
                        to { 
                          opacity: 1; 
                          transform: translate(-50%, 0); 
                        }
                      }
                    `}
                  </style>
                  {activeFlow?.type === 'composite' && flowState.completedFlows.has(activeFlow.id)
                    ? "🎉 Congratulations! You've completed the onboarding!"
                    : "✨ Great job! You've completed this guide!"}
                </div>
              </>
            )}
          </>
        )}
      </UnifiedFlowContext.Provider>
    </ThemeProvider>
  );
};

export const useFlow = () => {
  const context = useContext(UnifiedFlowContext);
  if (!context) {
    throw new Error('useFlow must be used within a UnifiedFlowProvider');
  }
  return context;
};
