import axios, { type AxiosInstance, type AxiosError } from 'axios';
import type {
  ElementMapping,
  BaseMessage,
  APIConversation,
  EndUserData,
  FlowCompletion,
  UserEvent,
} from '../types';
import { ServerConnectionError, ProjectIdError, ERROR_MESSAGES } from '../errors';
import { authService } from './auth';

import { logger } from '../utils/logger';
interface ErrorResponse {
  code?: string;
  error?: string;
}

class ApiService {
  private static instance: ApiService;
  private api: AxiosInstance | null = null;
  private isProjectIdVerified = false;
  private readonly MAX_RETRIES = 3;
  private readonly BASE_DELAY = 1000;
  private readonly MAX_DELAY = 10000;
  private isBackendAvailable = true;
  private initializationPromise: Promise<AxiosInstance | null> | null = null;
  private lastInitAttemptTime = 0;
  private readonly MIN_INIT_INTERVAL = 900000; // 15 minutes

  // Cache for user data
  private userDataCache: {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    data: any;
    timestamp: number;
  } | null = null;
  private USER_DATA_CACHE_DURATION = 900000; // 15 minutes
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private userDataPromise: Promise<any> | null = null;

  private constructor() {}

  public static getInstance(): ApiService {
    if (!ApiService.instance) {
      ApiService.instance = new ApiService();
    }
    return ApiService.instance;
  }

  private async withAuth<T>(operation: () => Promise<T>): Promise<T> {
    // Skip API operation if the backend is known to be unavailable
    if (!this.isBackendAvailable) {
      logger.debug('Skipping API operation - backend is marked as unavailable');
      throw new ServerConnectionError(ERROR_MESSAGES.SERVER_CONNECTION_FAILED);
    }

    await this.ensureApiInstance();
    return operation();
  }

  private async ensureApiInstance(): Promise<AxiosInstance> {
    if (!this.initializationPromise) {
      // Return a promise that resolves when initialization is complete
      this.initializationPromise = this._ensureApiInstance().finally(() => {
        this.initializationPromise = null;
      });
    }
    const api = await this.initializationPromise;
    if (!api) {
      throw new ServerConnectionError(ERROR_MESSAGES.SERVER_CONNECTION_FAILED);
    }
    return api;
  }

  private async _ensureApiInstance(): Promise<AxiosInstance | null> {
    const now = Date.now();
    if (now - this.lastInitAttemptTime < this.MIN_INIT_INTERVAL && !this.isProjectIdVerified) {
      logger.debug(
        `Initialization was attempted recently (${Math.floor((now - this.lastInitAttemptTime) / 1000)}s ago). Skipping.`,
      );
      return this.api;
    }

    this.lastInitAttemptTime = now;

    if (!this.isBackendAvailable) {
      throw new ServerConnectionError(ERROR_MESSAGES.SERVER_CONNECTION_FAILED);
    }

    const projectId = authService.getProjectId();
    if (!projectId) {
      throw new ProjectIdError(ERROR_MESSAGES.INVALID_PROJECT_ID);
    }

    if (!this.api || !this.isProjectIdVerified) {
      try {
        // Get initial auth headers
        const headers = await authService.getAuthHeaders();

        // Create API instance with the headers
        this.api = axios.create({
          baseURL: authService.getApiUrl(),
          headers: {
            'Content-Type': 'application/json',
            ...headers,
          },
          timeout: 10000,
        });

        // Initialize session if needed
        if (!authService.getSessionId()) {
          try {
            let sessionInitialized = false;
            let retryCount = 0;
            const maxRetries = this.MAX_RETRIES;
            const baseDelay = this.BASE_DELAY;

            while (!sessionInitialized && retryCount < maxRetries) {
              try {
                logger.debug(
                  `Attempting to initialize session (attempt ${retryCount + 1}/${maxRetries})`,
                );

                const response = await this.api.get('/api-key-auth');

                if (response.headers['x-session-id']) {
                  authService.setSessionId(response.headers['x-session-id']);
                  sessionInitialized = true;
                  logger.debug('Session initialized successfully');
                } else {
                  throw new Error('No session ID received from server');
                }
              } catch (sessionError) {
                retryCount++;

                // Enhanced error logging with detailed diagnostics
                if (axios.isAxiosError(sessionError)) {
                  if (!sessionError.response) {
                    // Network error (no response from server)
                    logger.warn(
                      `Network error during session initialization (attempt ${retryCount}/${maxRetries}):`,
                      {
                        message: sessionError.message,
                        code: sessionError.code,
                        url: sessionError.config?.url,
                        baseURL: sessionError.config?.baseURL,
                      },
                    );

                    // Check for DNS resolution issues or if the server is unreachable
                    if (
                      sessionError.code === 'ENOTFOUND' ||
                      sessionError.code === 'ECONNREFUSED' ||
                      sessionError.code === 'ETIMEDOUT'
                    ) {
                      logger.error(
                        `Connection error with code ${sessionError.code}. Server may be unreachable.`,
                      );

                      // If this is our last retry, mark as unavailable but don't throw
                      if (retryCount >= maxRetries) {
                        logger.error(`Max retries (${maxRetries}) reached. Connection failed.`);
                        this.isBackendAvailable = false;
                        // Break out of the retry loop
                        break;
                      }
                    }
                  } else if (sessionError.response.status === 429) {
                    // Rate limit error handling (existing code)
                    const retryAfter = sessionError.response.headers['retry-after'];
                    const delayMs = retryAfter
                      ? parseInt(retryAfter, 10) * 1000
                      : baseDelay * Math.pow(2, retryCount);

                    logger.warn(
                      `Rate limit reached during session initialization (attempt ${retryCount}/${maxRetries}):`,
                      {
                        retryAfter: retryAfter || 'not specified',
                        calculatedDelay: `${delayMs}ms`,
                        status: sessionError.response.status,
                      },
                    );

                    if (retryCount < maxRetries) {
                      logger.debug(`Waiting ${delayMs}ms before next attempt...`);
                      await new Promise(resolve => setTimeout(resolve, delayMs));
                      continue;
                    }
                  } else {
                    // Server returned an error response
                    logger.warn(
                      `Server error during session initialization (attempt ${retryCount}/${maxRetries}):`,
                      {
                        status: sessionError.response.status,
                        data: sessionError.response.data,
                        url: sessionError.config?.url,
                      },
                    );
                  }
                } else {
                  // Non-Axios error
                  logger.warn(
                    `Unexpected error during session initialization (attempt ${retryCount}/${maxRetries}):`,
                    sessionError instanceof Error ? sessionError.message : 'Unknown error',
                  );
                }

                if (retryCount < maxRetries) {
                  const delay = Math.min(baseDelay * Math.pow(2, retryCount - 1), this.MAX_DELAY);
                  logger.debug(`Retrying in ${delay}ms...`);
                  await new Promise(resolve => setTimeout(resolve, delay));
                  continue;
                }

                // If we've exhausted all retries, mark as unavailable but don't throw
                if (retryCount >= maxRetries) {
                  logger.error(`Failed to initialize session after ${maxRetries} attempts`);
                  this.isBackendAvailable = false;
                  // No need to throw - just break out of retry loop
                  break;
                }
              }
            }

            // If we couldn't initialize a session after all retries, still proceed
            // The SDK will work in offline mode
            if (!sessionInitialized) {
              logger.warn('Proceeding without server session. SDK will operate in offline mode.');
              this.isBackendAvailable = false;
            }
          } catch (outerError) {
            // Catch any uncaught errors in the session initialization process
            logger.error('Unexpected error during session initialization process:', outerError);
            this.isBackendAvailable = false;
            // Don't re-throw - allow SDK to work in offline mode
          }
        }

        // Set up interceptors (continue even if session init failed)
        this.setupInterceptors();

        // Even if we failed to initialize session, mark key as verified
        // so we don't repeatedly try to initialize on every API call
        this.isProjectIdVerified = true;
      } catch (error) {
        logger.debug('Failed to initialize API service:', error);
        this.isProjectIdVerified = false;
        this.isBackendAvailable = false;

        // Enhanced error logging
        if (axios.isAxiosError(error)) {
          logger.error('API initialization failed with Axios error:', {
            message: error.message,
            code: error.code,
            url: error.config?.url,
            baseURL: error.config?.baseURL,
            response: error.response
              ? {
                  status: error.response.status,
                  data: error.response.data,
                }
              : 'No response',
          });
        } else {
          logger.error(
            'API initialization failed with non-Axios error:',
            error instanceof Error ? error.message : 'Unknown error',
          );
        }

        if (error instanceof ProjectIdError) {
          throw error;
        }
        // If it's already a ServerConnectionError, throw it directly
        if (error instanceof ServerConnectionError) {
          throw error;
        }

        // Provide more specific error messages based on error type
        if (axios.isAxiosError(error)) {
          if (!error.response) {
            // Network error
            if (error.code === 'ENOTFOUND') {
              throw new ServerConnectionError(
                `${ERROR_MESSAGES.SERVER_CONNECTION_FAILED} - DNS resolution failed. Check your internet connection or API URL.`,
              );
            } else if (error.code === 'ECONNREFUSED') {
              throw new ServerConnectionError(
                `${ERROR_MESSAGES.SERVER_CONNECTION_FAILED} - Connection refused. The server may be down or unreachable.`,
              );
            } else if (error.code === 'ETIMEDOUT' || error.code === 'TIMEOUT') {
              throw new ServerConnectionError(
                `${ERROR_MESSAGES.SERVER_CONNECTION_FAILED} - Connection timed out. The server may be unresponsive.`,
              );
            }
            throw new ServerConnectionError(
              `${ERROR_MESSAGES.SERVER_CONNECTION_FAILED} - Network error: ${error.message}`,
            );
          }
        }

        throw new ServerConnectionError(ERROR_MESSAGES.SERVER_CONNECTION_FAILED);
      }
    }
    return this.api;
  }

  private setupInterceptors(): void {
    if (!this.api) return;

    // Add response interceptor for session management
    this.api.interceptors.response.use(
      response => {
        if (response.headers['x-session-rotated'] === 'true') {
          authService.setSessionId(response.headers['x-session-id']);
        }
        return response;
      },
      async (error: AxiosError) => {
        if (error.response?.status === 401) {
          const code = (error.response.data as ErrorResponse)?.code;
          if (code === 'SESSION_EXPIRED' || code === 'SESSION_INACTIVE') {
            authService.setSessionId('');
            return this.api?.request(error.config!);
          }
          this.isProjectIdVerified = false;
          throw new ProjectIdError(ERROR_MESSAGES.INVALID_PROJECT_ID);
        }
        throw error;
      },
    );

    // Add request interceptor for auth headers
    this.api.interceptors.request.use(async config => {
      const headers = await authService.getAuthHeaders(config.data || {});
      Object.entries(headers).forEach(([key, value]) => {
        config.headers.set(key, value);
      });
      return config;
    });
  }

  private async delay(attempt: number): Promise<void> {
    const exponentialDelay = this.BASE_DELAY * Math.pow(2, attempt);
    const jitter = Math.random() * 100;
    const delay = Math.min(exponentialDelay + jitter, this.MAX_DELAY);
    return new Promise(resolve => setTimeout(resolve, delay));
  }

  private async withRetry<T>(operation: () => Promise<T>): Promise<T> {
    let lastError: Error | null = null;
    for (let attempt = 0; attempt < this.MAX_RETRIES; attempt++) {
      try {
        return await operation();
      } catch (error) {
        lastError = error as Error;
        if (error instanceof ProjectIdError) {
          throw error;
        }
        if (attempt < this.MAX_RETRIES - 1) {
          await this.delay(attempt);
          continue;
        }
      }
    }
    throw lastError || new Error('Operation failed after retries');
  }

  public async initialize(projectId: string, storage: Storage, apiUrl?: string): Promise<void> {
    // Initialize auth service first
    await authService.initialize(projectId, storage, apiUrl);

    try {
      // Now try to verify API connection, but don't let failure block initialization
      await this.ensureApiInstance();
    } catch (error) {
      logger.warn('Failed to initialize API connection during SDK setup:', error);
      // We don't re-throw here - just log the error and continue
      // The SDK will try again when specific API operations are requested
    }
  }

  // Conversation endpoints
  public async createConversation(): Promise<APIConversation> {
    return this.withAuth(async () => {
      const response = await this.api!.post<APIConversation>(
        '/conversations/sdk/projects/conversations',
      );
      return response.data;
    });
  }

  public async getConversation(conversationId: string): Promise<APIConversation> {
    return this.withAuth(async () => {
      const response = await this.api!.get<APIConversation>(`/conversations/sdk/${conversationId}`);
      return response.data;
    });
  }

  public async getConversationMessages(conversationId: string): Promise<BaseMessage[]> {
    return this.withAuth(async () => {
      const response = await this.api!.get<BaseMessage[]>(
        `/conversations/sdk/${conversationId}/messages`,
      );
      return response.data;
    });
  }

  public async submitGuideFeedback(
    guideId: string,
    positive: boolean,
    comments?: string,
  ): Promise<void> {
    return this.withRetry(async () => {
      const api = await this.ensureApiInstance();
      const payload = {
        guideId,
        positive,
        ...(comments && { comments }),
      };
      await api.post('/feedback/api-key/guides', payload);
    });
  }

  public async getAssistantResponse(
    message: string,
    conversationId: string | undefined,
    uiElements: ElementMapping[],
    onData: (data: string) => void,
    onError: (err: Error) => void,
    onComplete: () => void,
  ): Promise<void> {
    try {
      await this.ensureApiInstance();
      const baseUrl = this.api!.defaults.baseURL;
      const body = { message, conversationId, uiElements };
      const headers = await authService.getAuthHeaders(body);

      const response = await fetch(`${baseUrl}/conversations/assistant/respond`, {
        method: 'POST',
        headers: {
          Accept: 'text/event-stream',
          'Content-Type': 'application/json',
          ...headers,
        },
        body: JSON.stringify(body),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      if (!response.body) {
        throw new Error('No response body received');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await reader.read();
        if (done) {
          logger.debug('Pointer SDK: Stream complete');
          onComplete();
          break;
        }

        const text = decoder.decode(value);
        const lines = text.split(/\n/);
        for (const line of lines) {
          if (line === '') continue;
          const cleanChunk = line.replace(/^data: /, '');

          if (cleanChunk.includes('[DONE]')) {
            continue;
          }

          onData(cleanChunk);
        }
      }
    } catch (error) {
      logger.error('Pointer SDK: Assistant response error:', error);
      if (error instanceof ProjectIdError) {
        onError(error);
      } else {
        onError(new ServerConnectionError(ERROR_MESSAGES.API_REQUEST_FAILED));
      }
    }
  }

  public async verifyProjectId(): Promise<void> {
    logger.debug('Pointer SDK: Verifying project ID');
    await this.ensureApiInstance();
    logger.debug('Pointer SDK: Project ID verification successful');
  }

  public async reset(): Promise<void> {
    this.api = null;
    this.isProjectIdVerified = false;
    this.isBackendAvailable = true;
    await authService.reset();
  }

  public isAvailable(): boolean {
    return this.isBackendAvailable && this.isProjectIdVerified;
  }

  // User tracking methods

  /**
   * Set user data for tracking
   * This is a convenience method that delegates to authService
   */
  public setUserData(userData: EndUserData): void {
    authService.setUserData(userData);
  }

  /**
   * Get current user data
   * This is a convenience method that delegates to authService
   */
  public getUserData(): EndUserData | null {
    return authService.getUserData();
  }

  /**
   * Clear user data
   * This is a convenience method that delegates to authService
   */
  public clearUserData(): void {
    authService.clearUserData();
    // Clear the cache when user data is cleared
    this.userDataCache = null;
  }

  /**
   * Clear the user data cache to force a fresh fetch on next request
   */
  public clearUserDataCache(): void {
    this.userDataCache = null;
  }

  /**
   * Track a user event
   */
  public async trackEvent(event: UserEvent): Promise<void> {
    try {
      // Verify user ID exists before making user-related API call
      const userData = this.getUserData();
      if (!userData || !userData.userId) {
        logger.warn('Cannot track event: End-user ID is required');
        return;
      }

      return await this.withRetry(async () => {
        await this.ensureApiInstance();
        await this.api!.post('/end-users/sdk/events', event);
      });
    } catch (error: unknown) {
      logger.error('Failed to track user event:', error);
      // Re-throw specific error types that callers might want to handle
      if (error instanceof ProjectIdError || error instanceof ServerConnectionError) {
        throw error;
      }
      // For other errors, wrap with a generic message but preserve the original
      throw new Error(
        `Failed to track user event: ${error instanceof Error ? error.message : 'Unknown error'}`,
        {
          cause: error,
        },
      );
    }
  }

  /**
   * Register a flow completion for the user
   */
  public async registerFlowCompletion(completion: FlowCompletion): Promise<void> {
    try {
      // Verify user ID exists before making user-related API call
      const userData = this.getUserData();
      if (!userData || !userData.userId) {
        logger.warn('Cannot register flow completion: End-user ID is required');
        return;
      }

      return await this.withRetry(async () => {
        await this.ensureApiInstance();
        await this.api!.post('/end-users/sdk/flows/complete', completion);
      });
    } catch (error: unknown) {
      logger.error('Failed to register flow completion:', error);
      // Re-throw specific error types that callers might want to handle
      if (error instanceof ProjectIdError || error instanceof ServerConnectionError) {
        throw error;
      }
      // For other errors, wrap with a generic message but preserve the original
      throw new Error(
        `Failed to register flow completion: ${error instanceof Error ? error.message : 'Unknown error'}`,
        {
          cause: error,
        },
      );
    }
  }

  /**
   * Get the user's data and progress information from the server
   * @returns User data including onboarding progress and completion status
   */
  public async fetchUserDataFromServer(): Promise<{
    userId: string;
    name: string | null;
    avatarUrl: string | null;
    completedFlows: {
      flowIds: string[];
      isSubflow: boolean;
      completionTimestamps: Record<string, string>;
    };
    createdAt: Date;
  }> {
    // Verify user ID exists before making user-related API call
    const storedUserData = this.getUserData();
    if (!storedUserData || !storedUserData.userId) {
      logger.warn('Cannot fetch user data: End-user ID is required');
      throw new Error('End-user ID is required');
    }

    const now = Date.now();

    // If we have a cached result that's still valid, use it
    if (this.userDataCache && now - this.userDataCache.timestamp < this.USER_DATA_CACHE_DURATION) {
      logger.debug(
        'Using cached user data (age: ' +
          Math.round((now - this.userDataCache.timestamp) / 1000) +
          's)',
      );
      logger.debug('Cached completed flows:', this.userDataCache.data.completedFlows);
      return this.userDataCache.data;
    }

    // If there's already a request in progress, wait for it
    if (this.userDataPromise) {
      logger.debug('User data request already in progress, reusing promise');
      return this.userDataPromise;
    }

    // Start new request
    this.userDataPromise = this.withRetry(async () => {
      await this.ensureApiInstance();
      const response = await this.api!.get('/end-users/sdk/user-data');
      logger.debug('Fresh user data fetched from server:', {
        completedFlows: response.data.completedFlows,
        isSubflow: response.data.isSubflow,
        userId: response.data.userId,
      });
      return response.data;
    });

    try {
      const data = await this.userDataPromise;

      // Cache the successful result
      this.userDataCache = {
        data,
        timestamp: now,
      };

      return data;
    } finally {
      // Clear the promise
      this.userDataPromise = null;
    }
  }

  /**
   * Check if the API service can make requests to the backend
   * This first checks the cached availability status, and if needed, attempts to verify the connection
   */
  public async canConnectToBackend(): Promise<boolean> {
    // If we already know the backend is unavailable, don't check again
    if (!this.isBackendAvailable) {
      return false;
    }

    // If we already have a verified API key, assume we can connect
    if (this.isProjectIdVerified && this.api) {
      return true;
    }

    // Otherwise try to establish a connection
    try {
      await this.ensureApiInstance();
      return this.isBackendAvailable;
    } catch (error) {
      logger.debug('Failed to connect to backend during availability check:', error);
      return false;
    }
  }
}

export const apiService = ApiService.getInstance();
