import { apiService } from '../services/api';
import { storage } from './storage';
import type { ElementMapping, StorageMessage } from '../types';
import { guideSocketClient } from '../services/websocket/GuideSocketClient';
import { getWindow } from '..';

import { logger } from './logger';
class ConversationManager {
  private static instance: ConversationManager;

  private constructor() {}

  public static getInstance(): ConversationManager {
    if (!ConversationManager.instance) {
      ConversationManager.instance = new ConversationManager();
    }
    return ConversationManager.instance;
  }

  public async createConversation(): Promise<string> {
    try {
      // Create conversation in backend first
      const backendConversation = await apiService.createConversation();

      // Create in local storage using the backend ID, but don't set a title
      // The title will be fetched through polling
      storage.createConversation('', backendConversation.id);

      // // Track conversation creation event with user data if available
      // const userData = apiService.getUserData();
      // if (userData) {
      //   apiService.trackEvent({
      //     eventType: 'CONVERSATION',
      //     eventName: 'CONVERSATION_CREATED',
      //     eventData: {
      //       conversationId: backendConversation.id,
      //     },
      //     context: {
      //       userId: userData.userId,
      //     },
      //     timestamp: new Date().toISOString(),
      //   });
      // }

      // Return the backend conversation ID
      return backendConversation.id;
    } catch (error) {
      logger.error('Failed to create backend conversation:', error);
      throw error; // Let the widget handle the error
    }
  }

  public async handleAssistantResponse(
    message: string,
    conversationId: string,
    uiElements: ElementMapping[],
    onChunk: (text: string) => void,
  ): Promise<void> {
    // Store the user's message first
    storage.addMessage(conversationId, {
      role: 'user',
      content: message,
    });

    // Track message sent event with user data if available
    // const userData = apiService.getUserData();
    // if (userData) {
    //   apiService.trackEvent({
    //     eventType: 'CONVERSATION',
    //     eventName: 'MESSAGE_SENT',
    //     eventData: {
    //       conversationId,
    //       messageLength: message.length,
    //     },
    //     context: {
    //       userId: userData.userId,
    //     },
    //     timestamp: new Date().toISOString(),
    //   });
    // }

    let assistantMessage = '';
    let isGuideResponse = false;
    let currentEventType: string | null = null;
    let responseBuffer = '';
    let initialGuideMessage: string | null = null; // Track initial guide message

    // Helper function to add text with proper spacing
    const appendWithSpacing = (current: string, newText: string): string => {
      if (
        !current.endsWith(' ') &&
        !newText.startsWith(' ') &&
        ((/[a-zA-Z]$/.test(current) && /^[0-9]/.test(newText)) ||
          (current.endsWith(':') && !newText.startsWith(' ')))
      ) {
        return current + ' ' + newText;
      }
      return current + newText;
    };

    return new Promise((resolve, reject) => {
      apiService.getAssistantResponse(
        message,
        conversationId,
        uiElements.slice(0, 50),
        (chunk: string) => {
          // Clean any data: prefix first
          const cleanChunk = chunk.replace(/^data:\s*/, '');

          // Skip empty chunks
          if (!cleanChunk.trim()) {
            return;
          }

          // Handle event type declarations
          if (cleanChunk.startsWith('event: ')) {
            // Complete previous event if exists
            if (currentEventType === 'message' && responseBuffer) {
              if (!isGuideResponse) {
                assistantMessage = appendWithSpacing(assistantMessage, responseBuffer);
                onChunk(responseBuffer);
              }
              responseBuffer = '';
            }

            currentEventType = cleanChunk.replace('event: ', '');
            return;
          }

          // Handle response type event
          if (currentEventType === 'responseType') {
            try {
              const responseTypeData = JSON.parse(cleanChunk);
              if (responseTypeData.type === 'guide') {
                isGuideResponse = true;
              }
            } catch (e) {
              logger.error('Failed to parse response type:', e);
            }
            return;
          }

          // Handle guide initialization
          if (currentEventType === 'guideInit') {
            try {
              const initData = JSON.parse(cleanChunk);
              logger.debug('Guide Init Data:', initData);

              // Store the initial message for later use
              initialGuideMessage = initData.initialResponse;

              // Store the guide initialization message immediately with proper flags
              const guideMessage: StorageMessage = {
                role: 'assistant',
                content: initialGuideMessage || 'Initializing guide...',
                showGuideButton: true,
                relatedGuideId: initData.conversationId,
                timestamp: Date.now(),
                metadata: {
                  projectId: initData.metadata?.projectId,
                  knowledgeBaseId: initData.metadata?.knowledgeBaseId,
                  page: getWindow()?.location.pathname,
                },
                showFeedback: false,
              };
              storage.addMessage(conversationId, guideMessage);
              logger.debug('Stored guide init message:', guideMessage);

              // Send the initial message with guide button
              const initChunk = JSON.stringify({
                type: 'message',
                content: initialGuideMessage,
                showGuideButton: true,
                isGuideLoading: true,
              });
              logger.debug('Sending init chunk to widget:', initChunk);
              onChunk(initChunk);

              // Start the guide via WebSocket
              guideSocketClient.startGuide({
                message,
                conversationId: initData.conversationId,
                uiElements: uiElements.slice(0, 50),
              });
            } catch (e) {
              logger.error('Failed to parse guide init data:', e);
            }
            return;
          }

          // Handle message events
          if (currentEventType === 'message') {
            if (isGuideResponse) {
              // For guide responses, we need to maintain the guide state
              onChunk(
                JSON.stringify({
                  type: 'message',
                  content: cleanChunk,
                  showGuideButton: true,
                  isGuideLoading: false,
                }),
              );
            } else {
              // For regular messages, just append to the buffer
              responseBuffer += cleanChunk;
            }
            return;
          }

          // Handle guide step
          if (currentEventType === 'guideStep') {
            try {
              const stepData = JSON.parse(cleanChunk);
              const step = stepData.step;
              const guideId = stepData.guideId;
              logger.debug('Guide Step Data:', stepData);

              // Send guide data while maintaining the initial message
              const stepChunk = JSON.stringify({
                type: 'message',
                content: initialGuideMessage || 'Starting guide...',
                showGuideButton: true,
                isGuideLoading: false,
                guide: {
                  id: guideId,
                  name: step.metadata.guideName,
                  steps: [
                    {
                      id: step.id,
                      position: step.position,
                      instructions: step.instructions,
                      page: step.metadata.page,
                      action: step.action,
                    },
                  ],
                },
              });
              logger.debug('Sending step chunk to widget:', stepChunk);
              onChunk(stepChunk);

              // Don't store step data in chat history since it's shown in the step card
            } catch (e) {
              logger.error('Failed to parse guide step data:', e);
            }
            return;
          }

          // Handle guide data
          if (isGuideResponse && cleanChunk.startsWith('{')) {
            try {
              const guideData = JSON.parse(cleanChunk);
              if (guideData.name && guideData.steps) {
                onChunk(cleanChunk); // Pass the entire guide data
              }
            } catch (e) {
              logger.error('Failed to parse guide data:', e);
            }
            return;
          }

          // Handle done event
          if (currentEventType === 'done' || cleanChunk.includes('[DONE]')) {
            // Send any remaining buffered response
            if (responseBuffer && !isGuideResponse) {
              assistantMessage = appendWithSpacing(assistantMessage, responseBuffer);
              onChunk(responseBuffer);
            }
            return;
          }
        },
        (error: Error) => {
          logger.error('Error getting assistant response:', error);
          reject(error);
        },
        () => {
          // Send any final buffered response
          if (responseBuffer && !isGuideResponse) {
            assistantMessage = appendWithSpacing(assistantMessage, responseBuffer);
            onChunk(responseBuffer);
          }

          if (!isGuideResponse) {
            // Only store message if it wasn't a guide (which would be handled by WebSocket)
            storage.addMessage(conversationId, {
              role: 'assistant',
              content: assistantMessage.trim(),
              showFeedback: false,
            });
          }
          resolve();
        },
      );
    });
  }
}

export const conversationManager = ConversationManager.getInstance();
