import React from 'react';
import type { ReactNode } from 'react';
import ReactMarkdown from 'react-markdown';
import type { Components } from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import style from 'react-syntax-highlighter/dist/esm/styles/hljs/docco';
import styles from './MarkdownAnimateText.module.css';

interface TokenizedTextProps {
  input: string | ReactNode;
  sep: 'word' | 'char';
  animation: string;
  animationDuration: string;
  animationTimingFunction: string;
  animationIterationCount: number;
}

type MarkdownComponentProps = {
  children?: ReactNode;
  className?: string;
};

const TokenizedText: React.FC<TokenizedTextProps> = ({
  input,
  sep,
  animationDuration,
  animationTimingFunction,
}) => {
  const tokens = React.useMemo(() => {
    if (React.isValidElement(input)) return [input];
    if (typeof input !== 'string') return null;

    const splitRegex = sep === 'word' ? /(\s+)/ : /(.)/;
    return input.split(splitRegex).filter(token => token.length > 0);
  }, [input, sep]);

  return (
    <>
      {tokens?.map((token, index) => (
        <span
          key={index}
          className={styles.animatedToken}
          style={{
            animationDuration,
            animationTimingFunction,
          }}>
          {token}
        </span>
      ))}
    </>
  );
};

interface MarkdownAnimateTextProps {
  content: string;
  sep?: 'word' | 'char';
  animation?: string;
  animationDuration?: string;
  animationTimingFunction?: string;
}

export const MarkdownAnimateText: React.FC<MarkdownAnimateTextProps> = ({
  content,
  sep = 'word',
  animation = 'fadeIn',
  animationDuration = '0.5s',
  animationTimingFunction = 'ease-out',
}) => {
  const animateText = React.useCallback(
    (text: ReactNode): ReactNode => {
      const processText = (input: string | ReactNode | ReactNode[]): ReactNode => {
        if (Array.isArray(input)) {
          return input.map((element, index) => (
            <React.Fragment key={index}>{processText(element)}</React.Fragment>
          ));
        } else if (typeof input === 'string') {
          if (!animation) return input;
          return (
            <TokenizedText
              input={input}
              sep={sep}
              animation={animation}
              animationDuration={animationDuration}
              animationTimingFunction={animationTimingFunction}
              animationIterationCount={1}
            />
          );
        } else if (React.isValidElement(input)) {
          return input;
        } else {
          return null;
        }
      };
      return processText(Array.isArray(text) ? text : [text]);
    },
    [animation, animationDuration, animationTimingFunction, sep],
  );

  const components: Partial<Components> = React.useMemo(
    () => ({
      p: ({ children }: MarkdownComponentProps) => (
        <p className={styles.paragraph}>{animateText(children)}</p>
      ),
      ul: ({ children }: MarkdownComponentProps) => <ul className={styles.list}>{children}</ul>,
      ol: ({ children }: MarkdownComponentProps) => <ol className={styles.list}>{children}</ol>,
      li: ({ children }: MarkdownComponentProps) => (
        <li className={styles.listItem}>{animateText(children)}</li>
      ),
      strong: ({ children }: MarkdownComponentProps) => (
        <strong className={styles.bold}>{animateText(children)}</strong>
      ),
      code: ({ className, children }: MarkdownComponentProps) => {
        if (!className) {
          return <code className={styles.inlineCode}>{animateText(children)}</code>;
        }
        const language = className.replace('language-', '');
        return (
          <div className={styles.codeBlock}>
            <SyntaxHighlighter style={style} language={language}>
              {String(children)}
            </SyntaxHighlighter>
          </div>
        );
      },
      pre: ({ children }: MarkdownComponentProps) => (
        <div className={styles.preBlock}>{children}</div>
      ),
    }),
    [animateText],
  );

  return (
    <div className={styles.markdownContainer}>
      <ReactMarkdown components={components} remarkPlugins={[remarkGfm]}>
        {content}
      </ReactMarkdown>
    </div>
  );
};
