import * as React from 'react';
import type { StorageConversation } from '../../../types';
import { SessionItem } from './SessionItem';
import styles from './SessionList.module.css';

interface SessionListProps {
  groupTitle: string;
  sessions: StorageConversation[];
  editingSessionId: string | null;
  editingSessionTitle: string;
  hoveredSessionId: string | null;
  onSessionClick: (sessionId: string) => void;
  onEditClick: (sessionId: string, title: string) => void;
  onDeleteClick: (sessionId: string) => void;
  onTitleChange: (value: string) => void;
  onTitleUpdate: (sessionId: string) => void;
  onMouseEnter: (sessionId: string) => void;
  onMouseLeave: () => void;
}

export const SessionList: React.FC<SessionListProps> = ({
  groupTitle,
  sessions,
  editingSessionId,
  editingSessionTitle,
  hoveredSessionId,
  onSessionClick,
  onEditClick,
  onDeleteClick,
  onTitleChange,
  onTitleUpdate,
  onMouseEnter,
  onMouseLeave,
}) => {
  return (
    <div className={styles.container}>
      <p className={styles.title}>{groupTitle}</p>
      <ul>
        {sessions.map(session => (
          <li key={session.id}>
            <SessionItem
              session={session}
              isEditing={editingSessionId === session.id}
              editTitle={editingSessionTitle}
              isHovered={hoveredSessionId === session.id}
              onMouseEnter={() => onMouseEnter(session.id)}
              onMouseLeave={onMouseLeave}
              onClick={() => onSessionClick(session.id)}
              onEditClick={() => onEditClick(session.id, session.title || '')}
              onDeleteClick={() => onDeleteClick(session.id)}
              onTitleChange={onTitleChange}
              onTitleBlur={() => onTitleUpdate(session.id)}
              onTitleKeyPress={e => {
                if (e.key === 'Enter') {
                  onTitleUpdate(session.id);
                }
              }}
            />
          </li>
        ))}
      </ul>
    </div>
  );
};
