import type { Action } from '../types';

interface ValidationOptions {
  debounceTime?: number;
  shouldPreventDefault?: boolean;
}

interface ValidationResult {
  shouldComplete: boolean;
  message?: string;
}

type ValidationCallback = (result: ValidationResult) => void;

export class ActionValidator {
  private static instance: ActionValidator;
  private debounceTimers: Map<string, NodeJS.Timeout>;
  private defaultDebounceTime: number;

  private constructor() {
    this.debounceTimers = new Map();
    this.defaultDebounceTime = 1000; // 1 second default
  }

  public static getInstance(): ActionValidator {
    if (!ActionValidator.instance) {
      ActionValidator.instance = new ActionValidator();
    }
    return ActionValidator.instance;
  }

  private clearDebounceTimer(elementId: string) {
    const timer = this.debounceTimers.get(elementId);
    if (timer) {
      clearTimeout(timer);
      this.debounceTimers.delete(elementId);
    }
  }

  private setDebounceTimer(elementId: string, callback: () => void, debounceTime: number) {
    this.clearDebounceTimer(elementId);
    const timer = setTimeout(callback, debounceTime);
    this.debounceTimers.set(elementId, timer);
  }

  public setupValidation(
    element: HTMLElement,
    action: Action,
    onValidation: ValidationCallback,
    options: ValidationOptions = {},
  ): () => void {
    const elementId = element.id || Math.random().toString(36).substring(7);
    const debounceTime = options.debounceTime || this.defaultDebounceTime;

    const handleInputValidation = (event: Event) => {
      const inputElement = event.target as HTMLInputElement;

      this.setDebounceTimer(
        elementId,
        () => {
          let shouldComplete = inputElement.value.length > 0;
          if (action.validation) {
            shouldComplete = action.validation(inputElement);
          }
          onValidation({ shouldComplete });
        },
        debounceTime,
      );
    };

    const handleInteraction = (event: Event) => {
      if (options.shouldPreventDefault) {
        event.preventDefault();
      }

      let shouldComplete = false;
      let selectElement: HTMLSelectElement;

      switch (action.type) {
        case 'click':
          shouldComplete = true;
          break;
        case 'input':
          return; // Handled by debounced handler
        case 'select':
          selectElement = event.target as HTMLSelectElement;
          shouldComplete = selectElement.value !== '';
          break;
        case 'submit':
          shouldComplete = true;
          break;
        case 'navigate':
          shouldComplete = true;
          // Special handling for navigation
          if (action.path) {
            onValidation({ shouldComplete: true });
            return;
          }
          break;
      }

      if (action.validation) {
        shouldComplete = action.validation(event.target as HTMLElement);
      }

      onValidation({ shouldComplete });
    };

    // Attach appropriate event listeners based on action type
    switch (action.type) {
      case 'input':
        element.addEventListener('input', handleInputValidation);
        break;
      case 'select':
        element.addEventListener('change', handleInteraction);
        break;
      case 'navigate':
      case 'click':
      case 'submit':
        element.addEventListener('click', handleInteraction);
        break;
    }

    // Return cleanup function
    return () => {
      element.removeEventListener('input', handleInputValidation);
      element.removeEventListener('change', handleInteraction);
      element.removeEventListener('click', handleInteraction);
      this.clearDebounceTimer(elementId);
    };
  }

  public cleanup() {
    this.debounceTimers.forEach(timer => clearTimeout(timer));
    this.debounceTimers.clear();
  }
}

export const actionValidator = ActionValidator.getInstance();
