import nodeForge from 'node-forge';
const { pki, md: mdHash, util } = nodeForge;
import type { pki as PkiTypes } from 'node-forge';
import { ProjectIdError, ERROR_MESSAGES } from '../errors';

import { logger } from '../utils/logger';
class WebSocketAuthService {
  private static instance: WebSocketAuthService;
  private storage: Storage | null = null;
  private privateKey: PkiTypes.rsa.PrivateKey | null = null;
  private publicKeyRaw: string | null = null;
  private projectId: string | null = null;
  private apiUrl: string = 'https://api.pointer.so';
  private isInitialized = false;
  private sessionId: string | null = null;

  private constructor() {}

  public static getInstance(): WebSocketAuthService {
    if (!WebSocketAuthService.instance) {
      WebSocketAuthService.instance = new WebSocketAuthService();
    }
    return WebSocketAuthService.instance;
  }

  public async initialize(projectId: string, storage: Storage, apiUrl?: string): Promise<void> {
    this.projectId = projectId;
    this.storage = storage;
    if (apiUrl) {
      this.apiUrl = apiUrl;
    }

    await this.loadOrGenerateKeyPair();
    this.isInitialized = true;
  }

  public getProjectId(): string | null {
    return this.projectId;
  }

  public getApiUrl(): string {
    return this.apiUrl;
  }

  public isReady(): boolean {
    return this.isInitialized && !!this.privateKey && !!this.publicKeyRaw;
  }

  private async loadOrGenerateKeyPair(): Promise<void> {
    if (!this.storage) {
      throw new Error('Storage not initialized');
    }

    // Try to load from storage first - use a different key than the API service
    const storedKeys = this.storage.getItem('pointer_websocket_keypair');
    if (storedKeys) {
      try {
        const { privateKey, publicKey } = JSON.parse(storedKeys);
        this.privateKey = pki.privateKeyFromPem(privateKey);
        this.publicKeyRaw = publicKey;
        logger.debug('WebSocket Auth Service: Loaded existing keypair');
        return;
      } catch (error) {
        logger.debug('WebSocket Auth Service: Failed to load stored keys, generating new ones');
      }
    }

    // Generate new keys if not found in storage
    logger.debug('WebSocket Auth Service: Generating new keypair');
    await new Promise<void>(resolve => {
      setTimeout(() => {
        const keypair = pki.rsa.generateKeyPair({
          bits: 2048,
        });
        this.privateKey = keypair.privateKey;

        // Store raw key data without PEM formatting
        const pem = pki.publicKeyToPem(keypair.publicKey);
        this.publicKeyRaw = pem
          .replace(/-----(BEGIN|END) PUBLIC KEY-----/g, '')
          .replace(/[\n\r]/g, '')
          .trim();

        // Store in storage with a distinct key
        try {
          this.storage!.setItem(
            'pointer_websocket_keypair',
            JSON.stringify({
              privateKey: pki.privateKeyToPem(this.privateKey),
              publicKey: this.publicKeyRaw,
            }),
          );
          logger.debug('WebSocket Auth Service: Stored new keypair');
        } catch (error) {
          logger.debug('WebSocket Auth Service: Failed to store keypair');
        }
        resolve();
      }, 0);
    });
  }

  private async ensureKeys(): Promise<void> {
    if (!this.isInitialized) {
      throw new Error('WebSocket auth service not initialized');
    }
    if (!this.privateKey || !this.publicKeyRaw) {
      await this.loadOrGenerateKeyPair();
    }
  }

  public async getPublicKeyPem(): Promise<string> {
    await this.ensureKeys();
    if (!this.publicKeyRaw) {
      throw new Error('Public key not generated');
    }
    return `-----BEGIN PUBLIC KEY-----\n${this.publicKeyRaw}\n-----END PUBLIC KEY-----`;
  }

  public async getEncodedPublicKey(): Promise<string> {
    return btoa(await this.getPublicKeyPem());
  }

  public async createSignature(
    timestamp: number,
    body: Record<string, unknown> = {},
  ): Promise<string> {
    await this.ensureKeys();
    if (!this.privateKey) {
      throw new Error('Cannot create signature without private key');
    }

    // Include session ID in signature if we have one
    const message = this.sessionId
      ? `${timestamp}:${this.sessionId}:${JSON.stringify(body)}`
      : `${timestamp}::${JSON.stringify(body)}`;

    const md = mdHash.sha256.create();
    md.update(message, 'utf8');
    const signature = this.privateKey.sign(md, 'RSASSA-PKCS1-V1_5');
    return util.encode64(signature);
  }

  public async getAuthData(body: Record<string, unknown> = {}): Promise<Record<string, string>> {
    if (!this.projectId) {
      throw new ProjectIdError(ERROR_MESSAGES.INVALID_PROJECT_ID);
    }

    if (!this.isReady()) {
      throw new Error('WebSocket auth service not ready');
    }

    const timestamp = Date.now();
    const [encodedPublicKey, signature] = await Promise.all([
      this.getEncodedPublicKey(),
      this.createSignature(timestamp, body),
    ]);

    // Only include session ID in headers if we have one
    const headers: Record<string, string> = {
      'X-PROJECT-ID': this.projectId,
      'X-CLIENT-PUBLIC-KEY': encodedPublicKey,
      'X-REQUEST-TIMESTAMP': timestamp.toString(),
      'X-REQUEST-SIGNATURE': signature,
    };

    if (this.sessionId) {
      headers['X-SESSION-ID'] = this.sessionId;
    }

    return headers;
  }

  public async reset(): Promise<void> {
    this.privateKey = null;
    this.publicKeyRaw = null;
    this.isInitialized = false;
    if (this.storage) {
      this.storage.removeItem('pointer_websocket_keypair');
      await this.loadOrGenerateKeyPair();
      this.isInitialized = true;
    }
  }

  public setSessionId(sessionId: string | null): void {
    this.sessionId = sessionId;
  }

  public getSessionId(): string | null {
    return this.sessionId;
  }
}

export const websocketAuthService = WebSocketAuthService.getInstance();
