import { useState, useEffect, useCallback } from 'react';
import type { RuntimeGuide, DisplayMessage } from '../../../types';
import { MessageItem } from './MessageItem';
import { Suggestions } from '../suggestions/Suggestions';
import styles from './ChatMessages.module.css';

interface ChatMessagesProps {
  messages: DisplayMessage[];
  userAvatar: string;
  assistantLogo: string;
  onGuideStart: (guide: RuntimeGuide) => void;
  onFeedback: (index: number, feedback: 'yes' | 'no') => void;
  containerRef: React.RefObject<HTMLDivElement>;
  showSuggestions?: boolean;
  onSuggestionClick?: (text: string) => void;
}

export const ChatMessages: React.FC<ChatMessagesProps> = ({
  messages,
  userAvatar,
  assistantLogo,
  onGuideStart,
  onFeedback,
  containerRef,
  showSuggestions,
  onSuggestionClick,
}) => {
  const [isSuggestionsHiding, setIsSuggestionsHiding] = useState(false);
  const [shouldShowSuggestions, setShouldShowSuggestions] = useState(showSuggestions);
  const [isAnimating, setIsAnimating] = useState(false);
  const [userHasScrolled, setUserHasScrolled] = useState(false);

  // Check if user is near bottom
  const isNearBottom = useCallback(() => {
    if (!containerRef.current) return true;
    const { scrollTop, scrollHeight, clientHeight } = containerRef.current;
    return scrollHeight - scrollTop - clientHeight < 50;
  }, [containerRef]);

  // Scroll helper function
  const scrollToBottom = useCallback(
    (smooth = true) => {
      if (!containerRef.current) return;

      const container = containerRef.current;

      // Only scroll if we haven't detected manual user scrolling
      // or if we're near the bottom already
      if (!userHasScrolled || isNearBottom()) {
        container.style.scrollBehavior = smooth ? 'smooth' : 'auto';
        const scrollHeight = container.scrollHeight;
        container.scrollTop = scrollHeight;

        // Reset scroll behavior
        if (smooth) {
          setTimeout(() => {
            if (container) {
              container.style.scrollBehavior = 'auto';
            }
          }, 300);
        }
      }
    },
    [containerRef, userHasScrolled, isNearBottom],
  );

  // Handle scroll events to detect manual scrolling
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleScroll = () => {
      // If user scrolls up, mark as manually scrolled
      if (!isNearBottom()) {
        setUserHasScrolled(true);
      } else {
        // Reset the flag if they scroll back to bottom
        setUserHasScrolled(false);
      }
    };

    container.addEventListener('scroll', handleScroll);
    return () => container.removeEventListener('scroll', handleScroll);
  }, [containerRef, isNearBottom]);

  useEffect(() => {
    if (showSuggestions === false && shouldShowSuggestions) {
      setIsSuggestionsHiding(true);
      const timer = setTimeout(() => {
        setShouldShowSuggestions(false);
      }, 300); // Match the duration in the CSS transition
      return () => clearTimeout(timer);
    } else if (showSuggestions) {
      setIsSuggestionsHiding(false);
      setShouldShowSuggestions(true);
    }
  }, [showSuggestions, shouldShowSuggestions]);

  // Handle animation state when messages change
  useEffect(() => {
    if (messages.length > 0) {
      setIsAnimating(true);
      const timer = setTimeout(() => {
        setIsAnimating(false);
      }, 500); // Match the animation duration
      return () => clearTimeout(timer);
    }
  }, [messages.length]);

  // Handle automatic scrolling for new messages
  useEffect(() => {
    if (messages.length > 0) {
      const lastMessage = messages[messages.length - 1];
      const isNewMessage =
        lastMessage?.isStreaming ||
        (lastMessage?.assistant && lastMessage.assistant !== '') ||
        lastMessage?.user;

      if (isNewMessage) {
        // Initial scroll without smooth behavior
        scrollToBottom(false);

        // Secondary scroll with smooth behavior after a small delay
        setTimeout(() => scrollToBottom(true), 50);
      }
    }
  }, [messages, scrollToBottom]);

  return (
    <div
      className={`${styles.container} ${isAnimating ? styles.animating : ''} ${
        !shouldShowSuggestions ? styles.fadeBottom : ''
      }`}
      ref={containerRef}>
      <div className={styles.content}>
        {messages.length === 0 && shouldShowSuggestions ? (
          <Suggestions onItemClick={onSuggestionClick!} isHiding={isSuggestionsHiding} />
        ) : (
          <>
            {messages.map((message, index) => (
              <MessageItem
                key={index}
                message={message}
                userAvatar={userAvatar}
                assistantLogo={assistantLogo}
                onGuideStart={onGuideStart}
                onFeedback={feedback => onFeedback(index, feedback)}
              />
            ))}
          </>
        )}
      </div>
    </div>
  );
};
