'use client';

import * as React from 'react';
import { updatePointerPosition } from '../utils/positions';
import { storage } from '../utils/storage';
import { PageMapper } from '../runtime/pageMapper';
import { apiService } from '../services/api';
import { Step as StepComponent } from '../components/step';
import { Widget } from '../components/widget';
import { ScrollIndicator } from '../components/scroll';
import { ThemeProvider } from './ThemeContext';
import { createPortal } from 'react-dom';
import { projectIdVerificationCache } from '../utils/apiVerification';
import { guideSocketClient } from '../services/websocket/GuideSocketClient';
import Confetti from '../components/confetti';
import type {
  DisplayMessage,
  ElementMapping,
  PointerProviderProps,
  SimpleGuide,
  Step,
  // StorageMessage,
  PointerContextType as IPointerContextType,
  CustomizationConfig,
} from '../types';
import { actionValidator } from '../utils/actionValidation';
import { getDocument, getWindow } from '..';
import { logger } from '../utils/logger';
import { getStorage } from '../index';
export const PointerContext = React.createContext<IPointerContextType | null>(null);

type PointerContextType = IPointerContextType;

interface InitializationMetrics {
  startTime: number;
  storageTime: number;
  apiServiceTime: number;
  pageMapperTime: number;
  totalTime: number;
}

export const PointerProvider = ({
  children,
  projectId,
  apiUrl,
  disabled = false,
  // User data
  userData,
  triggerId,
  // Theme props
  primaryColor,
  secondaryColor,
  tertiaryColor,
  accentColor,
  interactiveColor,
  backgroundColor,
  borderColor,
  borderRadius,
  cursorColor,
  // Branding props
  logomark,
  triggerIcon,
  triggerBackground,
  triggerIconColor,
  triggerBorder,
  // Content props
  welcomeMessage,
  welcomeSubheading,
  inputPlaceholder,
  // Link button props
  link1Text,
  link1Icon,
  link1Url,
  link2Text,
  link2Icon,
  link2Url,
  link3Text,
  link3Icon,
  link3Url,
  link4Text,
  link4Icon,
  link4Url,
}: PointerProviderProps) => {
  const [currentStep, setCurrentStep] = React.useState<number>(-1);
  const [showPointer, setShowPointer] = React.useState<boolean>(false);
  const [steps, setSteps] = React.useState<Step[]>([]);
  const [activeStepId, setActiveStepId] = React.useState<string | null>(null);
  const [isLastStep, setIsLastStep] = React.useState<boolean>(false);
  const [activeGuide, setActiveGuide] = React.useState<SimpleGuide | null>(null);
  const [isChatOpen, setIsChatOpen] = React.useState<boolean>(false);
  const [guides, setGuides] = React.useState<SimpleGuide[]>([]);
  const [defaultResponse, setDefaultResponse] = React.useState<string>(
    'There was an error responding to your message. Please contact support.',
  );
  const [triggerPhrases, setTriggerPhrases] = React.useState<Record<string, string>>({});
  const [isGuideActive, setIsGuideActive] = React.useState<boolean>(false);
  const [chatHistory, setChatHistory] = React.useState<DisplayMessage[]>([]);
  const [completedActions, setCompletedActions] = React.useState<Set<string>>(new Set());
  const [pointerPosition, setPointerPosition] = React.useState({ top: 0, left: 0 });
  const [targetPosition, setTargetPosition] = React.useState({
    top: 0,
    left: 0,
    width: 0,
    height: 0,
  });
  const [pageMappings, setPageMappings] = React.useState<ElementMapping[]>([]);
  const [isInitialized, setIsInitialized] = React.useState<boolean>(false);
  const [isBackendAvailable, setIsBackendAvailable] = React.useState<boolean>(true);
  const [error, _setError] = React.useState<string | null>(null);
  const pageMapperRef = React.useRef<PageMapper | null>(null);
  const [scrollDirection, setScrollDirection] = React.useState<'up' | 'down' | null>(null);
  const [isStepGenerating, setIsStepGenerating] = React.useState<boolean>(false);
  const [_showCursorClick, setShowCursorClick] = React.useState<boolean>(false);
  const initializationPromise = React.useRef<Promise<void> | null>(null);

  // Single source of truth for position updates
  const positionCleanupRef = React.useRef<(() => void) | null>(null);

  // Completion popup state
  const [showCompletionPopup, setShowCompletionPopup] = React.useState(false);
  const [isCompletionVisible, setIsCompletionVisible] = React.useState(false);

  // Convert props to customization object
  const customization: CustomizationConfig = React.useMemo(
    () => ({
      theme: {
        ...(primaryColor && { primaryColor }),
        ...(secondaryColor && { secondaryColor }),
        ...(tertiaryColor && { tertiaryColor }),
        ...(accentColor && { accentColor }),
        ...(interactiveColor && { interactiveColor }),
        ...(backgroundColor && { backgroundColor }),
        ...(borderColor && { borderColor }),
        ...(borderRadius && { borderRadius }),
        ...(cursorColor && { cursorColor }),
      },
      branding: {
        ...(logomark && { logomark }),
        ...(triggerIcon && { triggerIcon }),
        ...(triggerBackground && { triggerBackground }),
        ...(triggerIconColor && { triggerIconColor }),
        ...(triggerBorder && { triggerBorder }),
      },
      content: {
        ...(welcomeMessage && { welcomeMessage }),
        ...(welcomeSubheading && { welcomeSubheading }),
        ...(inputPlaceholder && { inputPlaceholder }),
        ...(link1Text && { link1Text }),
        ...(link1Icon && { link1Icon }),
        ...(link1Url && { link1Url }),
        ...(link2Text && { link2Text }),
        ...(link2Icon && { link2Icon }),
        ...(link2Url && { link2Url }),
        ...(link3Text && { link3Text }),
        ...(link3Icon && { link3Icon }),
        ...(link3Url && { link3Url }),
        ...(link4Text && { link4Text }),
        ...(link4Icon && { link4Icon }),
        ...(link4Url && { link4Url }),
      },
    }),
    [
      primaryColor,
      secondaryColor,
      tertiaryColor,
      accentColor,
      interactiveColor,
      backgroundColor,
      borderColor,
      borderRadius,
      cursorColor,
      logomark,
      triggerIcon,
      triggerBackground,
      triggerIconColor,
      triggerBorder,
      welcomeMessage,
      welcomeSubheading,
      inputPlaceholder,
      link1Text,
      link1Icon,
      link1Url,
      link2Text,
      link2Icon,
      link2Url,
      link3Text,
      link3Icon,
      link3Url,
      link4Text,
      link4Icon,
      link4Url,
    ],
  );

  // Function to check element visibility
  const checkElementVisibility = React.useCallback(() => {
    const win = getWindow();
    const doc = getDocument();
    if (!doc || !win) return;

    if (steps[currentStep]) {
      try {
        const element = doc.querySelector(steps[currentStep].position);
        if (element) {
          const rect = element.getBoundingClientRect();
          const viewportHeight = win.innerHeight;

          // Larger buffer for top elements to prevent aggressive up-scroll indicators
          const topBuffer = rect.top < 100 ? 0 : 100; // No buffer for nav elements
          const bottomBuffer = 100;

          // Calculate how much of the element is visible
          const elementHeight = rect.height;
          const visibleHeight = Math.min(rect.bottom, viewportHeight) - Math.max(rect.top, 0);
          const visibilityRatio = visibleHeight / elementHeight;

          // Only show indicators if element is significantly out of view (less than 50% visible)
          if (rect.bottom < topBuffer && visibilityRatio < 0.5) {
            setScrollDirection('up');
          } else if (rect.top > viewportHeight - bottomBuffer && visibilityRatio < 0.5) {
            setScrollDirection('down');
          } else {
            setScrollDirection(null);
          }
        } else {
          setScrollDirection(null);
        }
      } catch (error) {
        logger.error('Invalid selector in checkElementVisibility:', {
          selector: steps[currentStep].position,
          error: error instanceof Error ? error.message : String(error),
        });
        setScrollDirection(null);
      }
    }
  }, [currentStep, steps]);

  // Check visibility on mount, step changes, and after any position updates
  React.useEffect(() => {
    const win = getWindow();
    if (!win) return;

    if (showPointer && currentStep >= 0) {
      checkElementVisibility();
      const scrollHandler = () => {
        requestAnimationFrame(checkElementVisibility);
      };
      win.addEventListener('scroll', scrollHandler, { passive: true });

      // Also check after any potential position adjustments
      const positionCheckTimer = setInterval(checkElementVisibility, 100);

      return () => {
        win.removeEventListener('scroll', scrollHandler);
        clearInterval(positionCheckTimer);
      };
    } else {
      setScrollDirection(null);
    }
  }, [checkElementVisibility, showPointer, currentStep]);

  // Initialize SDK with performance monitoring
  React.useEffect(() => {
    const initializeSDK = async () => {
      if (initializationPromise.current) {
        return initializationPromise.current;
      }

      const metrics: InitializationMetrics = {
        startTime: performance.now(),
        storageTime: 0,
        apiServiceTime: 0,
        pageMapperTime: 0,
        totalTime: 0,
      };

      try {
        // Set initialized immediately to allow the app to start rendering
        setIsInitialized(true);

        // Initialize storage (this is fast and synchronous)
        metrics.storageTime = performance.now();
        storage.initialize();

        // Check if we're in SSR
        const browserStorage = typeof window !== 'undefined' ? window.localStorage : null;
        if (!browserStorage) {
          logger.debug('Pointer SDK: Running in SSR mode, deferring API initialization');
          return;
        }

        // Defer non-critical initialization
        await new Promise(resolve => setTimeout(resolve, 0));

        // Initialize API service with storage
        await apiService.initialize(projectId, browserStorage, apiUrl);
        metrics.apiServiceTime = performance.now();

        // Set user data if provided
        if (userData) {
          apiService.setUserData(userData);
        }

        // Initialize PageMapper after a short delay
        await new Promise(resolve => setTimeout(resolve, 50));
        if (!pageMapperRef.current) {
          pageMapperRef.current = new PageMapper({
            onMappingsUpdate: mappings => {
              setPageMappings(mappings);
            },
          });
        }
        metrics.pageMapperTime = performance.now();

        // Check if project ID is already verified
        if (projectIdVerificationCache.isProjectIdVerified(projectId, apiUrl)) {
          logger.debug('Pointer SDK: Using cached project ID verification');
          setIsBackendAvailable(true);
        } else {
          // Start project ID verification in the background
          projectIdVerificationCache.verifyProjectId(projectId, apiUrl).then(isVerified => {
            logger.debug('Pointer SDK: Project ID verification completed:', isVerified);
            setIsBackendAvailable(isVerified);
          });
        }

        metrics.totalTime = performance.now() - metrics.startTime;

        // Log performance metrics
        logger.debug('Pointer SDK: Initialization metrics:', {
          total: metrics.totalTime.toFixed(2) + 'ms',
          storage: (metrics.storageTime - metrics.startTime).toFixed(2) + 'ms',
          api: (metrics.apiServiceTime - metrics.storageTime).toFixed(2) + 'ms',
          pageMapper: (metrics.pageMapperTime - metrics.apiServiceTime).toFixed(2) + 'ms',
        });
      } catch (error) {
        logger.debug('Pointer SDK: Initialization failed:', error);
        setIsBackendAvailable(false);
        initializationPromise.current = null;
      }
    };

    initializationPromise.current = initializeSDK();
  }, [projectId, apiUrl, userData]);

  // Add cleanup for PageMapper
  React.useEffect(() => {
    return () => {
      if (pageMapperRef.current) {
        pageMapperRef.current.destroy();
        pageMapperRef.current = null;
      }
    };
  }, []);

  // Load active conversation on mount
  React.useEffect(() => {
    if (!isInitialized) return;

    const loadConversation = async () => {
      try {
        const activeConversation = storage.getActiveConversation();
        if (activeConversation) {
          setChatHistory(activeConversation.messages);
        }
      } catch (err) {
        logger.error('Failed to load conversation:', err);
      }
    };

    loadConversation();
  }, [isInitialized]);

  const stopGuide = React.useCallback(() => {
    if (activeGuide) {
      storage.markGuideCompleted(activeGuide.id);
      storage.clearGuideProgress();
    }

    setShowPointer(false);
    setCurrentStep(-1);
    setActiveGuide(null);
    setSteps([]);
    setIsGuideActive(false);
    setCompletedActions(new Set());
  }, [activeGuide]);

  const handleWalkthroughEnd = React.useCallback(() => {
    // Check if the guide was manually stopped
    const walkthroughState = getStorage().getItem('pointer_walkthrough_state');
    const wasManuallyStoppedByUser = walkthroughState
      ? JSON.parse(walkthroughState).wasManuallyStopped
      : false;

    // First, hide the UI elements
    setShowPointer(false);
    setIsGuideActive(false);

    // Clean up storage
    getStorage().removeItem('pointer_walkthrough_state');
    const pointerState = getStorage().getItem('pointerState');
    if (pointerState) {
      const currentState = JSON.parse(pointerState);
      getStorage().setItem(
        'pointerState',
        JSON.stringify({
          ...currentState,
          currentStep: -1,
          activeGuide: null,
          steps: [],
          isGuideActive: false,
          showPointer: false,
        }),
      );
    }

    // Open chat and show feedback if not manually stopped
    setIsChatOpen(true);
    if (!wasManuallyStoppedByUser) {
      // TODO: Add feedback message once fixed
      // const feedbackMessage: StorageMessage = {
      //   role: 'assistant',
      //   content: "Great! We've completed the walkthrough. Did this answer your question?",
      //   timestamp: Date.now(),
      //   showFeedback: false, // switch to true once fixed
      //   isCompletionMessage: true,
      // };
      // // Add to chat history for immediate display
      // setChatHistory(prevHistory => [
      //   ...prevHistory,
      //   {
      //     assistant: feedbackMessage.content,
      //     showFeedback: false, // switch to true once fixed
      //     feedbackGiven: null,
      //   },
      // ]);
      // // Get active conversation and save to storage
      // const activeConversation = storage.getActiveConversation();
      // if (activeConversation?.id) {
      //   // Ensure we're adding to the existing conversation
      //   storage.addMessage(activeConversation.id, feedbackMessage);
      // } else {
      //   // If no active conversation, create one with the existing chat history plus feedback
      //   const storageMessages: StorageMessage[] = chatHistory.map(msg => ({
      //     role: msg.assistant ? 'assistant' : 'user',
      //     content: msg.assistant || msg.user || '',
      //     timestamp: Date.now(),
      //     showFeedback: msg.showFeedback || false,
      //     feedbackGiven: msg.feedbackGiven === null ? undefined : msg.feedbackGiven,
      //   }));
      //   storageMessages.push(feedbackMessage);
      //   // Create a new conversation with a default title
      //   const conversationId = storage.createConversation('New conversation');
      //   if (conversationId) {
      //     // Add all messages to the new conversation
      //     storageMessages.forEach(msg => {
      //       storage.addMessage(conversationId, msg);
      //     });
      //     storage.setActiveConversation(conversationId);
      //   }
      // }
    }

    // Finally, clean up the guide state
    stopGuide();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stopGuide, setIsChatOpen, setChatHistory, setShowPointer, setIsGuideActive, chatHistory]);

  // Initialize WebSocket connection
  React.useEffect(() => {
    if (!isInitialized || disabled) return;
    const win = getWindow();
    if (!win) return;

    const initializeWebSocket = async () => {
      try {
        await guideSocketClient.connect({
          projectId,
          apiUrl,
          onGuideStep: response => {
            // Update guide state with new step
            const { step, currentStepIndex, isComplete, guideId } = response;

            // Convert the guide step to our internal format
            const formattedStep: Step = {
              id: step.id,
              position: step.position,
              instructions: step.instructions,
              page: step.metadata?.page || win.location.pathname,
              action: step.action,
            };

            // Update steps array
            setSteps(prevSteps => {
              const newSteps = [...prevSteps];
              newSteps[currentStepIndex] = formattedStep;
              return newSteps;
            });

            // Update current step if needed
            if (currentStep !== currentStepIndex) {
              setCurrentStep(currentStepIndex);
            }

            // Reset step generating state
            setIsStepGenerating(false);

            // Update chat history to maintain the initial message but add guide data
            setChatHistory(prevHistory => {
              const lastMessage = prevHistory[prevHistory.length - 1];
              if (lastMessage?.isGuideLoading) {
                // Keep the original message content but update the guide state
                return [
                  ...prevHistory.slice(0, -1),
                  {
                    ...lastMessage,
                    isGuideLoading: false,
                    guide: {
                      id: guideId,
                      name: step.metadata?.guideName || 'Guide',
                      steps: [formattedStep],
                    },
                  },
                ];
              }
              return prevHistory;
            });

            // If this is the last step, update isLastStep
            if (isComplete) {
              setIsLastStep(true);
            }
          },
          onGuideComplete: response => {
            // Store the completed guide
            const completedGuide: SimpleGuide = {
              id: response.guideId,
              name: response.name,
              steps: response.steps.map(step => ({
                id: step.id,
                position: step.position,
                instructions: step.instructions,
                page: step.metadata?.page || win.location.pathname,
                action: step.action,
              })),
            };

            // Update guides list
            setGuides(prevGuides => [...prevGuides, completedGuide]);

            // Mark the guide as complete in storage
            storage.markGuideCompleted(response.guideId);

            // Reset step generating state
            setIsStepGenerating(false);

            // Show completion popup with confetti
            logger.debug('[Completion Popup] Showing popup for guide:', response.guideId);
            setShowCompletionPopup(true);
            setIsCompletionVisible(true);

            // Start fade out after 2.5 seconds
            setTimeout(() => {
              setIsCompletionVisible(false);
              // Actually remove components after fade completes
              setTimeout(() => {
                setShowCompletionPopup(false);
              }, 500);
            }, 2500);

            // Clean up guide state
            handleWalkthroughEnd();
          },
          onError: error => {
            logger.error('Guide WebSocket error:', error);
            _setError(error.message);
            setIsStepGenerating(false);
            handleWalkthroughEnd();
          },
          onConnectionStateChange: connected => {
            if (!connected) {
              logger.debug('Guide WebSocket disconnected');
            }
          },
        });
      } catch (error) {
        logger.error('Failed to initialize WebSocket:', error);
        setIsBackendAvailable(false);
      }
    };

    initializeWebSocket();

    return () => {
      guideSocketClient.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isInitialized, disabled, projectId, apiUrl]);

  // Handle step transitions and position updates
  React.useEffect(() => {
    if (currentStep >= 0 && steps[currentStep] && showPointer) {
      // Clean up any existing position tracking
      if (positionCleanupRef.current) {
        positionCleanupRef.current();
        positionCleanupRef.current = null;
      }

      const currentStepData = steps[currentStep];
      // Start new position tracking
      const cleanup = updatePointerPosition(
        currentStepData,
        setPointerPosition,
        setTargetPosition,
        () => {
          handleWalkthroughEnd();
        },
      );

      // Store cleanup function
      positionCleanupRef.current = cleanup;

      return () => {
        if (positionCleanupRef.current) {
          positionCleanupRef.current();
          positionCleanupRef.current = null;
        }
      };
    }
  }, [currentStep, steps, showPointer, handleWalkthroughEnd]);

  // Handle action completion and step transitions
  const handleActionCompletion = React.useCallback(
    async (stepId: string) => {
      if (isStepGenerating) return; // Prevent multiple completions while generating
      try {
        setIsStepGenerating(true);
        setCompletedActions(prev => {
          const newSet = new Set([...prev, stepId]);

          if (activeGuide) {
            storage.saveGuideProgress({
              guideId: activeGuide.id,
              currentStep,
              completedActions: Array.from(newSet),
            });
          }

          return newSet;
        });

        // Force update UI mappings before sending step completion
        logger.debug('PointerContext: Forcing UI mappings update before step completion');
        logger.debug('PointerContext: This will wait for page to be fully loaded and stable');
        let updatedMappings: ElementMapping[] = [];

        if (pageMapperRef.current) {
          try {
            // Wait for mappings to be fully updated
            // This will now wait for page stability before mapping
            updatedMappings = await pageMapperRef.current.forceUpdateMappings();
            logger.debug(
              '🎯 PointerContext: UI mappings updated successfully after page stabilized',
              updatedMappings.length,
            );
          } catch (mappingError) {
            logger.error('Failed to update UI mappings:', mappingError);
            // Fall back to current mappings if force update fails
            updatedMappings = pageMapperRef.current.getCurrentMappings();
          }
        }

        // Send step completion to WebSocket and wait for response
        await guideSocketClient.sendStepComplete({
          stepId,
          updatedUiElements: updatedMappings,
        });

        // Note: Don't set isStepGenerating to false here
        // It will be set to false when we receive the next step or guide completion
      } catch (error) {
        logger.error('Failed to complete step:', error);
        setIsStepGenerating(false); // Reset on error
      }
    },
    [currentStep, activeGuide, setCompletedActions, isStepGenerating],
  );

  const isStepActionCompleted = React.useCallback(
    (stepId: string) => {
      return completedActions.has(stepId);
    },
    [completedActions],
  );

  // Update startGuide to use WebSocket
  const startGuide = React.useCallback(
    async (guide: SimpleGuide) => {
      try {
        // If guide already has steps, start it directly without making a new request
        if (guide.steps && guide.steps.length > 0) {
          setActiveGuide(guide);
          setSteps(guide.steps);
          setCurrentStep(0);
          setShowPointer(true);
          setIsGuideActive(true);
          setIsLastStep(false);
          setCompletedActions(new Set());
          return;
        }

        // Only proceed with WebSocket initialization if we don't have steps
        const activeConversation = storage.getActiveConversation();
        let conversationId = activeConversation?.id;

        if (!conversationId) {
          const conversation = await apiService.createConversation();
          conversationId = conversation.id;
        }

        // Save initial guide progress
        storage.saveGuideProgress({
          guideId: guide.id,
          currentStep: 0,
          completedActions: [],
        });

        // Force update UI mappings before starting the guide
        logger.debug('PointerContext: Forcing UI mappings update before starting guide');
        logger.debug('PointerContext: This will wait for page to be fully loaded and stable');
        let updatedMappings: ElementMapping[] = [];

        if (pageMapperRef.current) {
          try {
            // Wait for mappings to be fully updated
            // This will now wait for page stability before mapping
            updatedMappings = await pageMapperRef.current.forceUpdateMappings();
            logger.debug(
              '🎯 PointerContext: UI mappings updated successfully for guide start after page stabilized',
              updatedMappings.length,
            );
          } catch (mappingError) {
            logger.error('Failed to update UI mappings for guide start:', mappingError);
            // Fall back to current mappings if force update fails
            updatedMappings = pageMapperRef.current.getCurrentMappings();
          }
        }

        // Start the guide via WebSocket
        await guideSocketClient.startGuide({
          message: `Start guide: ${guide.name}`,
          conversationId,
          uiElements: updatedMappings,
        });

        // Update local state
        setActiveGuide(guide);
        setSteps(guide.steps);
        setCurrentStep(0);
        setShowPointer(true);
        setIsGuideActive(true);
        setIsLastStep(false);
        setCompletedActions(new Set());
      } catch (error) {
        logger.error('Failed to start guide:', error);
        _setError('Failed to start guide');
      }
    },
    [
      setActiveGuide,
      setSteps,
      setCurrentStep,
      setShowPointer,
      setIsGuideActive,
      setIsLastStep,
      setCompletedActions,
      _setError,
    ],
  );

  const nextStep = React.useCallback(() => {
    if (isStepGenerating) return; // Prevent progression while generating
    const currentStepData = steps[currentStep];

    // Only proceed if the current step's action is completed or there is no action
    if (!currentStepData?.action || isStepActionCompleted(currentStepData.id)) {
      // Check if next step would be the last one
      if (currentStep === steps.length - 2) {
        setIsLastStep(true);
      }

      // Show click animation before moving to next step
      setShowCursorClick(true);

      // Wait for animation to complete before moving to next step
      setTimeout(() => {
        setShowCursorClick(false);

        if (currentStep < steps.length - 1) {
          setCurrentStep(prev => prev + 1);
        } else {
          handleWalkthroughEnd();
        }
      }, 600);
    }
  }, [currentStep, steps, isStepActionCompleted, isStepGenerating, handleWalkthroughEnd]);

  React.useEffect(() => {
    const win = getWindow();
    if (!win) return;
    const doc = getDocument();
    if (!doc) return;

    if (currentStep >= 0 && steps[currentStep]) {
      const currentStepData = steps[currentStep];
      let targetElement: Element | null = null;

      try {
        targetElement = doc.querySelector(currentStepData.position);
      } catch (error) {
        logger.error('Invalid selector in effect:', {
          selector: currentStepData.position,
          error: error instanceof Error ? error.message : String(error),
        });
      }

      if (targetElement && currentStepData.action && !isStepActionCompleted(currentStepData.id)) {
        const handleValidationComplete = ({ shouldComplete }: { shouldComplete: boolean }) => {
          if (shouldComplete) {
            // Dispatch stepComplete event
            const stepCompleteEvent = new CustomEvent('stepComplete', {
              detail: { stepId: currentStepData.id },
            });
            win.dispatchEvent(stepCompleteEvent);
            handleActionCompletion(currentStepData.id);
          }
        };

        // Set up validation with the centralized validator
        const cleanup = actionValidator.setupValidation(
          targetElement as HTMLElement,
          currentStepData.action,
          handleValidationComplete,
          {
            shouldPreventDefault: currentStepData.action.type === 'submit',
          },
        );

        return cleanup;
      }

      if (currentStepData.action && !isStepActionCompleted(currentStepData.id)) {
        // Wait for page to be stable before completing any action
        const validatePageLoad = async () => {
          try {
            // Wait for PageMapper to indicate the page is stable
            if (pageMapperRef.current) {
              logger.debug('Action: Waiting for page stability');
              await pageMapperRef.current.forceUpdateMappings();
              logger.debug('Action: Page is stable, completing step');
              handleActionCompletion(currentStepData.id);
            }
          } catch (error) {
            logger.error('Action: Error validating page load:', error);
            // Even if there's an error, we should still complete the step after a reasonable delay
            setTimeout(() => {
              logger.debug('Action: Completing step after error recovery delay');
              handleActionCompletion(currentStepData.id);
            }, 2000);
          }
        };

        // Start validation
        validatePageLoad();
      }
    }
  }, [currentStep, steps, handleActionCompletion, isStepActionCompleted]);

  const contextValue: PointerContextType = {
    isInitialized,
    error,
    currentStep,
    setCurrentStep,
    showPointer,
    setShowPointer,
    steps,
    setSteps,
    activeStepId,
    setActiveStepId,
    isLastStep,
    setIsLastStep,
    activeGuide,
    setActiveGuide,
    isChatOpen,
    setIsChatOpen,
    guides,
    setGuides,
    defaultResponse,
    setDefaultResponse,
    triggerPhrases,
    setTriggerPhrases,
    startGuide,
    nextStep,
    stopGuide,
    pointerPosition,
    setPointerPosition,
    targetPosition,
    setTargetPosition,
    isGuideActive,
    setIsGuideActive,
    handleWalkthroughEnd,
    handleActionCompletion,
    isStepActionCompleted,
    isStepGenerating,
    chatHistory,
    setChatHistory,
    pageMappings,
    getCurrentMappings: React.useCallback(
      () => pageMapperRef.current?.getCurrentMappings() || [],
      [],
    ),
    scrollDirection,
    setScrollDirection,
    triggerId,
  };

  if (!isInitialized || disabled) {
    return <>{children}</>;
  }

  return (
    <ThemeProvider customization={customization}>
      <PointerContext.Provider value={contextValue}>
        {children}
        {isInitialized && isBackendAvailable && !disabled && (
          <>
            {isInitialized &&
              !error &&
              showPointer &&
              currentStep >= 0 &&
              steps &&
              steps.length > currentStep &&
              createPortal(
                <div
                  id="pointer-sdk-root"
                  style={{
                    position: 'fixed',
                    inset: 0,
                    pointerEvents: 'none',
                    zIndex: 99999, // Add root level z-index
                    fontFamily: 'var(--font-family)',
                  }}>
                  <style>
                    {`
                      .pointer-events-none {
                        pointer-events: none;
                      }
                      @keyframes pulse {
                        0%, 100% { opacity: 1; }
                        50% { opacity: 0.5; }
                      }
                    `}
                  </style>
                  <div
                    style={{
                      position: 'fixed',
                      zIndex: 99999,
                    }}>
                    <StepComponent
                      stepId={steps[currentStep].id}
                      instructions={steps[currentStep].instructions}
                      isLastStep={isLastStep}
                      onNextStep={nextStep}
                      onStopGuide={stopGuide}
                      position={pointerPosition}
                      onWalkthroughEnd={handleWalkthroughEnd}
                    />
                    {/* Cursor is rendered separately to give control to the Step component */}
                  </div>
                  {scrollDirection && <ScrollIndicator direction={scrollDirection} />}
                </div>,
                getDocument()!.body,
              )}
            {isBackendAvailable && <Widget />}
            {/* Completion popup with confetti */}
            {showCompletionPopup && (
              <>
                <div
                  style={{
                    position: 'fixed',
                    bottom: 0,
                    left: 0,
                    right: 0,
                    height: '100vh',
                    pointerEvents: 'none',
                    opacity: isCompletionVisible ? 1 : 0,
                    transition: 'opacity 0.5s ease-out',
                  }}>
                  <Confetti
                    mode="boom"
                    particleCount={50}
                    colors={['#ff577f', '#ff884b', '#ffd384', '#fff9b0']}
                    effectCount={1}
                    effectInterval={1500}
                    y={0.85}
                  />
                </div>
                <div
                  style={{
                    position: 'fixed',
                    bottom: '2rem',
                    left: '50%',
                    transform: 'translateX(-50%)',
                    backgroundColor: 'var(--pointer-background-color)',
                    padding: '0.5rem 1rem',
                    borderRadius: 'var(--pointer-border-radius)',
                    border: '1px solid var(--pointer-border-color)',
                    boxShadow: '0 4px 24px -4px rgba(0, 0, 0, 0.08)',
                    zIndex: 99999,
                    animation: 'slideUpAndFade 0.3s ease-out',
                    fontSize: '14px',
                    fontWeight: 500,
                    color: 'var(--pointer-secondary-color)',
                    opacity: isCompletionVisible ? 1 : 0,
                    transition: 'opacity 0.5s ease-out',
                  }}>
                  <style>
                    {`
                      @keyframes slideUpAndFade {
                        from { 
                          opacity: 0; 
                          transform: translate(-50%, 1rem); 
                        }
                        to { 
                          opacity: 1; 
                          transform: translate(-50%, 0); 
                        }
                      }
                    `}
                  </style>
                  ✨ Great job! You've completed this guide!
                </div>
              </>
            )}
          </>
        )}
      </PointerContext.Provider>
    </ThemeProvider>
  );
};
