import * as React from 'react';
import { PenSquare, Clock, Maximize2, Minimize2 } from '../../../components/icons';
import { Button } from '../../../components/base/Button';
import styles from './HeaderActions.module.css';

interface HeaderActionsProps {
  onNewChat: () => void;
  onHistoryClick: () => void;
  onClose: () => void;
  isMaximized: boolean;
  onToggleSize: () => void;
}

export const HeaderActions: React.FC<HeaderActionsProps> = ({
  onNewChat,
  onHistoryClick,
  isMaximized,
  onToggleSize,
}) => {
  return (
    <div className={styles.container}>
      <Button variant="ghost" size="icon" onClick={onNewChat} className={styles.button}>
        <PenSquare className={styles.icon} />
      </Button>
      <Button variant="ghost" size="icon" onClick={onHistoryClick} className={styles.button}>
        <Clock className={styles.icon} />
      </Button>
      <Button variant="ghost" size="icon" onClick={onToggleSize} className={styles.button}>
        {isMaximized ? (
          <Minimize2 className={styles.icon} />
        ) : (
          <Maximize2 className={styles.icon} />
        )}
      </Button>
    </div>
  );
};
