import * as React from 'react';
import { Avatar } from '../../../components/base/Avatar';
import type { DisplayMessage, RuntimeGuide } from '../../../types';
import { MessageActions } from './MessageActions';
import { LoadingDots } from './LoadingDots';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { MarkdownAnimateText } from './MarkdownAnimateText';
import styles from './MessageItem.module.css';

interface MessageItemProps {
  message: DisplayMessage;
  userAvatar: string;
  assistantLogo: string;
  onGuideStart?: (guide: RuntimeGuide) => void;
  onFeedback?: (feedback: 'yes' | 'no') => void;
}

export const MessageItem: React.FC<MessageItemProps> = ({
  message,
  userAvatar,
  assistantLogo,
  onGuideStart,
  onFeedback,
}) => {
  const isUser = !!message.user;
  const isEmptyStreaming = !isUser && message.isStreaming && !message.assistant;

  const formatMarkdown = (text: string) => {
    // Ensure proper line breaks for list items
    return text
      .replace(/(\d+\.|\*)\s/g, '\n$1 ') // Add newline before list items
      .replace(/\n{3,}/g, '\n\n') // Remove excess newlines
      .trim();
  };

  return (
    <div className={`${styles.container} ${isUser ? styles.userMessage : styles.assistantMessage}`}>
      <Avatar
        className={styles.avatar}
        src={isUser ? undefined : assistantLogo}
        alt={isUser ? 'User' : 'Assistant'}
        fallback={isUser ? userAvatar : undefined}
        size="sm"
      />
      <div
        className={`${styles.messageContent} ${isUser ? styles.userContent : styles.assistantContent}`}>
        {isEmptyStreaming ? (
          <div className={styles.loadingContainer}>
            <LoadingDots />
          </div>
        ) : (
          <div
            className={`${styles.bubble} ${isUser ? styles.userBubble : styles.assistantBubble}`}>
            {isUser ? (
              message.user
            ) : message.isStreaming ? (
              <MarkdownAnimateText
                content={formatMarkdown(message.assistant || '')}
                sep="word"
                animation="fadeIn"
                animationDuration="0.25s"
                animationTimingFunction="ease-out"
              />
            ) : (
              <div className={styles.animatedMarkdown}>
                <ReactMarkdown
                  remarkPlugins={[remarkGfm]}
                  components={{
                    p: ({ children }) => <p className={styles.paragraph}>{children}</p>,
                    ul: ({ children }) => <ul className={styles.list}>{children}</ul>,
                    ol: ({ children }) => <ol className={styles.list}>{children}</ol>,
                    li: ({ children }) => <li className={styles.listItem}>{children}</li>,
                    strong: ({ children }) => <strong className={styles.bold}>{children}</strong>,
                    br: () => <br />,
                  }}>
                  {formatMarkdown(message.assistant || '')}
                </ReactMarkdown>
              </div>
            )}
          </div>
        )}
        {!isUser && (
          <MessageActions
            guide={message.guide || undefined}
            showGuideButton={message.showGuideButton}
            showFeedback={message.showFeedback}
            feedbackGiven={message.feedbackGiven}
            onGuideStart={onGuideStart}
            onFeedback={onFeedback}
            isGuideLoading={message.isGuideLoading}
          />
        )}
      </div>
    </div>
  );
};
