import { useEffect, useState, useRef, useCallback } from 'react';
import { X, ChevronsRight } from '../icons';
import { Card } from '../base/Card';
import { Tooltip } from '../base/Tooltip';
import { Button } from '../base/Button';
import { ScrollIndicator } from '../scroll';
import styles from '../Step.module.css';
import { Cursor } from '../cursor';
import type { Action } from '@/sdk/types';
import { actionValidator } from '../../utils/actionValidation';
import { getDocument, getWindow } from '../../index';
import React from 'react';

import { logger } from '../../utils/logger';
interface FlowStepProps {
  instructions: string;
  isLastStep: boolean;
  onNextStep: () => void;
  onStopGuide: () => void;
  position: { top: number; left: number };
  onWalkthroughEnd: () => void;
  stepId?: string;
  currentStep: number;
  totalSteps: number;
  action?: Action;
  scrollDirection?: 'up' | 'down' | null;
  type: 'guided' | 'self-paced' | 'modal';
  content?: {
    title?: string;
    description: string;
    media?: {
      type: 'image' | 'video';
      url: string;
    };
  };
  onPreviousStep?: () => void;
  showCloseButton?: boolean;
  pollDuration?: number; // Custom duration in milliseconds to poll for an element
  autoScroll?: boolean; // Whether to automatically scroll to the element
}

// Wrap the component with React.memo
export const FlowStep = React.memo(
  ({
    instructions,
    isLastStep,
    onNextStep,
    onStopGuide,
    stepId = '',
    currentStep,
    action,
    scrollDirection: externalScrollDirection,
    onWalkthroughEnd,
    type,
    onPreviousStep,
    showCloseButton = true,
    pollDuration,
    autoScroll,
  }: FlowStepProps) => {
    const [_isValidated, setIsValidated] = useState(false);
    const [isVisible, setIsVisible] = useState(false);
    const [_isCustomValidationActive, setIsCustomValidationActive] = useState(false);
    const [targetPosition, setTargetPosition] = useState({ top: 0, left: 0, width: 0, height: 0 });
    const [_pointerPosition, setPointerPosition] = useState({ top: 0, left: 0 });
    const [scrollDirection, setScrollDirection] = useState<'up' | 'down' | null>(
      externalScrollDirection || null,
    );
    const customValidationTimerRef = useRef<NodeJS.Timeout | null>(null);
    const customValidationIntervalRef = useRef<NodeJS.Timeout | null>(null);
    const stepIdRef = useRef<string>(stepId);
    const isWaitingForElement = useRef<boolean>(false);
    const hasCompletedValidation = useRef<boolean>(false);

    // Cursor-related states
    const [showClickEffect, setShowClickEffect] = useState(false);
    const [cardVisible, setCardVisible] = useState(false);
    const [cursorReady, setCursorReady] = useState(false);
    const [cursorVisible, setCursorVisible] = useState(true);
    const [initialAnimation, setInitialAnimation] = useState(true);
    const [widgetPosition, setWidgetPosition] = useState({ top: 0, left: 0 });
    const [cursorInPosition, setCursorInPosition] = useState(false);
    const [finalCursorPos, setFinalCursorPos] = useState({ top: 0, left: 0 });
    const [pointerDirection, setPointerDirection] = useState<'left' | 'right'>('left');
    const [isExiting, setIsExiting] = useState(false);
    const [cursorPosition, setCursorPosition] = useState<'default' | 'card-bottom'>('default');

    // Add hasSearched ref at component level
    const hasSearched = useRef(false);

    // In the component body, after the other state and ref declarations
    const lastScrollDirectionUpdateRef = useRef<number>(0);
    const lastScrollDirectionValueRef = useRef<'up' | 'down' | null>(null);
    const SCROLL_UPDATE_INTERVAL = 150; // milliseconds

    // Track step changes
    useEffect(() => {
      // If stepId changes, we're moving to a new step
      if (stepIdRef.current !== stepId) {
        // Reset states for new step
        setCardVisible(false);
        setIsValidated(false);
        setIsCustomValidationActive(false);
        hasCompletedValidation.current = false;
        hasSearched.current = false; // Reset hasSearched when step changes

        setInitialAnimation(false);
        setIsExiting(false);
        setIsVisible(true);

        // Reset waiting state
        isWaitingForElement.current = false;

        // Update ref
        stepIdRef.current = stepId;
      }
    }, [stepId]);

    // Handle cursor click effect - memoized to prevent unnecessary recreations
    const handleCursorClick = useCallback(() => {
      setShowClickEffect(true);
      setTimeout(() => {
        setShowClickEffect(false);
      }, 400); // Reduced from 600ms to 400ms for faster click effect
    }, []);

    // Update scrollDirection when external prop changes
    useEffect(() => {
      if (externalScrollDirection !== undefined) {
        setScrollDirection(externalScrollDirection);
      }
    }, [externalScrollDirection]);

    // Find element and calculate positions
    useEffect(() => {
      let findElementAttempts = 0;
      const DEFAULT_INTERVAL = 250; // ms
      const DEFAULT_MAX_DURATION = 10000; // 10 seconds (40 attempts * 250ms)

      // If pollDuration is provided, calculate the max attempts based on the duration
      const customDuration = pollDuration || DEFAULT_MAX_DURATION;
      const MAX_ATTEMPTS = Math.ceil(customDuration / DEFAULT_INTERVAL);

      // For logging purposes
      const effectivePollingTime = MAX_ATTEMPTS * DEFAULT_INTERVAL;

      // Check if we've already searched
      if (hasSearched.current) {
        return;
      }

      logger.debug('[FlowStep] Starting element search', {
        stepId,
        pollDuration: customDuration,
        maxAttempts: MAX_ATTEMPTS,
        timestamp: new Date().toISOString(),
      });

      const findElement = () => {
        if (typeof window === 'undefined') return false;
        const win = getWindow();
        if (!win) return false;
        const doc = getDocument();
        if (!doc) return false;

        // Try exact match first
        let element = doc.getElementById(stepId);

        // If not found, try partial match
        if (!element) {
          const elements = Array.from(doc.querySelectorAll('[id]')).filter((el: Element) =>
            el.id.includes(stepId),
          );
          // Only use if we found exactly one match to ensure uniqueness
          if (elements.length === 1) {
            element = elements[0] as HTMLElement;
          }
        }

        if (!element) {
          // Mark that we're waiting for the element
          isWaitingForElement.current = true;
          logger.debug('[FlowStep] Element not found, waiting', {
            stepId,
            attempt: findElementAttempts,
            timestamp: new Date().toISOString(),
          });
          return false;
        }

        // Mark that we've searched
        hasSearched.current = true;

        // Create a function to calculate positions after scrolling
        const calculatePositionsAfterScroll = () => {
          if (typeof window === 'undefined') return false;
          const win = getWindow();
          if (!win) return false;

          const rect = element.getBoundingClientRect();

          // Check if element is actually visible and has dimensions
          if (rect.width === 0 || rect.height === 0) {
            isWaitingForElement.current = true;
            return false;
          }

          // Element found and visible, we're no longer waiting
          isWaitingForElement.current = false;

          // Calculate optimal placement for cursor
          const windowWidth = win.innerWidth;
          const windowHeight = win.innerHeight;

          // Determine pointer direction based on element position
          const direction = rect.left > windowWidth / 2 ? 'right' : 'left';
          setPointerDirection(direction);

          // Check if element is too close to the bottom or edges of the viewport
          const SAFE_MARGIN = 120; // Minimum safe distance from screen edges
          const isNearBottom = rect.bottom > windowHeight - SAFE_MARGIN;
          const isNearRight = rect.right > windowWidth - SAFE_MARGIN && direction === 'left';
          const isNearLeft = rect.left < SAFE_MARGIN && direction === 'right';

          // Set cursor position based on available space
          if (isNearBottom || isNearRight || isNearLeft) {
            setCursorPosition('card-bottom');
          } else {
            setCursorPosition('default');
          }

          // Set target position for highlighting
          const newTargetPosition = {
            top: rect.top,
            left: rect.left,
            width: rect.width,
            height: rect.height,
          };
          setTargetPosition(newTargetPosition);

          // Calculate cursor position
          const cursorSize = 20;
          const horizontalOffset = rect.width * 0.04;

          let cursorPos;
          if (direction === 'left') {
            cursorPos = {
              left: rect.left + rect.width / 2 + horizontalOffset - cursorSize / 2,
              top: rect.top + rect.height / 2 - 2,
            };
          } else {
            cursorPos = {
              left: rect.left + rect.width / 2 - horizontalOffset - cursorSize / 2,
              top: rect.top + rect.height / 2 - 2,
            };
          }

          setPointerPosition(cursorPos);
          setFinalCursorPos(cursorPos);

          return true;
        };

        // Scroll the element into view with smooth behavior
        if (autoScroll) {
          element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }

        // Wait for the scroll to complete before calculating positions
        // Use a single timeout with a longer duration to ensure scroll is complete
        setTimeout(() => {
          calculatePositionsAfterScroll();
        }, 300); // Increased from 200ms to 300ms to ensure scroll is complete

        // Return true immediately to indicate the element was found
        // The position calculation will happen after the scroll
        return true;
      };

      // Initial check
      const isPositioned = findElement();

      if (isPositioned) {
        setIsVisible(true);
        setCardVisible(false);

        // Only reset cursor position after we've found the new element
        setCursorInPosition(false);

        // Keep cursor ready true to maintain animation
        setCursorReady(true);

        // Reset validation state when element is found
        setIsValidated(false);
        setIsCustomValidationActive(false);

        const movementTimer = setTimeout(() => {
          setCursorInPosition(true);

          const cardTimer = setTimeout(() => {
            setCardVisible(true);
          }, 150);

          return () => clearTimeout(cardTimer);
        }, 400);

        return () => clearTimeout(movementTimer);
      }

      // Set up interval to periodically check for the element
      const intervalId = setInterval(() => {
        findElementAttempts++;

        if (findElementAttempts >= MAX_ATTEMPTS) {
          clearInterval(intervalId);
          logger.warn(
            `Element search timeout: Element with ID "${stepId}" not found after ${effectivePollingTime}ms (pollDuration: ${customDuration}ms)`,
          );
          isWaitingForElement.current = false;
          return;
        }

        const found = findElement();
        if (found) {
          clearInterval(intervalId);

          setIsVisible(true);
          setCardVisible(false);

          // Only reset cursor position after we've found the new element
          setCursorInPosition(false);

          // Keep cursor ready true to maintain animation
          setCursorReady(true);

          // Reset validation state when element is found
          setIsValidated(false);
          setIsCustomValidationActive(false);

          const movementTimer = setTimeout(() => {
            setCursorInPosition(true);

            const cardTimer = setTimeout(() => {
              setCardVisible(true);
            }, 150);

            return () => clearTimeout(cardTimer);
          }, 400);

          return () => clearTimeout(movementTimer);
        }
      }, DEFAULT_INTERVAL);

      // Create throttled version of findElement for viewport changes
      const throttledFindElement = (() => {
        let lastRun = 0;
        let timeout: ReturnType<typeof setTimeout> | null = null;

        return () => {
          const now = Date.now();
          if (lastRun && now < lastRun + 150) {
            if (timeout) clearTimeout(timeout);
            timeout = setTimeout(() => {
              lastRun = now;
              findElement();
            }, 150);
            return;
          }
          lastRun = now;
          findElement();
        };
      })();

      // Handle scroll and resize with throttling
      const handleViewportChange = () => {
        throttledFindElement();
      };

      if (typeof window === 'undefined') return;
      const win = getWindow();
      if (!win) return;

      win.addEventListener('scroll', handleViewportChange, { passive: true });
      win.addEventListener('resize', handleViewportChange, { passive: true });

      return () => {
        clearInterval(intervalId);
        win.removeEventListener('scroll', handleViewportChange);
        win.removeEventListener('resize', handleViewportChange);
      };
    }, [stepId, pollDuration, autoScroll]);

    // Track visibility state changes
    useEffect(() => {}, [
      isVisible,
      cursorReady,
      cursorInPosition,
      cardVisible,
      targetPosition,
      stepId,
      isExiting,
    ]);

    // Get widget position for initial animation
    useEffect(() => {
      if (typeof window === 'undefined') return;
      const win = getWindow();
      if (!win) return;
      const doc = getDocument();
      if (!doc) return;

      // Find the widget trigger button
      const widgetTrigger = doc.querySelector('.Widget-module__triggerButton___i7xat');
      if (widgetTrigger) {
        const rect = widgetTrigger.getBoundingClientRect();
        setWidgetPosition({
          top: rect.top + rect.height / 2,
          left: rect.left + rect.width / 2,
        });
      } else {
        // Fallback if widget button not found
        setWidgetPosition({
          top: win.innerHeight - 50,
          left: win.innerWidth - 50,
        });
      }
    }, []);

    // Enhanced fade-in sequence with initial animation - only for the very first step
    useEffect(() => {
      if (!initialAnimation) return;

      // First make the component itself visible
      const visibilityTimer = setTimeout(() => {
        // Reset cursor position state
        setCursorInPosition(false);

        // Start with cursor completely hidden
        setCursorReady(false);

        // After a short delay, make cursor visible and start moving to target
        setTimeout(() => {
          // Show cursor at widget position first
          setCursorReady(true);

          // After cursor has moved to position, mark it as in position
          const movementTimer = setTimeout(() => {
            setCursorInPosition(true);

            // Only after cursor is in position, show the card
            const cardTimer = setTimeout(() => {
              setCardVisible(true);
            }, 150);

            return () => clearTimeout(cardTimer);
          }, 400);

          // Clean up movement timer
          return () => {
            clearTimeout(movementTimer);
          };
        }, 100);
      }, 50);

      return () => clearTimeout(visibilityTimer);
    }, [initialAnimation, widgetPosition]);

    // Action validation
    useEffect(() => {
      if (!isVisible || !action || type === 'self-paced' || isWaitingForElement.current) {
        if (!action || type === 'self-paced') setIsValidated(true);
        return;
      }

      // Helper function to find element with partial ID matching
      const findElement = (id: string): HTMLElement | null => {
        if (typeof window === 'undefined') return null;
        const doc = getDocument();
        if (!doc) return null;
        const win = getWindow();
        if (!win) return null;

        // Try exact match first
        let element = doc.getElementById(id);

        // If not found, try partial match
        if (!element) {
          const elements = Array.from(doc.querySelectorAll('[id]')).filter(el =>
            el.id.includes(id),
          );
          // Only use if we found exactly one match to ensure uniqueness
          if (elements.length === 1) {
            element = elements[0] as HTMLElement;
          }
        }

        // If element is found, scroll it into view
        if (autoScroll && element) {
          element.scrollIntoView({ behavior: 'smooth', block: 'center' });

          // Use a sequence of timeouts to ensure we catch the final position after scrolling
          const updatePositionAfterScroll = () => {
            const rect = element.getBoundingClientRect();
            const newTargetPosition = {
              top: rect.top,
              left: rect.left,
              width: rect.width,
              height: rect.height,
            };
            setTargetPosition(newTargetPosition);
          };

          // Update position multiple times to ensure we get the final position
          setTimeout(() => {
            updatePositionAfterScroll();

            // Second update after a delay
            setTimeout(() => {
              updatePositionAfterScroll();

              // Final update at a longer interval
              setTimeout(() => {
                updatePositionAfterScroll();
              }, 100);
            }, 100);
          }, 200);
        }

        return element;
      };

      const targetElement = findElement(stepId);
      if (!targetElement || !cursorInPosition) return;

      const handleValidationComplete = ({ shouldComplete }: { shouldComplete: boolean }) => {
        if (shouldComplete && !hasCompletedValidation.current) {
          hasCompletedValidation.current = true;

          // Hide card first
          setCardVisible(false);

          // Show click effect
          handleCursorClick();

          setIsValidated(true);

          // If this is the last step, start the exit sequence
          if (isLastStep) {
            setIsExiting(true);
            // Fade out cursor
            setTimeout(() => {
              setCursorVisible(false);
              // Wait for fade out animation before calling onWalkthroughEnd
              setTimeout(() => {
                onWalkthroughEnd();
              }, 300);
            }, 300);
          }

          // Wait a moment before moving to next step (shorter delay)
          setTimeout(
            () => {
              onNextStep();
            },
            isLastStep ? 600 : 400,
          );
        }
      };

      // Set up validation with the centralized validator
      const cleanup = actionValidator.setupValidation(
        targetElement,
        action,
        handleValidationComplete,
        {
          shouldPreventDefault: action.type === 'submit',
        },
      );

      return () => {
        cleanup();
      };
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [
      action,
      stepId,
      onNextStep,
      isVisible,
      handleCursorClick,
      isLastStep,
      onWalkthroughEnd,
      type,
      cursorInPosition,
      isWaitingForElement.current,
      autoScroll,
    ]);

    // Custom validation
    useEffect(() => {
      if (
        !isVisible ||
        !action ||
        action.type !== 'custom' ||
        !action.customValidation ||
        isWaitingForElement.current ||
        !cursorInPosition ||
        hasCompletedValidation.current
      )
        return;

      setIsCustomValidationActive(true);

      const { condition, pollingInterval, timeout } = action.customValidation;

      if (!condition) {
        logger.warn('[Custom Validation] No condition provided for custom validation');
        return;
      }

      // Function to perform the validation check
      const checkCondition = () => {
        try {
          if (condition() && !hasCompletedValidation.current) {
            hasCompletedValidation.current = true;

            // Hide card first
            setCardVisible(false);

            // Show click effect
            handleCursorClick();

            setIsValidated(true);
            setIsCustomValidationActive(false);

            // If this is the last step, start the exit sequence
            if (isLastStep) {
              setIsExiting(true);
              // Fade out cursor
              setTimeout(() => {
                setCursorVisible(false);
                // Wait for fade out animation before calling onWalkthroughEnd
                setTimeout(() => {
                  onWalkthroughEnd();
                }, 300);
              }, 300);
            }

            // Wait a moment before moving to next step (shorter delay)
            setTimeout(
              () => {
                onNextStep();
              },
              isLastStep ? 600 : 400,
            );

            // Clean up
            if (customValidationIntervalRef.current) {
              clearInterval(customValidationIntervalRef.current);
              customValidationIntervalRef.current = null;
            }
            if (customValidationTimerRef.current) {
              clearTimeout(customValidationTimerRef.current);
              customValidationTimerRef.current = null;
            }
          }
        } catch (error) {
          logger.error('[Custom Validation] Error in custom validation condition', error);
        }
      };

      // Initial check
      checkCondition();

      // Set up polling if requested
      if (pollingInterval && pollingInterval > 0) {
        customValidationIntervalRef.current = setInterval(checkCondition, pollingInterval);
      }

      // Set up timeout if requested
      if (timeout && timeout > 0) {
        customValidationTimerRef.current = setTimeout(() => {
          if (customValidationIntervalRef.current) {
            clearInterval(customValidationIntervalRef.current);
            customValidationIntervalRef.current = null;
          }

          setIsCustomValidationActive(false);
        }, timeout);
      }

      // Cleanup on unmount or when action changes
      return () => {
        if (customValidationIntervalRef.current) {
          clearInterval(customValidationIntervalRef.current);
          customValidationIntervalRef.current = null;
        }
        if (customValidationTimerRef.current) {
          clearTimeout(customValidationTimerRef.current);
          customValidationTimerRef.current = null;
        }
        setIsCustomValidationActive(false);
      };
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isVisible, action, stepId, onNextStep, handleCursorClick, isLastStep, onWalkthroughEnd]);

    // Replace the existing visibility check effect
    // Calculate if element is in viewport and set scroll direction
    useEffect(() => {
      if (!isVisible) return;

      const checkVisibility = () => {
        if (typeof window === 'undefined') return;
        const win = getWindow();
        if (!win) return;
        const doc = getDocument();
        if (!doc) return;

        // Throttle updates - skip if called too frequently
        const now = Date.now();
        if (now - lastScrollDirectionUpdateRef.current < SCROLL_UPDATE_INTERVAL) {
          return; // Skip this update if it's too soon after the last one
        }

        // Try to find the element using direct DOM query instead of relying on state
        let element = doc.getElementById(stepId);
        if (!element) {
          const elements = Array.from(doc.querySelectorAll('[id]')).filter((el: Element) =>
            el.id.includes(stepId),
          );
          if (elements.length === 1) {
            element = elements[0] as HTMLElement;
          }
        }

        // Get dimensions from the actual element if found, or fall back to state
        let elementRect: {
          top: number;
          bottom: number;
          height: number;
        } = {
          top: targetPosition.top,
          bottom: targetPosition.top + targetPosition.height,
          height: targetPosition.height,
        };

        if (element) {
          const rect = element.getBoundingClientRect();
          elementRect = {
            top: rect.top,
            bottom: rect.bottom,
            height: rect.height,
          };
          // Only update target position if there's a significant change
          if (
            Math.abs(targetPosition.top - rect.top) > 2 ||
            Math.abs(targetPosition.left - rect.left) > 2 ||
            Math.abs(targetPosition.width - rect.width) > 2 ||
            Math.abs(targetPosition.height - rect.height) > 2
          ) {
            setTargetPosition({
              top: rect.top,
              left: rect.left,
              width: rect.width,
              height: rect.height,
            });
          }
        }

        const MARGIN = 60; // Additional margin to account for tooltip height
        const viewportHeight = win.innerHeight;

        // Helper function to only update if direction has changed
        const updateScrollDirectionIfChanged = (newDirection: 'up' | 'down' | null) => {
          if (lastScrollDirectionValueRef.current !== newDirection) {
            lastScrollDirectionValueRef.current = newDirection;
            lastScrollDirectionUpdateRef.current = now;
            setScrollDirection(newDirection);
          }
        };

        // Element is above viewport
        if (elementRect.top < MARGIN) {
          updateScrollDirectionIfChanged('up');
        }
        // Element is below viewport
        else if (elementRect.bottom > viewportHeight - MARGIN) {
          updateScrollDirectionIfChanged('down');
        }
        // Element is in viewport
        else {
          updateScrollDirectionIfChanged(null);
        }
      };

      // Initial check
      checkVisibility();

      // Check on scroll with throttling
      const throttledCheckVisibility = () => {
        requestAnimationFrame(checkVisibility);
      };

      if (typeof window === 'undefined') return;
      const win = getWindow();
      if (!win) return;

      win.addEventListener('scroll', throttledCheckVisibility, { passive: true });
      return () => win.removeEventListener('scroll', throttledCheckVisibility);
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isVisible, stepId]); // Removed targetPosition from dependencies

    const handleStopGuide = () => {
      // Start exit sequence
      setIsExiting(true);
      setCardVisible(false);

      // Fade out cursor
      setTimeout(() => {
        setCursorVisible(false);
        // Wait for fade out animation before calling onStopGuide
        setTimeout(() => {
          onStopGuide();
        }, 200); // Reduced from 300ms to 200ms for faster exit
      }, 200); // Reduced from 300ms to 200ms for faster cursor fade
    };

    // Handle skip to next step
    const handleSkip = () => {
      // Don't allow skipping if we're still waiting for an element
      if (isWaitingForElement.current) {
        logger.warn(`Cannot skip step while waiting for element with ID "${stepId}" to load`);
        return;
      }

      // Hide card first
      setCardVisible(false);

      // Show click effect
      handleCursorClick();

      // If this is the last step, start the exit sequence
      if (isLastStep) {
        setIsExiting(true);
        // Fade out cursor
        setTimeout(() => {
          setCursorVisible(false);
          // Wait for fade out animation before calling onWalkthroughEnd
          setTimeout(() => {
            onWalkthroughEnd();
          }, 200); // Reduced from 300ms to 200ms for faster exit
        }, 200); // Reduced from 300ms to 200ms for faster cursor fade
      }

      // Wait a moment before moving to next step (shorter delay)
      setTimeout(
        () => {
          onNextStep();
        },
        isLastStep ? 400 : 300, // Reduced from 600/400ms to 400/300ms for faster transitions
      );
    };

    const handleBack = () => {
      // Hide card first
      setCardVisible(false);

      // Reset cursor position state
      setCursorInPosition(false);

      // Wait for card to hide before moving cursor
      setTimeout(() => {
        onPreviousStep?.();
      }, 300);
    };

    // Add debug logging for showCloseButton
    useEffect(() => {}, [
      showCloseButton,
      stepId,
      type,
      currentStep,
      isVisible,
      cardVisible,
      cursorPosition,
    ]);

    if (!isVisible) {
      return null;
    }

    // For initial animation, use widget position as starting point
    let displayCursorPos = initialAnimation && !cursorInPosition ? widgetPosition : finalCursorPos;

    // Calculate card position based on final cursor position and direction
    const cardPosition = {
      top:
        cursorPosition === 'card-bottom'
          ? finalCursorPos.top - 140 - 10 // Reduced from -180 -25 to -140 -10
          : finalCursorPos.top + 25,
      left:
        pointerDirection === 'left'
          ? finalCursorPos.left + 25 // Card to the right of cursor
          : finalCursorPos.left - 320 - 5, // Card to the left of cursor (320px is card width)
    };

    // Adjust cursor position for cases where it would be cut off
    if (cursorPosition === 'card-bottom' && cursorInPosition) {
      displayCursorPos = {
        top:
          pointerDirection === 'left'
            ? cardPosition.top + 138 // Fine-tuned vertical distance
            : cardPosition.top + 116,
        left:
          pointerDirection === 'left'
            ? cardPosition.left - 23 // Slightly closer to the card on the left
            : cardPosition.left + 322, // Slightly closer to the card on the right
      };
    }

    const shouldShowSelfPacedButtons = type === 'self-paced';

    return (
      <>
        {/* Only show cursor when ready and visible */}
        {cursorReady && cursorVisible && (
          <div
            style={{
              opacity: isExiting ? 0 : 1,
              transition: 'opacity 0.3s ease-out',
              position: 'fixed',
              zIndex: 2147483647,
              pointerEvents: 'none',
            }}>
            <Cursor
              position={displayCursorPos}
              onClick={showClickEffect}
              size={20}
              initialAnimation={initialAnimation}
              isFlipped={cursorPosition === 'default' ? pointerDirection === 'right' : false}
              animate={!isExiting} // Disable animation during exit
              rotation={
                cursorPosition === 'card-bottom'
                  ? pointerDirection === 'left'
                    ? -90
                    : -180 // Point up from bottom of card
                  : undefined
              }
            />
          </div>
        )}

        {/* Main step card */}
        <Card
          className={styles.card}
          style={{
            position: 'fixed',
            top: `${cardPosition.top}px`,
            left: `${cardPosition.left}px`,
            transform: 'none',
            opacity: cardVisible ? 1 : 0,
            margin: 0,
            zIndex: 2147483647,
            maxWidth: '320px',
            width: '100%',
            boxShadow: '0 0 10px rgba(0, 0, 0, 0.1)',
            borderRadius: '16px',
            border: 'none',
            overflow: 'hidden',
            transition: 'opacity 0.3s ease-out',
            pointerEvents: cardVisible ? 'auto' : 'none',
          }}>
          <div
            style={{
              position: 'absolute',
              inset: 0,
              borderRadius: '16px',
              padding: '1px',
              background:
                'linear-gradient(137deg, var(--pointer-accent-color) 0%, var(--pointer-accent-color) 1%, var(--pointer-border-color) 15%, var(--pointer-border-color) 100%)',
              WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
              WebkitMaskComposite: 'xor',
              maskComposite: 'exclude',
              pointerEvents: 'none',
            }}
          />

          <div className={styles.header}>
            <p className={styles.instructions}>{instructions}</p>
            {(type === 'guided' || showCloseButton) && (
              <div className={styles.actions} style={{ display: 'flex', visibility: 'visible' }}>
                {type === 'guided' && (
                  <Tooltip content="Skip to next step">
                    <Button
                      variant="ghost"
                      size="icon"
                      className={styles.actionButton}
                      onClick={handleSkip}>
                      <ChevronsRight className={styles.actionIcon} />
                    </Button>
                  </Tooltip>
                )}
                {showCloseButton && (
                  <Tooltip content="Close guide">
                    <Button
                      variant="ghost"
                      size="icon"
                      className={styles.actionButton}
                      onClick={handleStopGuide}
                      style={{ display: showCloseButton ? 'flex' : 'none' }}>
                      <X className={styles.actionIcon} />
                    </Button>
                  </Tooltip>
                )}
              </div>
            )}
          </div>

          {/* Add navigation buttons for self-paced steps */}
          {shouldShowSelfPacedButtons && (
            <div
              style={{
                display: 'flex',
                justifyContent: 'flex-end',
                gap: '8px',
                padding: '0 16px 12px 16px',
                marginTop: '4px',
              }}>
              <Button
                variant="outline"
                size="xs"
                onClick={handleBack}
                disabled={currentStep <= 1}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px',
                }}>
                Back
              </Button>
              <Button
                size="xs"
                onClick={handleSkip}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px',
                  backgroundColor: 'var(--pointer-interactive-color)',
                }}>
                {isLastStep ? 'Finish' : 'Continue'}
              </Button>
            </div>
          )}
        </Card>

        {scrollDirection && (
          <ScrollIndicator direction={scrollDirection} className={styles.scrollIndicator} />
        )}
      </>
    );
  },
  (prevProps, nextProps) => {
    // Custom comparison function to prevent unnecessary re-renders
    return (
      prevProps.stepId === nextProps.stepId &&
      prevProps.currentStep === nextProps.currentStep &&
      prevProps.isLastStep === nextProps.isLastStep &&
      prevProps.instructions === nextProps.instructions &&
      prevProps.scrollDirection === nextProps.scrollDirection &&
      prevProps.showCloseButton === nextProps.showCloseButton &&
      prevProps.type === nextProps.type
    );
  },
);
