import React, { useState, useEffect, useRef } from 'react';

interface CursorProps {
  position: { top: number; left: number };
  animate?: boolean;
  size?: number;
  onClick?: boolean;
  isThinking?: boolean;
  initialAnimation?: boolean;
  isFlipped?: boolean;
  rotation?: number;
}

const CursorSVG = () => (
  <svg
    width="20"
    height="20"
    viewBox="0 0 160 160"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    data-pointer-cursor="true"
    style={{
      width: '100%',
      height: '100%',
    }}>
    <g clipPath="url(#clip0_2288_6692)">
      <path
        d="M12.9542 22.5158C10.474 10.7283 23.0497 1.51949 33.5384 7.44264L143.258 69.4032C152.114 74.4042 152.85 86.8806 144.645 92.8891L60.8705 154.234C52.665 160.243 40.9933 155.774 38.8992 145.822L12.9542 22.5158Z"
        fill="var(--pointer-cursor-color, var(--pointer-accent-color, #6366F1))"
      />
    </g>
    <defs>
      <clipPath id="clip0_2288_6692">
        <rect width="160" height="160" fill="white" />
      </clipPath>
    </defs>
  </svg>
);

export const Cursor: React.FC<CursorProps> = ({
  position,
  animate = true,
  size = 20,
  onClick = false,
  isThinking = false,
  initialAnimation = false,
  isFlipped = false,
  rotation,
}) => {
  const [showClickEffect, setShowClickEffect] = useState(false);
  const [prevPosition, setPrevPosition] = useState(position);
  const [isMoving, setIsMoving] = useState(false);
  const [hasInitialized, setHasInitialized] = useState(false);
  const cursorRef = useRef<HTMLDivElement>(null);
  const trailRef = useRef<HTMLDivElement>(null);

  // Initialize prevPosition with current position on mount
  useEffect(() => {
    setPrevPosition(position);

    // Mark as initialized after first render
    setTimeout(() => {
      setHasInitialized(true);
    }, 50);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Calculate movement distance for dynamic animation duration
  const calculateDistance = (
    pos1: { top: number; left: number },
    pos2: { top: number; left: number },
  ) => {
    return Math.sqrt(Math.pow(pos2.left - pos1.left, 2) + Math.pow(pos2.top - pos1.top, 2));
  };

  // Track position changes to detect movement
  useEffect(() => {
    // Only trigger animation if position actually changed and not the first render
    // Also don't show trail during initial animation
    if (
      hasInitialized &&
      !initialAnimation &&
      (prevPosition.top !== position.top || prevPosition.left !== position.left)
    ) {
      // Calculate distance to determine animation duration
      const distance = calculateDistance(prevPosition, position);
      const baseDuration = 300; // Base duration in ms
      const maxDuration = 900; // Max duration for long distances

      // Dynamic duration based on distance (longer for further movements)
      const duration = Math.min(
        maxDuration,
        baseDuration + distance * 1.5, // Scale factor for distance
      );

      // Start movement animation
      setIsMoving(true);

      // Store the previous position for trail effect
      const oldPosition = { ...prevPosition };

      // Update position state
      setPrevPosition(position);

      // Apply dynamic animation duration with a smoother easing curve (no bounce)
      if (cursorRef.current) {
        cursorRef.current.style.transition = `all ${duration / 1000}s cubic-bezier(0.4, 0.0, 0.2, 1)`;
      }

      // Position the trail at the previous position
      if (trailRef.current) {
        trailRef.current.style.top = `${oldPosition.top}px`;
        trailRef.current.style.left = `${oldPosition.left}px`;
      }

      // Reset moving state after animation completes
      const timer = setTimeout(() => {
        setIsMoving(false);

        // If onClick is true, show click effect after cursor stops moving
        if (onClick) {
          setShowClickEffect(true);

          // Hide click effect after animation
          const clickTimer = setTimeout(() => {
            setShowClickEffect(false);
          }, 600);

          return () => clearTimeout(clickTimer);
        }
      }, duration);

      return () => clearTimeout(timer);
    } else {
      // Just update the position state without showing trail
      setPrevPosition(position);
    }
  }, [position, prevPosition, onClick, hasInitialized, initialAnimation]);

  // Get transform style based on state
  const getTransformStyle = () => {
    // Use rotation instead of scaleX flip for a more natural look
    // -75 degrees gives a similar effect to flipping but looks more natural
    let flipTransform = isFlipped ? 'rotate(72deg)' : 'rotate(0deg)';

    // Apply custom rotation if provided
    if (rotation !== undefined) {
      flipTransform = `rotate(${rotation}deg)`;
    }

    if (isMoving) {
      return `${flipTransform} scale(1.05)`;
    } else if (isThinking) {
      return `${flipTransform} scale(1.02)`;
    } else {
      return `${flipTransform} scale(1)`;
    }
  };

  // Get filter style based on state
  const getFilterStyle = () => {
    // Add a subtle filter effect when flipped to further mask the rotation
    return isFlipped
      ? 'drop-shadow(0 1px 2px rgba(0, 0, 0, 0.3)) brightness(0.98)'
      : 'drop-shadow(0 1px 2px rgba(0, 0, 0, 0.3))';
  };

  return (
    <>
      {/* The cursor itself */}
      <div
        ref={cursorRef}
        style={{
          position: 'fixed',
          top: `${position.top}px`,
          left: `${position.left}px`,
          width: `${size}px`,
          height: `${size}px`,
          zIndex: 2147483647,
          pointerEvents: 'none',
          transition: animate ? 'all 0.3s cubic-bezier(0.4, 0.0, 0.2, 1)' : 'none',
          transform: getTransformStyle(),
          filter: getFilterStyle(),
          willChange: 'transform, top, left', // Optimize for animations
          animation: isThinking ? 'cursorPulse 2s ease-in-out infinite' : 'none',
          transformOrigin: rotation !== undefined ? 'center bottom' : 'center center', // Point from bottom when rotated
        }}>
        <CursorSVG />
      </div>

      {/* Cursor trail effect - only show when actually moving and not during initial animation */}
      {/* Make trail more subtle and less like a second cursor */}
      {isMoving && hasInitialized && prevPosition.top !== 0 && prevPosition.left !== 0 && (
        <div
          ref={trailRef}
          style={{
            position: 'fixed',
            top: `${prevPosition.top}px`,
            left: `${prevPosition.left}px`,
            width: `${size * 0.8}px`, // Smaller than the main cursor
            height: `${size * 0.8}px`, // Smaller than the main cursor
            zIndex: 2147483646,
            pointerEvents: 'none',
            opacity: 0.2, // More transparent
            animation: 'fadeOutTrail 0.4s ease-out forwards', // Faster fade out
            transform:
              rotation !== undefined
                ? `rotate(${rotation}deg)`
                : isFlipped
                  ? 'rotate(72deg)'
                  : 'rotate(0deg)',
            transformOrigin: rotation !== undefined ? 'center bottom' : 'center center', // Match main cursor
          }}>
          <CursorSVG />
        </div>
      )}

      {/* Click effect animation */}
      {showClickEffect && (
        <div
          style={{
            position: 'fixed',
            top: `${position.top}px`,
            left: `${position.left}px`,
            width: `${size * 1.5}px`,
            height: `${size * 1.5}px`,
            borderRadius: '50%',
            background: 'rgba(99, 102, 241, 0.4)',
            zIndex: 2147483646,
            pointerEvents: 'none',
            transform: 'translate(-50%, -50%)',
            animation: 'cursorClickEffect 0.6s ease-out forwards',
          }}
        />
      )}

      {/* Add styles for animations */}
      <style>
        {`
          @keyframes cursorClickEffect {
            0% {
              transform: translate(-50%, -50%) scale(0.5);
              opacity: 0.7;
            }
            100% {
              transform: translate(-50%, -50%) scale(1.5);
              opacity: 0;
            }
          }
          
          @keyframes fadeOutTrail {
            0% {
              opacity: 0.2;
              transform: ${rotation !== undefined ? `rotate(${rotation}deg)` : isFlipped ? 'rotate(72deg)' : 'rotate(0deg)'} scale(0.9);
              filter: blur(1px);
            }
            100% {
              opacity: 0;
              transform: ${rotation !== undefined ? `rotate(${rotation}deg)` : isFlipped ? 'rotate(72deg)' : 'rotate(0deg)'} scale(0.7);
              filter: blur(2px);
            }
          }
          
          @keyframes cursorPulse {
            0% {
              transform: ${isFlipped ? 'rotate(72deg)' : 'rotate(0deg)'} scale(1);
            }
            50% {
              transform: ${isFlipped ? 'rotate(72deg)' : 'rotate(0deg)'} scale(1.05);
            }
            100% {
              transform: ${isFlipped ? 'rotate(72deg)' : 'rotate(0deg)'} scale(1);
            }
          }
        `}
      </style>
    </>
  );
};
