import type { StorageConversation } from '../types';

export type ChatGroup = Record<string, StorageConversation[]>;

/**
 * Groups chat sessions by time period
 * @param sessions Array of chat sessions to group
 * @returns Object with chat sessions grouped by time period
 */
export const groupChatSessionsByDate = (sessions: StorageConversation[]): ChatGroup => {
  return sessions.reduce((acc, session) => {
    const date = new Date(session.createdAt);
    const now = new Date();
    const diffDays = Math.floor((now.getTime() - date.getTime()) / (1000 * 3600 * 24));

    let group;
    if (diffDays === 0) {
      group = 'Recent';
    } else if (diffDays === 1) {
      group = 'Yesterday';
    } else if (diffDays <= 7) {
      group = 'Previous 7 days';
    } else if (diffDays <= 30) {
      group = 'Previous 30 days';
    } else {
      group = date.toLocaleString('default', { month: 'long', year: 'numeric' });
    }

    if (!acc[group]) {
      acc[group] = [];
    }
    acc[group].push(session);
    return acc;
  }, {} as ChatGroup);
};

/**
 * Formats a date for display in the chat history
 * @param timestamp Unix timestamp in milliseconds
 * @returns Formatted date string
 */
export const formatDate = (timestamp: number): string => {
  return new Date(timestamp).toLocaleDateString();
};

/**
 * Gets a relative time string for a timestamp
 * @param timestamp Unix timestamp in milliseconds
 * @returns Relative time string (e.g., "Today", "Yesterday", "2 days ago")
 */
export const getRelativeTimeString = (timestamp: number): string => {
  const date = new Date(timestamp);
  const now = new Date();
  const diffDays = Math.floor((now.getTime() - date.getTime()) / (1000 * 3600 * 24));

  if (diffDays === 0) return 'Today';
  if (diffDays === 1) return 'Yesterday';
  if (diffDays < 7) return `${diffDays} days ago`;
  if (diffDays < 30) return `${Math.floor(diffDays / 7)} weeks ago`;
  if (diffDays < 365) return `${Math.floor(diffDays / 30)} months ago`;
  return `${Math.floor(diffDays / 365)} years ago`;
};
