const { React, ReactDOM } = window;

import type { PointerConfig } from './init';

window.POINTER_INIT = async (config: PointerConfig, container: HTMLElement) => {
  const { PointerProvider } = await import('../contexts/PointerContext');
  const { ThemeProvider } = await import('../contexts/ThemeContext');

  // Create a wrapper component that will be rendered
  const App = () => {
    return React.createElement(ThemeProvider, {
      customization: {},
      children: React.createElement(PointerProvider, {
        ...config,
        children: null,
      }),
    });
  };

  // Create root and render using React 18 API
  // @ts-expect-error - ReactDOM.createRoot is correctly exposed on the UMD build
  const root = ReactDOM.createRoot(container);
  root.render(React.createElement(App));
};
