import * as React from 'react';
import { groupChatSessionsByDate } from '../../../utils/dateUtils';
import { SessionList } from './SessionList';
import { EmptyState } from '../EmptyState';
import type { StorageConversation } from '../../../types';
import styles from './SessionGroups.module.css';

interface SessionGroupsProps {
  sessions: StorageConversation[];
  editingSessionId: string | null;
  editingSessionTitle: string;
  hoveredSessionId: string | null;
  onSessionClick: (sessionId: string) => void;
  onEditClick: (sessionId: string, title: string) => void;
  onDeleteClick: (sessionId: string) => void;
  onTitleChange: (value: string) => void;
  onTitleUpdate: (sessionId: string) => void;
  onMouseEnter: (sessionId: string) => void;
  onMouseLeave: () => void;
}

export const SessionGroups: React.FC<SessionGroupsProps> = ({
  sessions,
  editingSessionId,
  editingSessionTitle,
  hoveredSessionId,
  onSessionClick,
  onEditClick,
  onDeleteClick,
  onTitleChange,
  onTitleUpdate,
  onMouseEnter,
  onMouseLeave,
}) => {
  const groupedSessions = groupChatSessionsByDate(sessions);

  if (Object.keys(groupedSessions).length === 0) {
    return <EmptyState />;
  }

  return (
    <div className={styles.container}>
      {Object.entries(groupedSessions).map(([group, groupSessions]) => (
        <SessionList
          key={group}
          groupTitle={group}
          sessions={groupSessions}
          editingSessionId={editingSessionId}
          editingSessionTitle={editingSessionTitle}
          hoveredSessionId={hoveredSessionId}
          onSessionClick={onSessionClick}
          onEditClick={onEditClick}
          onDeleteClick={onDeleteClick}
          onTitleChange={onTitleChange}
          onTitleUpdate={onTitleUpdate}
          onMouseEnter={onMouseEnter}
          onMouseLeave={onMouseLeave}
        />
      ))}
    </div>
  );
};
