/**
 * Custom error types for better error handling
 */
export class PointerError extends Error {
  constructor(
    message: string,
    public code: string,
  ) {
    super(message);
    this.name = 'PointerError';
  }
}

export class ServerDiscoveryError extends PointerError {
  constructor(message: string) {
    super(message, 'SERVER_DISCOVERY_ERROR');
  }
}

export class ServerConnectionError extends PointerError {
  constructor(message: string) {
    super(message, 'SERVER_CONNECTION_ERROR');
  }
}

export class ProjectIdError extends PointerError {
  constructor(message: string) {
    super(message, 'PROJECT_ID_ERROR');
  }
}

export class ServerInitializationError extends PointerError {
  constructor(message: string) {
    super(message, 'SERVER_INIT_ERROR');
  }
}

export const ERROR_MESSAGES = {
  SERVER_NOT_FOUND: 'Could not find Pointer server. Make sure it is running and accessible.',
  SERVER_CONNECTION_FAILED:
    'Failed to connect to Pointer server. Please check your network connection.',
  INVALID_PROJECT_ID: 'Invalid project ID. Please check your project ID and try again.',
  SERVER_ALREADY_RUNNING: 'Pointer server is already running.',
  PORT_IN_USE: 'Preferred port is already in use.',
  INITIALIZATION_FAILED: 'Failed to initialize Pointer server.',
  API_REQUEST_FAILED: 'Failed to make API request.',
  STREAM_CONNECTION_FAILED: 'Failed to establish stream connection.',
} as const;
