import * as React from 'react';
import { HeaderActions } from './HeaderActions';
import { Button } from '../../base/Button';
import styles from './ChatHeader.module.css';
import pointerWordmarkLight from '../../../assets/pointer-wordmark-light.svg';
import { ChevronLeft } from '../../icons';
import { useTheme } from '../../../contexts/ThemeContext';

interface ChatHeaderProps {
  view: 'main' | 'history';
  onBack?: () => void;
  onNewChat: () => void;
  onHistoryClick: () => void;
  onClose: () => void;
  conversationTitle?: string;
  isGeneratingTitle?: boolean;
  hasMessages?: boolean;
  isMaximized?: boolean;
  onToggleSize?: () => void;
}

export const ChatHeader: React.FC<ChatHeaderProps> = ({
  view,
  onBack,
  onNewChat,
  onHistoryClick,
  onClose,
  conversationTitle,
  isGeneratingTitle,
  hasMessages,
  isMaximized,
  onToggleSize,
}) => {
  const { content, branding } = useTheme();
  const [showDefault, setShowDefault] = React.useState(true);
  const [showConversation, setShowConversation] = React.useState(false);

  React.useEffect(() => {
    if (conversationTitle || hasMessages) {
      setShowDefault(false);
      setTimeout(() => {
        setShowConversation(true);
      }, 200);
    } else {
      setShowConversation(false);
      setShowDefault(true);
    }
  }, [conversationTitle, hasMessages]);

  return (
    <div className={styles.header}>
      {/* Persistent Header Actions */}
      <div className={styles.actions}>
        <HeaderActions
          onNewChat={onNewChat}
          onHistoryClick={onHistoryClick}
          onClose={onClose}
          isMaximized={isMaximized || false}
          onToggleSize={onToggleSize || (() => {})}
        />
      </div>

      {/* History View Content */}
      {view === 'history' && (
        <div className={styles.titleContainer}>
          {onBack && (
            <Button variant="ghost" size="icon" onClick={onBack} className={styles.backButton}>
              <ChevronLeft className={styles.backIcon} />
            </Button>
          )}
          <h4 className={styles.conversationTitle}>All chats</h4>
        </div>
      )}

      {/* Default View Content */}
      {view === 'main' && showDefault && (
        <>
          <div className={styles.defaultView}>
            <div className={styles.headerLeft}>
              <img
                src={
                  typeof branding.logomark === 'string'
                    ? branding.logomark
                    : branding.logomark?.light || pointerWordmarkLight
                }
                alt="Logo"
                className={styles.logo}
              />
            </div>
          </div>
          <div className={styles.welcomeContainer}>
            <h1 className={styles.welcomeHeading}>{content.welcomeMessage}</h1>
            <h2 className={styles.welcomeSubheading}>{content.welcomeSubheading}</h2>
          </div>
        </>
      )}

      {/* Conversation View Content */}
      {view === 'main' && showConversation && (
        <div className={styles.conversationView}>
          <h4 className={styles.conversationTitle}>
            {conversationTitle || (isGeneratingTitle ? 'New conversation' : 'Chat')}
          </h4>
        </div>
      )}
    </div>
  );
};
