import type { SimpleGuide, StorageMessage, DisplayMessage, Step } from '../types';

/**
 * Formats a message for display in the chat
 * @param msg The raw message from storage
 * @param guides Available guides for reference
 * @returns Formatted message for display
 */
export const formatMessage = (msg: StorageMessage, guides?: SimpleGuide[]): DisplayMessage => {
  if (msg.role === 'user') {
    return { user: msg.content };
  } else {
    let guide: SimpleGuide | undefined;
    let displayText = msg.content;

    // First try to parse guide data from content
    try {
      const data = JSON.parse(msg.content);
      if (data.name && data.steps) {
        guide = {
          id: data.name,
          name: data.name,
          steps: data.steps.map((step: Step) => ({
            id: step.id,
            position: step.position,
            instructions: step.instructions,
            page: step.page,
            action: step.action,
          })),
        };
        displayText = data.text;
      }
    } catch {
      // If not JSON guide data and we have a relatedGuideId, try to find it in guides
      if (msg.relatedGuideId && guides) {
        guide = guides.find(g => g.id === msg.relatedGuideId);
        // If guide not found in guides context but we have a relatedGuideId,
        // create a minimal guide object to show the button
        if (!guide && msg.showGuideButton) {
          guide = {
            id: msg.relatedGuideId,
            name: msg.relatedGuideId,
            steps: [],
          };
        }
      }
    }

    return {
      assistant: displayText,
      showGuideButton: msg.showGuideButton,
      ...(guide ? { guide } : {}),
      ...(msg.showFeedback
        ? {
            showFeedback: false, // switch to true once fixed
            feedbackGiven: msg.feedbackGiven,
          }
        : {}),
    };
  }
};

/**
 * Creates a new user message
 * @param content The message content
 * @returns A new Message object
 */
export const createUserMessage = (content: string): StorageMessage => ({
  role: 'user',
  content,
  timestamp: Date.now(),
});

/**
 * Creates a new assistant message
 * @param content The message content
 * @param options Additional message options
 * @returns A new Message object
 */
export const createAssistantMessage = (
  content: string,
  options?: {
    relatedGuideId?: string;
    showGuideButton?: boolean;
    showFeedback?: boolean;
  },
): StorageMessage => ({
  role: 'assistant',
  content,
  timestamp: Date.now(),
  ...options,
});
