import * as React from 'react';
import { Mail, BookOpen, Users, MessagesSquare } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { Button } from '../../base/Button';
import styles from './LinkButtons.module.css';
import { getWindow } from '@/sdk';

interface LinkButtonsProps {
  link1Text?: string;
  link1Icon?: string;
  link1Url?: string;
  link2Text?: string;
  link2Icon?: string;
  link2Url?: string;
  link3Text?: string;
  link3Icon?: string;
  link3Url?: string;
  link4Text?: string;
  link4Icon?: string;
  link4Url?: string;
}

const DEFAULT_LINKS = [
  {
    text: 'Contact',
    icon: 'mail',
    url: 'mailto:team@pointer.so',
  },
  {
    text: 'Docs',
    icon: 'book',
    url: 'https://docs.pointer.so',
  },
  {
    text: 'Community',
    icon: 'users',
    url: 'https://dub.sh/pointer-community',
  },
  {
    text: 'Demo',
    icon: 'messages',
    url: 'https://cal.com/nealchopra/chat',
  },
];

const ICONS: Record<string, LucideIcon> = {
  mail: Mail,
  book: BookOpen,
  users: Users,
  messages: MessagesSquare,
};

export const LinkButtons: React.FC<LinkButtonsProps> = ({
  link1Text,
  link1Icon,
  link1Url,
  link2Text,
  link2Icon,
  link2Url,
  link3Text,
  link3Icon,
  link3Url,
  link4Text,
  link4Icon,
  link4Url,
}) => {
  const links = [
    {
      text: link1Text || DEFAULT_LINKS[0].text,
      icon: link1Icon || DEFAULT_LINKS[0].icon,
      url: link1Url || DEFAULT_LINKS[0].url,
    },
    {
      text: link2Text || DEFAULT_LINKS[1].text,
      icon: link2Icon || DEFAULT_LINKS[1].icon,
      url: link2Url || DEFAULT_LINKS[1].url,
    },
    {
      text: link3Text || DEFAULT_LINKS[2].text,
      icon: link3Icon || DEFAULT_LINKS[2].icon,
      url: link3Url || DEFAULT_LINKS[2].url,
    },
    {
      text: link4Text || DEFAULT_LINKS[3].text,
      icon: link4Icon || DEFAULT_LINKS[3].icon,
      url: link4Url || DEFAULT_LINKS[3].url,
    },
  ];

  return (
    <div className={styles.container}>
      <h3 className={styles.title}>Get in touch</h3>
      <div className={styles.buttonGrid}>
        {links.map((link, index) => {
          const Icon = ICONS[link.icon.toLowerCase()];
          return (
            <Button
              key={index}
              variant="outline"
              size="sm"
              className={styles.linkButton}
              onClick={() => {
                if (typeof window === 'undefined') return;
                const win = getWindow();
                if (!win) return;
                win.open(link.url, '_blank');
              }}>
              <span className={styles.iconWrapper}>
                {Icon && <Icon size={14} strokeWidth={2} />}
              </span>
              <span className={styles.text}>{link.text}</span>
            </Button>
          );
        })}
      </div>
    </div>
  );
};
