import * as React from 'react';
import { ArrowUpCircle } from '../../../components/icons';
import { Button } from '../../../components/base/Button';
import { Input } from '../../../components/base/Input';
import styles from './ChatInput.module.css';
import { useTheme } from '../../../contexts/ThemeContext';

interface ChatInputProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: (e: React.FormEvent) => void;
  inputRef: React.RefObject<HTMLInputElement>;
}

export const ChatInput: React.FC<ChatInputProps> = ({ value, onChange, onSubmit, inputRef }) => {
  const { content } = useTheme();

  return (
    <form
      onSubmit={e => {
        onSubmit(e);
        // Unfocus the input after submission
        inputRef.current?.blur();
      }}
      className={styles.container}>
      <Input
        ref={inputRef}
        value={value}
        onChange={e => onChange(e.target.value)}
        placeholder={content?.inputPlaceholder}
        fullWidth
        endAdornment={
          <Button type="submit" size="icon" variant="ghost" className={styles.submitButton}>
            <ArrowUpCircle className={`${styles.icon} ${value.trim() ? styles.iconActive : ''}`} />
            <span className={styles.srOnly}>Send message</span>
          </Button>
        }
      />
    </form>
  );
};
