'use client';

import { useState, useEffect, useRef, useContext, useCallback } from 'react';
import { PointerContext } from '../contexts/PointerContext';
import { ThemeContext, useThemeMode } from '../contexts/ThemeContext';
import type { SimpleGuide, StorageConversation } from '../types';
import { storage } from '../utils/storage';
import { Button } from './base/Button';
import { Popover } from './base/Popover';
import { Sparkles, ChevronDown, HelpCircle, MessageCircle, Zap } from './icons';
import { formatMessage } from '../utils/messageUtils';
import { getOrCreateUserAvatar } from '../utils/avatarUtils';
import pointerLogo from '../assets/pointer-bg.png';
import { ChatHeader } from './widget/header/ChatHeader';
import { SessionGroups } from './widget/sessions/SessionGroups';
import { ChatMessages } from './widget/messages/ChatMessages';
import { ChatInput } from './widget/messages/ChatInput';
import { conversationManager } from '../utils/conversationManager';
import { apiService } from '../services/api';
import { getStorage, getDocument } from '../index';
import styles from './widget/Widget.module.css';
import { PoweredByPointer } from './widget/header/PoweredByPointer';
import { LinkButtons } from './widget/links/LinkButtons';
import { guideSocketClient } from '../services/websocket/GuideSocketClient';

// Import the Pointer icon component
import { Pointer } from './icons/Pointer';

import { logger } from '../utils/logger';
const TRIGGER_ICONS = {
  sparkles: Sparkles,
  help: HelpCircle,
  message: MessageCircle,
  zap: Zap,
  pointer: Pointer,
};

export const Widget: React.FC = () => {
  const pointerContext = useContext(PointerContext);
  if (!pointerContext) return null;

  const {
    isChatOpen,
    setIsChatOpen,
    guides,
    defaultResponse,
    startGuide,
    chatHistory,
    setChatHistory,
    setCurrentStep,
    setSteps,
    pageMappings,
    getCurrentMappings,
    triggerId,
  } = pointerContext;

  const { branding, content } = useContext(ThemeContext);
  const { mode } = useThemeMode();

  // Get the appropriate icon component
  const TriggerIcon = TRIGGER_ICONS[branding.triggerIcon || 'pointer'];

  const [userInput, setUserInput] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);
  const [feedbackState, setFeedbackState] = useState<Record<number, 'yes' | 'no' | null>>({});
  const [view, setView] = useState<'main' | 'history'>('main');
  const [chatSessions, setChatSessions] = useState<StorageConversation[]>([]);
  const [guideIds, setGuideIds] = useState<Record<number, string>>({});
  const [currentConversationId, setCurrentConversationId] = useState<string | null>(null);
  const [hoveredSessionId, setHoveredSessionId] = useState<string | null>(null);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [editingSessionTitle, setEditingSessionTitle] = useState('');
  const [conversationTitle, setConversationTitle] = useState<string | null>(null);
  const [isGeneratingTitle, setIsGeneratingTitle] = useState(false);
  const titlePollingRef = useRef<NodeJS.Timeout | null>(null);
  const [waitingForFeedback, setWaitingForFeedback] = useState<number | null>(null);
  const [isMaximized, setIsMaximized] = useState(false);

  const scrollToBottom = useCallback(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.style.scrollBehavior = 'smooth';
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
      // Reset scroll behavior after animation
      setTimeout(() => {
        if (chatContainerRef.current) {
          chatContainerRef.current.style.scrollBehavior = 'auto';
        }
      }, 300);
    }
  }, []);

  const scrollToTop = useCallback(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = 0;
    }
  }, []);

  useEffect(() => {
    if (chatHistory.length === 0) {
      // Scenario 1: No messages, scroll to top
      scrollToTop();
    } else if (chatHistory.length > 0) {
      const lastMessage = chatHistory[chatHistory.length - 1];
      if (lastMessage?.showFeedback) {
        // Scenario 3: Feedback message, scroll to bottom with delay
        setTimeout(scrollToBottom, 100);
      } else {
        // Scenario 2: New message added, scroll to bottom
        scrollToBottom();
      }
    }
  }, [chatHistory, scrollToBottom, scrollToTop]);

  useEffect(() => {
    if (isChatOpen && chatHistory.length > 0) {
      scrollToBottom();
    }
  }, [isChatOpen, chatHistory, scrollToBottom]);

  useEffect(() => {
    const sessions = storage.getAllConversations();
    setChatSessions(sessions);

    // Clear active conversation on page load
    storage.clearActiveConversation();
    setCurrentConversationId(null);
  }, [guides]);

  const formatTitle = (title: string) => {
    // Remove all quotes (single and double) from anywhere in the title
    const unquoted = title.replace(/['"]/g, '');
    // Make it sentence case (first letter capitalized, rest lowercase)
    return unquoted.charAt(0).toUpperCase() + unquoted.slice(1).toLowerCase();
  };

  const pollForTitle = useCallback(async (conversationId: string) => {
    try {
      const conversation = await apiService.getConversation(conversationId);

      // If we got a title from the API, update storage
      if (conversation.title) {
        const formattedTitle = formatTitle(conversation.title);
        storage.updateConversationTitle(conversationId, formattedTitle);
        setConversationTitle(formattedTitle);
        setIsGeneratingTitle(false);
        if (titlePollingRef.current) {
          clearInterval(titlePollingRef.current);
          titlePollingRef.current = null;
        }
      }
    } catch (error) {
      logger.error('Failed to fetch conversation title:', error);
    }
  }, []);

  const handleUserInput = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim()) return;

    const userMessage = userInput.trim();

    // Check if this message is feedback
    if (waitingForFeedback !== null) {
      // Store the feedback message
      if (currentConversationId) {
        storage.addMessage(currentConversationId, {
          role: 'user',
          content: userMessage,
          isFeedback: true,
        });

        // First add just the user message
        setChatHistory(prevHistory => [...prevHistory, { user: userMessage }]);

        // Get the guide ID for the feedback message
        const guideMessageIndex = chatHistory.findIndex(
          (msg, i) => i <= waitingForFeedback && msg.guide,
        );
        const guideId = guideIds[guideMessageIndex];

        // If there's a guide ID, submit the feedback with the comment
        if (guideId) {
          try {
            await apiService.submitGuideFeedback(guideId, false, userMessage);
          } catch (error) {
            logger.error('Failed to submit guide feedback:', error);
          }
        }

        // After the user message is rendered, add loading dots in a separate update
        setTimeout(() => {
          setChatHistory(prevHistory => [...prevHistory, { assistant: '', isStreaming: true }]);

          // Scroll to bottom after loading dots are added
          requestAnimationFrame(() => {
            setTimeout(scrollToBottom, 50);
          });

          // After a brief delay, show the thank you message
          setTimeout(() => {
            // Add a final thank you message
            const finalMessage = {
              role: 'assistant' as const,
              content: 'Thanks for your feedback — it helps me improve!',
            };
            storage.addMessage(currentConversationId, finalMessage);

            setChatHistory(prevHistory => {
              const newHistory = [...prevHistory];
              const lastIndex = newHistory.length - 1;
              if (lastIndex >= 0) {
                newHistory[lastIndex] = { assistant: finalMessage.content, isStreaming: true };
              }
              return newHistory;
            });

            // Remove streaming after delay
            setTimeout(() => {
              setChatHistory(prevHistory => {
                const newHistory = [...prevHistory];
                const lastIndex = newHistory.length - 1;
                if (lastIndex >= 0) {
                  newHistory[lastIndex] = { ...newHistory[lastIndex], isStreaming: false };
                }
                return newHistory;
              });
            }, 1000);
          }, 500);
        }, 100);

        // Reset feedback waiting state
        setWaitingForFeedback(null);
        setUserInput('');
        return;
      }
    }

    let conversationId = currentConversationId;

    if (!conversationId) {
      try {
        conversationId = await conversationManager.createConversation();
        if (conversationId) {
          setCurrentConversationId(conversationId);
          setChatSessions(storage.getAllConversations());
          // Start polling for title after first message
          setIsGeneratingTitle(true);
          const id = conversationId; // Create a stable reference for the closure
          titlePollingRef.current = setInterval(() => pollForTitle(id), 2000);
        }
      } catch (error) {
        logger.error('Failed to create conversation:', error);
        return;
      }
    }

    setChatHistory(prevHistory => [
      ...prevHistory,
      { user: userMessage },
      { assistant: '', isStreaming: true },
    ]);
    setUserInput('');

    try {
      let streamedText = '';
      let isGuideResponse = false;

      await conversationManager.handleAssistantResponse(
        userMessage,
        conversationId,
        pageMappings,
        (chunk: string) => {
          // Clean any data: prefix first
          const cleanChunk = chunk.replace(/^data:\s*/, '');

          // Handle guide event start
          if (cleanChunk.startsWith('event: guide')) {
            isGuideResponse = true;
            return;
          }

          // Try to parse as JSON first
          try {
            const jsonData = JSON.parse(cleanChunk);
            // Only treat it as JSON if it's an object with a type property
            if (typeof jsonData === 'object' && jsonData !== null && 'type' in jsonData) {
              if (jsonData.type === 'message') {
                setChatHistory(prevHistory => [
                  ...prevHistory.slice(0, -1),
                  {
                    assistant: jsonData.content,
                    isStreaming: true,
                    showGuideButton: jsonData.showGuideButton,
                    isGuideLoading: jsonData.isGuideLoading,
                  },
                ]);
                return;
              }
            } else {
              // Add space if we're transitioning from text to number or from colon to any character
              if (
                (!streamedText.endsWith(' ') &&
                  !cleanChunk.startsWith(' ') &&
                  /[a-zA-Z]$/.test(streamedText) &&
                  /^[0-9]/.test(cleanChunk)) ||
                (streamedText.endsWith(':') && !cleanChunk.startsWith(' '))
              ) {
                streamedText += ' ';
              }

              streamedText += cleanChunk;
              setChatHistory(prevHistory => [
                ...prevHistory.slice(0, -1),
                {
                  assistant: streamedText,
                  isStreaming: true,
                  showFeedback: isGuideResponse,
                },
              ]);
            }
          } catch (e) {
            // Not JSON, handle as plain text
            if (isGuideResponse) {
              // If it's a guide response but not JSON, it might be the guide data
              if (cleanChunk.trim().startsWith('{')) {
                try {
                  const parsedGuideData = JSON.parse(cleanChunk);
                  if (
                    parsedGuideData &&
                    'id' in parsedGuideData &&
                    'text' in parsedGuideData &&
                    'name' in parsedGuideData &&
                    'steps' in parsedGuideData
                  ) {
                    setChatHistory(prevHistory => {
                      const messageIndex = prevHistory.length - 1;
                      setTimeout(() => {
                        setGuideIds(prev => ({
                          ...prev,
                          [messageIndex]: parsedGuideData.id,
                        }));
                      }, 0);

                      return [
                        ...prevHistory.slice(0, -1),
                        {
                          assistant: parsedGuideData.text,
                          guide: {
                            id: parsedGuideData.name,
                            name: parsedGuideData.name,
                            steps: parsedGuideData.steps,
                          },
                          showGuideButton: true,
                          isGuideLoading: false,
                        },
                      ];
                    });
                  }
                } catch (e) {
                  logger.debug('Failed to parse guide data:', e);
                }
              }
            } else {
              // Add space if we're transitioning from text to number or from colon to any character
              if (
                (!streamedText.endsWith(' ') &&
                  !cleanChunk.startsWith(' ') &&
                  /[a-zA-Z]$/.test(streamedText) &&
                  /^[0-9]/.test(cleanChunk)) ||
                (streamedText.endsWith(':') && !cleanChunk.startsWith(' '))
              ) {
                streamedText += ' ';
              }

              streamedText += cleanChunk;

              setChatHistory(prevHistory => {
                const newHistory = [
                  ...prevHistory.slice(0, -1),
                  {
                    assistant: streamedText,
                    isStreaming: true,
                    showFeedback: isGuideResponse,
                  },
                ];
                return newHistory;
              });
            }
          }
        },
      );
    } catch (error) {
      logger.error('Failed to get assistant response:', error);
      setChatHistory(prevHistory => {
        return [...prevHistory.slice(0, -1), { assistant: defaultResponse, isStreaming: true }];
      });

      // After a short delay, remove the streaming state
      setTimeout(() => {
        setChatHistory(prevHistory => {
          const newHistory = [...prevHistory];
          const lastIndex = newHistory.length - 1;
          if (lastIndex >= 0) {
            newHistory[lastIndex] = { ...newHistory[lastIndex], isStreaming: false };
          }
          return newHistory;
        });
      }, 1000);
    }

    if (inputRef.current) inputRef.current.focus();
  };

  const canStartGuide = useCallback((_guide: SimpleGuide | null): boolean => {
    return true; // Always allow starting the guide since we don't support multi-step guides YET (will change soon)
  }, []);

  const handleStartGuide = (guide: SimpleGuide | null) => {
    if (guide) {
      if (canStartGuide(guide)) {
        if (guide.resumeData) {
          setCurrentStep(guide.resumeData.currentStep);
          setSteps(guide.resumeData.steps);
          getStorage().removeItem('pointer_walkthrough_state');
        }
        startGuide(guide);
      } else {
        setChatHistory(prevHistory => [
          ...prevHistory,
          { assistant: 'This guide cannot be started from the current page.' },
        ]);
      }
    }
  };

  const handleItemClick = (text: string) => {
    setUserInput(text);
    if (inputRef.current) {
      inputRef.current.focus();
    }
  };

  const handleHistoryClick = () => {
    setView('history');
  };

  const handleBackToMain = () => {
    setView('main');
  };

  const handleChatSessionClick = (sessionId: string) => {
    const conversation = storage.getConversation(sessionId);
    if (conversation) {
      setCurrentConversationId(sessionId);
      if (conversation.title) {
        const formattedTitle = formatTitle(conversation.title);
        setConversationTitle(formattedTitle);
        // Also update storage with formatted title if it's different
        if (formattedTitle !== conversation.title) {
          storage.updateConversationTitle(sessionId, formattedTitle);
        }
      } else {
        setConversationTitle(null);
      }
      setIsGeneratingTitle(false);

      // Initialize feedback state from stored messages
      const newFeedbackState: Record<number, 'yes' | 'no' | null> = {};
      conversation.messages.forEach((msg, index) => {
        if (msg.feedbackGiven) {
          newFeedbackState[index] = msg.feedbackGiven;
        }
      });
      setFeedbackState(newFeedbackState);

      // Format messages using messageUtils.formatMessage
      const formattedMessages = conversation.messages.map(msg => formatMessage(msg, guides));
      setChatHistory(formattedMessages);
      storage.setActiveConversation(sessionId);
      setView('main');
    }
  };

  const handleEditSession = (sessionId: string, title: string) => {
    setEditingSessionId(sessionId);
    setEditingSessionTitle(title);
  };

  const handleUpdateSession = (sessionId: string) => {
    storage.updateConversationTitle(sessionId, editingSessionTitle);
    setChatSessions(storage.getAllConversations());
    setEditingSessionId(null);
  };

  const handleDeleteClick = (sessionId: string) => {
    storage.deleteConversation(sessionId);
    setChatSessions(storage.getAllConversations());
    if (sessionId === currentConversationId) {
      handleNewChatSession();
    }
  };

  // Clean up polling on unmount
  useEffect(() => {
    return () => {
      if (titlePollingRef.current) {
        clearInterval(titlePollingRef.current);
      }
    };
  }, []);

  // Reset title state on new chat
  const handleNewChatSession = useCallback(() => {
    getStorage().removeItem('pointer_walkthrough_state');
    setCurrentConversationId(null);
    setUserInput('');
    setChatHistory([]);
    setFeedbackState({});
    setView('main');
    setConversationTitle(null);
    setIsGeneratingTitle(false);
    if (titlePollingRef.current) {
      clearInterval(titlePollingRef.current);
      titlePollingRef.current = null;
    }
    if (inputRef.current) {
      inputRef.current.focus();
    }
  }, [setChatHistory]);

  const handleFeedback = useCallback(
    async (index: number, feedback: 'yes' | 'no') => {
      if (!currentConversationId) return;

      // Find the actual guide message index
      const guideMessageIndex = chatHistory.findIndex((msg, i) => i <= index && msg.guide);

      // Only proceed if feedback hasn't been given yet
      if (feedbackState[index] === undefined || feedbackState[index] === null) {
        // Update local state
        setFeedbackState(prev => ({ ...prev, [index]: feedback }));

        // Update the feedback in storage
        storage.updateMessageFeedback(currentConversationId, index, feedback);

        // Submit guide feedback if this was a guide message
        const guideId = guideIds[guideMessageIndex]; // Use the guide message index instead

        if (guideId) {
          try {
            // For positive feedback, submit immediately
            if (feedback === 'yes') {
              await apiService.submitGuideFeedback(guideId, true);
            }
            // For negative feedback, we'll wait for the comment
          } catch (error) {
            logger.error('Failed to submit guide feedback:', error);
          }
        }

        // First update the feedback state in the existing message
        setChatHistory(prevHistory => {
          const newHistory = [...prevHistory];
          if (newHistory[index]) {
            const existingMessage = newHistory[index];
            newHistory[index] = formatMessage(
              {
                role: 'assistant',
                content: existingMessage.assistant || '',
                showFeedback: false, // switch to true once fixed
                feedbackGiven: feedback,
                timestamp: Date.now(),
              },
              guides,
            );
          }
          return newHistory;
        });

        // After a brief delay, add the loading dots
        setTimeout(() => {
          setChatHistory(prevHistory => [...prevHistory, { assistant: '', isStreaming: true }]);

          // Scroll to bottom after loading dots are added
          requestAnimationFrame(() => {
            setTimeout(scrollToBottom, 50);
          });

          // After a brief delay, show the actual message
          setTimeout(() => {
            const feedbackMessage = {
              role: 'assistant' as const,
              content:
                feedback === 'yes'
                  ? `I'm glad I could help! Let me know if you have any other questions.`
                  : `I'm sorry this wasn't helpful. How can I improve?`,
            };

            storage.addMessage(currentConversationId, feedbackMessage);

            setChatHistory(prevHistory => {
              const newHistory = [...prevHistory];
              const lastIndex = newHistory.length - 1;
              if (lastIndex >= 0) {
                newHistory[lastIndex] = { assistant: feedbackMessage.content, isStreaming: true };
              }
              return newHistory;
            });

            // If feedback is negative, set state to wait for detailed feedback
            if (feedback === 'no') {
              setWaitingForFeedback(index);
            }

            // After a short delay, remove the streaming state
            setTimeout(() => {
              setChatHistory(prevHistory => {
                const newHistory = [...prevHistory];
                const lastIndex = newHistory.length - 1;
                if (lastIndex >= 0) {
                  newHistory[lastIndex] = { ...newHistory[lastIndex], isStreaming: false };
                }
                return newHistory;
              });
            }, 1000);
          }, 500);
        }, 100);
      }
    },
    [
      currentConversationId,
      chatHistory,
      feedbackState,
      guideIds,
      guides,
      setChatHistory,
      scrollToBottom,
    ],
  );

  // Helper function to get the correct theme value
  const getThemeValue = (
    value: string | { light: string; dark: string } | undefined,
  ): string | undefined => {
    if (!value) return undefined;
    if (typeof value === 'string') return value;
    return value[mode];
  };

  // Create trigger button style based on theme
  const triggerButtonStyle = {
    background: getThemeValue(branding.triggerBackground),
    border: getThemeValue(branding.triggerBorder),
  };

  const triggerIconStyle = {
    color: getThemeValue(branding.triggerIconColor),
  };

  // Add effect to handle UI element enrichment when widget opens
  useEffect(() => {
    if (isChatOpen) {
      const enrichUIElements = async () => {
        try {
          const currentMappings = getCurrentMappings();
          if (currentMappings.length === 0) return;

          // Convert mappings to UI elements format
          const elements = currentMappings.map(mapping => ({
            elementId: mapping.trackerId, // Use trackerId as the unique identifier
            trackerId: mapping.trackerId,
            routeId: mapping.routeId,
            identifiers: {
              selector: mapping.identifiers.selector || '',
              structuralPath: mapping.identifiers.structuralPath || '',
            },
            metadata: {
              elementType: mapping.metadata.elementType,
              pageContext: mapping.routeId,
              nearbyText: mapping.metadata.nearbyText || '',
            },
          }));

          // Send elements for enrichment
          await guideSocketClient.enrichUIElements(elements);
        } catch (error) {
          logger.error('Failed to enrich UI elements:', error);
        }
      };

      enrichUIElements();
    }
  }, [isChatOpen, getCurrentMappings]);

  useEffect(() => {
    if (!triggerId || typeof triggerId !== 'string') return;

    const doc = getDocument();
    if (!doc) return;

    const sanitizedTriggerId = triggerId.replace(/[^\w-]/g, '');
    if (sanitizedTriggerId !== triggerId) {
      console.warn(
        'Invalid triggerId provided. Only alphanumeric characters, underscores, and hyphens are allowed.',
      );
      return;
    }

    const triggerElement = doc.getElementById(sanitizedTriggerId);
    if (triggerElement) {
      const handleTriggerClick = () => {
        setIsChatOpen(!isChatOpen);
      };

      triggerElement.addEventListener('click', handleTriggerClick);

      if (isChatOpen) {
        triggerElement.classList.add('pointer-trigger-open');
      } else {
        triggerElement.classList.remove('pointer-trigger-open');
      }

      return () => {
        triggerElement.removeEventListener('click', handleTriggerClick);
      };
    }
  }, [triggerId, isChatOpen, setIsChatOpen]);

  return (
    <Popover
      open={isChatOpen}
      onOpenChange={setIsChatOpen}
      isMaximized={isMaximized}
      trigger={
        <Button
          variant="outline"
          size="icon"
          className={styles.triggerButton}
          style={triggerButtonStyle}
          data-custom-trigger={!!triggerId}
          data-widget-open={isChatOpen}>
          <div className={styles.iconContainer}>
            <ChevronDown
              className={`${styles.triggerIcon} ${isChatOpen ? styles.iconEnter : styles.iconExit}`}
              style={triggerIconStyle}
            />
            <TriggerIcon
              className={`${styles.triggerIcon} ${!isChatOpen ? styles.iconEnter : styles.iconExit}`}
              style={triggerIconStyle}
            />
          </div>
          <span className={styles.srOnly}>Open chat</span>
        </Button>
      }>
      <div className={styles.container} data-maximized={isMaximized}>
        <div className={styles.wrapper}>
          <div className={styles.content}>
            <div className={`${styles.slider} ${view === 'history' ? styles.sliderHistory : ''}`}>
              <div className={styles.mainPanel}>
                <ChatHeader
                  view="main"
                  onNewChat={handleNewChatSession}
                  onHistoryClick={handleHistoryClick}
                  onClose={() => setIsChatOpen(false)}
                  conversationTitle={conversationTitle || undefined}
                  isGeneratingTitle={isGeneratingTitle}
                  hasMessages={chatHistory.length > 0}
                  isMaximized={isMaximized}
                  onToggleSize={() => setIsMaximized(prev => !prev)}
                />
                {!currentConversationId && chatHistory.length === 0 && (
                  <LinkButtons
                    link1Text={content.link1Text}
                    link1Icon={content.link1Icon}
                    link1Url={content.link1Url}
                    link2Text={content.link2Text}
                    link2Icon={content.link2Icon}
                    link2Url={content.link2Url}
                    link3Text={content.link3Text}
                    link3Icon={content.link3Icon}
                    link3Url={content.link3Url}
                    link4Text={content.link4Text}
                    link4Icon={content.link4Icon}
                    link4Url={content.link4Url}
                  />
                )}
                <ChatMessages
                  messages={chatHistory}
                  userAvatar={getOrCreateUserAvatar()}
                  assistantLogo={pointerLogo}
                  onGuideStart={handleStartGuide}
                  onFeedback={(index, feedback) => handleFeedback(index, feedback)}
                  containerRef={chatContainerRef}
                  showSuggestions={false}
                  onSuggestionClick={handleItemClick}
                />
                <ChatInput
                  value={userInput}
                  onChange={setUserInput}
                  onSubmit={handleUserInput}
                  inputRef={inputRef}
                />
                <PoweredByPointer />
              </div>
              <div className={styles.historyPanel}>
                <ChatHeader
                  view="history"
                  onBack={handleBackToMain}
                  onNewChat={handleNewChatSession}
                  onHistoryClick={handleHistoryClick}
                  onClose={() => setIsChatOpen(false)}
                  isMaximized={isMaximized}
                  onToggleSize={() => setIsMaximized(prev => !prev)}
                />
                <div className={styles.historyContent}>
                  <SessionGroups
                    sessions={chatSessions}
                    editingSessionId={editingSessionId}
                    editingSessionTitle={editingSessionTitle}
                    hoveredSessionId={hoveredSessionId}
                    onSessionClick={handleChatSessionClick}
                    onEditClick={handleEditSession}
                    onDeleteClick={handleDeleteClick}
                    onTitleChange={setEditingSessionTitle}
                    onTitleUpdate={handleUpdateSession}
                    onMouseEnter={setHoveredSessionId}
                    onMouseLeave={() => setHoveredSessionId(null)}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </Popover>
  );
};
