import { getStorage } from '../index';

// Array of animal emojis for user avatars
export const ANIMAL_EMOJIS = [
  '🐶',
  '🐱',
  '🐭',
  '🐹',
  '🐰',
  '🦊',
  '🐻',
  '🐼',
  '🐨',
  '🐯',
  '🦁',
  '🐮',
  '🐷',
  '🐸',
  '🐙',
  '🦄',
  '🦒',
  '🦘',
  '🦔',
  '🐢',
];

/**
 * Gets the user's avatar from localStorage or creates a new one if it doesn't exist
 * @returns {string} The user's avatar emoji
 */
export const getOrCreateUserAvatar = (): string => {
  const storage = getStorage();
  const storedAvatar = storage.getItem('userAvatar');
  if (storedAvatar) {
    return storedAvatar;
  }
  const randomEmoji = ANIMAL_EMOJIS[Math.floor(Math.random() * ANIMAL_EMOJIS.length)];
  storage.setItem('userAvatar', randomEmoji);
  return randomEmoji;
};
