import type { ElementMapping, Step } from '@/sdk/types';

// Client → Server Events
export interface StartGuidePayload {
  message: string;
  conversationId: string;
  uiElements: ElementMapping[];
}

export interface StepCompletePayload {
  stepId: string;
  updatedUiElements: ElementMapping[];
}

// Server → Client Events
export interface GuideStep {
  id: string;
  position: string;
  instructions: string;
  action: {
    type: 'navigate' | 'click' | 'input' | 'select' | 'submit';
    path?: string;
  };
  purpose: string;
  state?: string;
  metadata?: {
    guideName?: string;
    page?: string;
    isLastStep: boolean;
  };
}

export interface GuideStepResponse {
  step: GuideStep;
  isComplete: boolean;
  currentStepIndex: number;
  totalSteps: number;
  guideId: string;
}

export interface GuideCompleteResponse {
  guideId: string;
  steps: GuideStep[];
  name: string;
  metadata?: GuideMetadata;
}

export interface GuideMetadata {
  initiatedPage: string;
  projectId?: string;
  knowledgeBaseId?: string;
}

export interface ErrorResponse {
  message: string;
  code?: string;
}

// Internal State Types
export interface GuideState {
  currentStepIndex: number;
  steps: Step[];
  name?: string;
  page?: string;
  conversationId: string;
  guideId?: string;
  timeoutId?: NodeJS.Timeout;
}

// Event Callbacks
export interface GuideSocketCallbacks {
  onGuideStep?: (response: GuideStepResponse) => void;
  onGuideComplete?: (response: GuideCompleteResponse) => void;
  onError?: (error: ErrorResponse) => void;
  onConnectionStateChange?: (connected: boolean) => void;
}

// Configuration
export interface GuideSocketConfig {
  projectId: string;
  apiUrl?: string;
  sessionId?: string;
  onGuideStep?: (response: GuideStepResponse) => void;
  onGuideComplete?: (response: GuideCompleteResponse) => void;
  onError?: (error: ErrorResponse) => void;
  onConnectionStateChange?: (connected: boolean) => void;
}

// Socket Events enum
export enum SocketEvents {
  // Client → Server
  START_GUIDE = 'startGuide',
  STEP_COMPLETE = 'stepComplete',
  PONG = 'pong',

  // Server → Client
  GUIDE_STEP = 'guideStep',
  GUIDE_COMPLETE = 'guideComplete',
  ERROR = 'error',
  PING = 'ping',

  // Socket.IO events
  CONNECT = 'connect',
  DISCONNECT = 'disconnect',
  CONNECT_ERROR = 'connect_error',
  RECONNECT = 'reconnect',
  RECONNECT_ATTEMPT = 'reconnect_attempt',
  RECONNECT_ERROR = 'reconnect_error',
  RECONNECT_FAILED = 'reconnect_failed',
}
